-- ACKS Arbiter — Canonical Database Schema
-- This file always reflects the current database state after all migrations.
-- Do NOT edit this file directly. Add a new migration in db/migrations/ instead.
-- Last migration applied: 150
--
-- To rebuild from scratch: delete campaign.db and relaunch the game.

CREATE TABLE IF NOT EXISTS schema_migrations (
    version INTEGER PRIMARY KEY,
    applied_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- Migration 034: Schema sweep markers
CREATE TABLE IF NOT EXISTS schema_sweep_markers (
    sweep_name TEXT PRIMARY KEY,
    applied_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- Migration 001: Initial schema
-- Creates all Tier 1 tables: campaigns, characters, parties, party_members,
-- character_conditions, character_proficiencies, inventory_items, character_spells,
-- hex_maps, hex_cells, domains.

CREATE TABLE IF NOT EXISTS campaigns (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    world_name TEXT NOT NULL DEFAULT '',
    calendar_day INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0, 1)),
    -- Migration 097: customs annual roll year-marker (§8.4).
    last_customs_roll_year INTEGER NOT NULL DEFAULT 0,
    -- Migration 155: the party the player was watching at last save; the
    -- session loader prefers it over the unordered LIMIT-1 pick. '' = none.
    last_active_party_id TEXT NOT NULL DEFAULT '',
    -- Migration 164: 'generated' (materialized from setting_* by SettingMaterializer)
    -- vs 'fixture' (TestContentSeeder). The two paths must never both run for one
    -- campaign. See gdd-setting-runtime-materialization.md §11.
    campaign_origin TEXT NOT NULL DEFAULT 'fixture'
        CHECK(campaign_origin IN ('fixture', 'generated')),
    -- Migration 175: the setting_settlements id the player chose as the start city on the
    -- review screen (Decision-K picker, M3-b). Centers the play window + spawns the party
    -- there. '' = auto-pick the largest market.
    start_settlement_id TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS characters (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    name TEXT NOT NULL,
    character_type TEXT NOT NULL DEFAULT 'pc'
        CHECK(character_type IN ('pc', 'henchman', 'npc')),
    persistence_tier TEXT NOT NULL DEFAULT 'full'
        CHECK(persistence_tier IN ('full', 'named', 'transient')),
    race TEXT NOT NULL DEFAULT 'human',
    character_class TEXT NOT NULL DEFAULT 'fighter',
    level INTEGER NOT NULL DEFAULT 1,
    xp INTEGER NOT NULL DEFAULT 0,
    -- Four ACKS 1e combat progression types. "crusader" is ACKS II only.
    combat_progression TEXT NOT NULL DEFAULT 'fighter'
        CHECK(combat_progression IN ('fighter', 'cleric', 'thief', 'mage')),
    strength INTEGER NOT NULL DEFAULT 10,
    intelligence INTEGER NOT NULL DEFAULT 10,
    wisdom INTEGER NOT NULL DEFAULT 10,
    dexterity INTEGER NOT NULL DEFAULT 10,
    constitution INTEGER NOT NULL DEFAULT 10,
    charisma INTEGER NOT NULL DEFAULT 10,
    hp_max INTEGER NOT NULL DEFAULT 1,
    hp_current INTEGER NOT NULL DEFAULT 1,
    armor_class INTEGER NOT NULL DEFAULT 0,
    attack_throw INTEGER NOT NULL DEFAULT 10,
    is_dead INTEGER NOT NULL DEFAULT 0 CHECK(is_dead IN (0, 1)),
    -- Migration 142: day_of_death = absolute day-count from
    -- Timekeeping.get_total_days() at the moment death was finalized;
    -- -1 means never died. death_cause encodes the kind of death:
    -- '' (unknown/combat), 'old_age', 'lost_head', 'cremated',
    -- 'disintegrated', 'combat'. Restore Life and Limb's days_dead_limit
    -- gate consumes day_of_death; the spell rejects targets whose
    -- death_cause is in {old_age, lost_head, cremated, disintegrated}.
    day_of_death INTEGER NOT NULL DEFAULT -1,
    death_cause TEXT NOT NULL DEFAULT '',
    is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0, 1)),
    employer_id TEXT REFERENCES characters(id),
    loyalty_score INTEGER,
    wage_cp_per_month INTEGER,
    -- Migration 005 additions
    save_petrification INTEGER NOT NULL DEFAULT 15,
    save_poison_death INTEGER NOT NULL DEFAULT 14,
    save_blast_breath INTEGER NOT NULL DEFAULT 16,
    save_staffs_wands INTEGER NOT NULL DEFAULT 16,
    save_spells INTEGER NOT NULL DEFAULT 17,
    base_movement INTEGER NOT NULL DEFAULT 120,
    hit_die_type TEXT NOT NULL DEFAULT '1d8',
    max_level INTEGER NOT NULL DEFAULT 14,
    xp_for_next_level INTEGER NOT NULL DEFAULT 2000,
    xp_adjustment_percent INTEGER NOT NULL DEFAULT 0,
    title TEXT NOT NULL DEFAULT '',
    alignment TEXT NOT NULL DEFAULT 'neutral',
    current_age INTEGER NOT NULL DEFAULT 0,
    age_category TEXT NOT NULL DEFAULT 'adult',
    languages TEXT NOT NULL DEFAULT '[]',
    personality TEXT NOT NULL DEFAULT '{}',
    is_incapacitated INTEGER NOT NULL DEFAULT 0,
    -- Migration 008 additions
    portrait_id TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now')),
    -- Migration 009 additions
    sex TEXT NOT NULL DEFAULT 'male' CHECK(sex IN ('male', 'female')),
    -- Migration 026 additions
    token_variant TEXT NOT NULL DEFAULT '',
    -- Migration 040: class-specific sub-selections (JSON dict)
    -- e.g. {"regional_origin": "jutland"} for barbarians,
    -- {"witch_tradition": "sylvan"} for witches.
    class_metadata TEXT NOT NULL DEFAULT '{}',
    -- Migration 126 (Urban Growth Stocking §11.4, Q-UGS-28): per-character POI
    -- affinity. Nullable: PC characters and itinerant NPCs are unanchored.
    home_poi_id TEXT REFERENCES settlement_pois(id) ON DELETE SET NULL,
    -- Migration 126 (Urban Growth Stocking §11.4, Q-UGS-29): NPC role enum.
    npc_role TEXT NOT NULL DEFAULT 'player'
        CHECK(npc_role IN (
            'player', 'henchman', 'specialist', 'baseline_placeholder',
            'stocked', 'named_npc', 'on_demand'
        )),
    -- Migration 145 (gdd-class-templates.md §6.4): which class template this
    -- character was created from. NULL for Path A picks, non-template builds,
    -- and generic NPCs. Reference-only (narration / inspection / analytics).
    origin_template_id TEXT DEFAULT NULL
);

-- Migration 120: structured permanent-wound records (Phase 10B.3 #6).
-- Wound rows are produced by both the Crime & Punishment resolver and the
-- Mortal Wounds resolver; WoundEffectAggregator reads them and propagates
-- mechanical effects into combat, social, spellcasting, and proficiency
-- resolvers per RAW.
CREATE TABLE IF NOT EXISTS character_permanent_wounds (
    id                   TEXT PRIMARY KEY,
    character_id         TEXT NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
    wound_kind           TEXT NOT NULL,
    source               TEXT NOT NULL DEFAULT '',
    applied_calendar_day INTEGER NOT NULL DEFAULT 0,
    notes                TEXT NOT NULL DEFAULT '',
    created_at           TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_character_permanent_wounds_character
    ON character_permanent_wounds(character_id);

CREATE TABLE IF NOT EXISTS parties (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    name TEXT NOT NULL DEFAULT 'The Party',
    current_map_id TEXT,
    current_hex_q INTEGER,
    current_hex_r INTEGER,
    current_location_type TEXT NOT NULL DEFAULT 'wilderness'
        CHECK(current_location_type IN ('wilderness', 'dungeon', 'settlement', 'sea')),
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    -- Migration 038: heraldry builder FK (NULL → backfilled at session load)
    heraldry_id TEXT REFERENCES party_heraldry(heraldry_id)
);

-- Migration 038: per-party heraldic shield.
CREATE TABLE IF NOT EXISTS party_heraldry (
    heraldry_id         TEXT PRIMARY KEY,
    shape_id            TEXT NOT NULL DEFAULT 'heater',
    division_id         TEXT NOT NULL DEFAULT 'plain',
    tincture_primary    TEXT NOT NULL DEFAULT '#dcdcdc',
    tincture_secondary  TEXT NOT NULL DEFAULT '#1a1a1a',
    ordinary_id         TEXT NOT NULL DEFAULT '',
    tincture_ordinary   TEXT NOT NULL DEFAULT '#dcdcdc',
    charge_id           TEXT NOT NULL DEFAULT '',
    tincture_charge     TEXT NOT NULL DEFAULT '#dcdcdc',
    created_at          TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS party_members (
    party_id TEXT NOT NULL REFERENCES parties(id),
    character_id TEXT NOT NULL REFERENCES characters(id),
    formation_slot TEXT NOT NULL DEFAULT 'middle'
        CHECK(formation_slot IN ('point', 'front', 'middle', 'rear')),
    -- Migration 022: grid-based formation (replaces formation_slot)
    formation_col INTEGER NOT NULL DEFAULT -1,
    formation_row INTEGER NOT NULL DEFAULT -1,
    joined_at TEXT NOT NULL DEFAULT (datetime('now')),
    PRIMARY KEY (party_id, character_id),
    -- Migration 035: enforce mutual exclusivity (one party per character)
    UNIQUE (character_id)
);

-- Migration 021: Party travel/exploration state
-- Migration 047: wilderness sustenance counters (exhaustion/starvation/dehydration,
-- water_units/ration_units, last_day_tick_round idempotency guard).
CREATE TABLE IF NOT EXISTS party_state (
    party_id TEXT PRIMARY KEY REFERENCES parties(id),
    marching_order TEXT NOT NULL DEFAULT '[]',
    is_lost INTEGER NOT NULL DEFAULT 0 CHECK(is_lost IN (0, 1)),
    is_force_marching INTEGER NOT NULL DEFAULT 0 CHECK(is_force_marching IN (0, 1)),
    force_march_days_used INTEGER NOT NULL DEFAULT 0,
    days_since_rest INTEGER NOT NULL DEFAULT 0,
    rations_days_remaining INTEGER NOT NULL DEFAULT 0,
    current_mount_type TEXT NOT NULL DEFAULT '',
    exhaustion_days INTEGER NOT NULL DEFAULT 0,
    starvation_days INTEGER NOT NULL DEFAULT 0,
    dehydration_days INTEGER NOT NULL DEFAULT 0,
    water_units INTEGER NOT NULL DEFAULT 0,
    ration_units INTEGER NOT NULL DEFAULT 0,
    last_day_tick_round INTEGER NOT NULL DEFAULT -1,
    -- Migration 131: camp state + per-day encounter gate (gdd-realtime-scheduler.md §4.3).
    is_camping INTEGER NOT NULL DEFAULT 0 CHECK(is_camping IN (0, 1)),
    camp_start_round INTEGER NOT NULL DEFAULT -1,
    camp_end_round INTEGER NOT NULL DEFAULT -1,
    camp_watch_assignments_json TEXT NOT NULL DEFAULT '[]',
    camp_armed_sleepers_json TEXT NOT NULL DEFAULT '[]',
    last_encounter_trigger_day INTEGER NOT NULL DEFAULT -1,
    -- Migration 155: deferred encounter decision for a background party
    -- (switch-first flow). var_to_str-serialized Dictionary; '' = none.
    pending_encounter TEXT NOT NULL DEFAULT '',
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- Migration 048: Weather state cache (Wilderness closure Phase 2).
-- Lazy per-hex/per-day records keyed on (campaign_id, hex_q, hex_r,
-- julian_day, year). See WeatherCache and WeatherGenerator.
CREATE TABLE IF NOT EXISTS weather_states (
    campaign_id TEXT NOT NULL,
    hex_q INTEGER NOT NULL,
    hex_r INTEGER NOT NULL,
    julian_day INTEGER NOT NULL,
    year INTEGER NOT NULL DEFAULT 1,
    temperature_band INTEGER NOT NULL DEFAULT 3,
    atmosphere TEXT NOT NULL DEFAULT 'calm',
    precipitation_level INTEGER NOT NULL DEFAULT 0,
    precipitation_type TEXT NOT NULL DEFAULT 'none',
    wind_level INTEGER NOT NULL DEFAULT 2,
    visibility_multiplier REAL NOT NULL DEFAULT 1.0,
    produces_mud INTEGER NOT NULL DEFAULT 0 CHECK(produces_mud IN (0, 1)),
    generated_at TEXT NOT NULL DEFAULT (datetime('now')),
    PRIMARY KEY (campaign_id, hex_q, hex_r, julian_day, year)
);

CREATE INDEX IF NOT EXISTS idx_weather_states_campaign_day
    ON weather_states (campaign_id, julian_day);

-- Migration 049: Party sustenance daily log (Wilderness closure Phase 3).
-- Append-only audit of daily food/water consumption + HP loss. Drives the
-- Notebook Party-tab last-7-days panel.
CREATE TABLE IF NOT EXISTS party_sustenance_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    party_id TEXT NOT NULL REFERENCES parties(id),
    day_index INTEGER NOT NULL,
    food_consumed INTEGER NOT NULL DEFAULT 0,
    water_consumed INTEGER NOT NULL DEFAULT 0,
    food_foraged INTEGER NOT NULL DEFAULT 0,
    water_foraged INTEGER NOT NULL DEFAULT 0,
    hp_lost INTEGER NOT NULL DEFAULT 0,
    starvation_days_after INTEGER NOT NULL DEFAULT 0,
    dehydration_days_after INTEGER NOT NULL DEFAULT 0,
    exhaustion_days_after INTEGER NOT NULL DEFAULT 0,
    notes TEXT NOT NULL DEFAULT '',
    logged_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_party_sustenance_log_party_day
    ON party_sustenance_log (party_id, day_index DESC);

-- Migration 050: POI / Lair discovery (Wilderness closure Phase 4).
-- Per le_wilderness_lair_rules.xml — lairs are dynamic POIs revealed via the
-- abstract search procedure (1d20 vs target derived from daily wilderness
-- movement). Wilderness POIs (sacred sites, ruins — see gdd-poi-generation.md)
-- share a discovered-flag gating model.
-- Migration 152: lazy lair placement (gdd-lair-discovery.md 2026-05-27).
-- Placement IS discovery — there is no `discovered` flag. Lairs are created
-- only by wandering-encounter substitution or a successful dedicated search,
-- via the Lair Generator (stubbed). cleared_at_round NULL = uncleared (gates
-- Build Stronghold per le_wilderness_lair_rules.xml §securing_land L31).
CREATE TABLE IF NOT EXISTS lairs (
    lair_id            TEXT    PRIMARY KEY,
    campaign_id        TEXT    NOT NULL REFERENCES campaigns(id),
    map_id             TEXT    NOT NULL REFERENCES hex_maps(id),
    hex_q              INTEGER NOT NULL,
    hex_r              INTEGER NOT NULL,
    monster_group      TEXT    NOT NULL DEFAULT '',
    monster_count      INTEGER NOT NULL DEFAULT 0,
    placed_via         TEXT    NOT NULL DEFAULT ''
        CHECK(placed_via IN ('', 'wandering_substitution', 'search', 'legacy')),
    created_at_round   INTEGER NOT NULL DEFAULT 0,
    cleared_at_round   INTEGER,
    treasure_type      TEXT    NOT NULL DEFAULT '',
    treasure_hoard_json TEXT   NOT NULL DEFAULT '{}',
    lair_layout_seed   INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS idx_lairs_hex
    ON lairs(campaign_id, map_id, hex_q, hex_r);

-- Migration 152: per-hex lazy lair bookkeeping (gdd-lair-discovery.md §3.1).
-- Lives in a keyed side-table rather than on hex_cells because save_hex_map()
-- INSERT-OR-REPLACEs every cell row on each fog save, which would clobber
-- handler-written lair state. lair_budget NULL = not yet rolled (lazy).
-- surveyed_total is the player-displayed denominator (true budget on a normal
-- Survey success, false value on an unmodified-1); NULL = never surveyed.
CREATE TABLE IF NOT EXISTS hex_lair_state (
    campaign_id                 TEXT    NOT NULL REFERENCES campaigns(id),
    map_id                      TEXT    NOT NULL REFERENCES hex_maps(id),
    hex_q                       INTEGER NOT NULL,
    hex_r                       INTEGER NOT NULL,
    lair_budget                 INTEGER,
    lair_budget_rolled_at_round INTEGER,
    lairs_placed_count          INTEGER NOT NULL DEFAULT 0,
    unrevealed_lair_types       TEXT    NOT NULL DEFAULT '[]',
    surveyed_total              INTEGER,
    PRIMARY KEY (campaign_id, map_id, hex_q, hex_r)
);

CREATE TABLE IF NOT EXISTS pois (
    poi_id               TEXT    PRIMARY KEY,
    campaign_id          TEXT    NOT NULL REFERENCES campaigns(id),
    map_id               TEXT    NOT NULL REFERENCES hex_maps(id),
    hex_q                INTEGER NOT NULL,
    hex_r                INTEGER NOT NULL,
    poi_type             TEXT    NOT NULL DEFAULT 'unknown',
    name                 TEXT    NOT NULL DEFAULT '',
    discovered           INTEGER NOT NULL DEFAULT 0 CHECK(discovered IN (0, 1)),
    discovered_at_round  INTEGER NOT NULL DEFAULT 0,
    faction_id           TEXT    NOT NULL DEFAULT '',
    seed                 INTEGER NOT NULL DEFAULT 0,
    -- Migration 168: self-contained context + rumor seeds (6-mile-generated POIs
    -- have no setting_poi_seeds row to read back from). JSON.
    context              TEXT    NOT NULL DEFAULT '{}',
    rumor_seeds          TEXT    NOT NULL DEFAULT '[]'
);

CREATE INDEX IF NOT EXISTS idx_pois_hex
    ON pois(campaign_id, map_id, hex_q, hex_r);

-- Migration 051: Survey progress per (party, hex) (Wilderness closure Phase 4).
-- Per le_wilderness_lair_rules.xml §land_surveying — Land Surveying assessment
-- target is 18+ base, +4 cumulative per successful hex search the party has
-- conducted in the same hex. last_estimate_correct = 0 marks a false reading
-- from a natural-1.
CREATE TABLE IF NOT EXISTS survey_progress (
    campaign_id            TEXT    NOT NULL REFERENCES campaigns(id),
    map_id                 TEXT    NOT NULL REFERENCES hex_maps(id),
    party_id               TEXT    NOT NULL REFERENCES parties(id),
    hex_q                  INTEGER NOT NULL,
    hex_r                  INTEGER NOT NULL,
    successful_searches    INTEGER NOT NULL DEFAULT 0,
    last_search_round      INTEGER NOT NULL DEFAULT -1,
    last_estimate          INTEGER NOT NULL DEFAULT -1,
    last_estimate_correct  INTEGER NOT NULL DEFAULT 1
        CHECK(last_estimate_correct IN (0, 1)),
    PRIMARY KEY (campaign_id, map_id, party_id, hex_q, hex_r)
);

-- Migration 052: Tracking & pursuit state (Wilderness closure Phase 5).
-- Per acore_proficiencies_rules_and_catalog.xml Tracking entry and
-- acore_adventures_and_encounters.xml §chases_in_the_wilderness.
CREATE TABLE IF NOT EXISTS tracking_sessions (
    session_id              TEXT    PRIMARY KEY,
    campaign_id             TEXT    NOT NULL REFERENCES campaigns(id),
    party_id                TEXT    NOT NULL REFERENCES parties(id),
    target_kind             TEXT    NOT NULL DEFAULT 'creature_group'
        CHECK(target_kind IN ('creature_group', 'character', 'caravan')),
    target_label            TEXT    NOT NULL DEFAULT '',
    target_size             INTEGER NOT NULL DEFAULT 1,
    started_at_round        INTEGER NOT NULL DEFAULT 0,
    started_terrain         TEXT    NOT NULL DEFAULT 'clear',
    weather_decay_total     REAL    NOT NULL DEFAULT 0.0,
    last_check_round        INTEGER NOT NULL DEFAULT -1,
    closed                  INTEGER NOT NULL DEFAULT 0 CHECK(closed IN (0, 1)),
    closed_reason           TEXT    NOT NULL DEFAULT ''
        CHECK(closed_reason IN ('', 'success', 'lost_trail', 'abandoned',
                                 'caught_up', 'engaged'))
);

CREATE INDEX IF NOT EXISTS idx_tracking_sessions_party
    ON tracking_sessions(campaign_id, party_id, closed);

CREATE TABLE IF NOT EXISTS pursuit_states (
    pursuit_id              TEXT    PRIMARY KEY,
    campaign_id             TEXT    NOT NULL REFERENCES campaigns(id),
    party_id                TEXT    NOT NULL REFERENCES parties(id),
    pursuer_label           TEXT    NOT NULL DEFAULT '',
    pursuer_size            INTEGER NOT NULL DEFAULT 1,
    pursuer_speed_advantage INTEGER NOT NULL DEFAULT 0,
    started_at_round        INTEGER NOT NULL DEFAULT 0,
    last_check_round        INTEGER NOT NULL DEFAULT -1,
    days_in_pursuit         INTEGER NOT NULL DEFAULT 0,
    closed                  INTEGER NOT NULL DEFAULT 0 CHECK(closed IN (0, 1)),
    closed_reason           TEXT    NOT NULL DEFAULT ''
        CHECK(closed_reason IN ('', 'evaded', 'caught', 'abandoned'))
);

CREATE INDEX IF NOT EXISTS idx_pursuit_states_party
    ON pursuit_states(campaign_id, party_id, closed);

-- Migration 053: Specialists (Wilderness closure Phase 6).
-- Per acore_equipment.xml §specialists and le_wilderness_lair_rules.xml §hirelings.
-- Non-adventuring monthly hires; exempt from henchman cap.
-- Migration 153 widened kind with 'sage' (gdd-specialists.md v2.0 dual-path).
CREATE TABLE IF NOT EXISTS specialists (
    specialist_id        TEXT    PRIMARY KEY,
    campaign_id          TEXT    NOT NULL REFERENCES campaigns(id),
    party_id             TEXT    NOT NULL REFERENCES parties(id),
    kind                 TEXT    NOT NULL DEFAULT 'pathfinder'
        CHECK(kind IN ('pathfinder', 'land_surveyor', 'sage')),
    name                 TEXT    NOT NULL DEFAULT '',
    settlement_id        TEXT    NOT NULL DEFAULT '',
    hired_at_round       INTEGER NOT NULL DEFAULT 0,
    monthly_wage_cp      INTEGER NOT NULL DEFAULT 2500,
    last_paid_round      INTEGER NOT NULL DEFAULT -1,
    unpaid_months        INTEGER NOT NULL DEFAULT 0,
    closed               INTEGER NOT NULL DEFAULT 0 CHECK(closed IN (0, 1)),
    closed_reason        TEXT    NOT NULL DEFAULT ''
        CHECK(closed_reason IN ('', 'dismissed', 'unpaid', 'departed'))
);

CREATE INDEX IF NOT EXISTS idx_specialists_party
    ON specialists(campaign_id, party_id, closed);

-- Migration 153: specialist commissions (gdd-specialists.md v2.0 §5 — the
-- in-settlement service path; dual-path ruling 2026-06-11). Status is LAZY:
-- ready iff party_time >= completes_at_round. result_payload is fixed at
-- commission time (report text or item_key).
CREATE TABLE IF NOT EXISTS specialist_commissions (
    commission_id         TEXT    PRIMARY KEY,
    campaign_id           TEXT    NOT NULL REFERENCES campaigns(id),
    party_id              TEXT    NOT NULL REFERENCES parties(id),
    settlement_id         TEXT    NOT NULL,
    kind                  TEXT    NOT NULL,
    service_id            TEXT    NOT NULL,
    service_label         TEXT    NOT NULL DEFAULT '',
    subject               TEXT    NOT NULL DEFAULT '',
    cost_cp               INTEGER NOT NULL DEFAULT 0,
    commissioned_at_round INTEGER NOT NULL DEFAULT 0,
    completes_at_round    INTEGER NOT NULL DEFAULT 0,
    result_kind           TEXT    NOT NULL DEFAULT 'report'
        CHECK(result_kind IN ('report', 'item')),
    result_payload        TEXT    NOT NULL DEFAULT '',
    collected             INTEGER NOT NULL DEFAULT 0 CHECK(collected IN (0, 1)),
    collected_at_round    INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS idx_specialist_commissions_party
    ON specialist_commissions(campaign_id, party_id, collected);

CREATE TABLE IF NOT EXISTS character_conditions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    character_id TEXT NOT NULL REFERENCES characters(id),
    condition_name TEXT NOT NULL,
    applied_at_round INTEGER,
    expires_at_round INTEGER,
    source_id TEXT
);

CREATE TABLE IF NOT EXISTS character_proficiencies (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    character_id TEXT NOT NULL REFERENCES characters(id),
    proficiency_key TEXT NOT NULL,
    rank INTEGER NOT NULL DEFAULT 1,
    slot_type TEXT NOT NULL DEFAULT 'general'
        CHECK(slot_type IN ('class', 'general')),
    -- Migration 007 additions
    selections_count INTEGER NOT NULL DEFAULT 1,
    specialization TEXT NOT NULL DEFAULT ''
);

-- encumbrance_units: weight in 1/1000-stone units (1 stone = 1000 units = ~10 lbs)
-- Examples: dagger=167, sword=1000, plate armour=6000, coin/gem=1
CREATE TABLE IF NOT EXISTS inventory_items (
    id TEXT PRIMARY KEY,
    character_id TEXT NOT NULL REFERENCES characters(id),
    item_key TEXT NOT NULL,
    name TEXT NOT NULL,
    quantity INTEGER NOT NULL DEFAULT 1,
    encumbrance_units INTEGER NOT NULL DEFAULT 0,
    slot TEXT NOT NULL DEFAULT 'pack'
        -- Migration 151: paper-doll slots (gdd-character-tab.md §3.4). Body
        -- armor lives in 'armor' (coexists with 'torso_clothing'); 'body' is
        -- now ONLY creature barding. 'accessory_1'..'_5' are legacy (no longer
        -- surfaced by the paper-doll UI; kept so old rows stay valid).
        CHECK(slot IN (
            'hands_main', 'hands_off',
            'head', 'neck', 'arms', 'armor',
            'torso_clothing', 'legs_clothing',
            'belt', 'feet', 'hands_worn', 'cloak',
            'ring_l', 'ring_r', 'quiver',
            'body',
            'accessory_1', 'accessory_2', 'accessory_3', 'accessory_4', 'accessory_5',
            'pack', 'mount'
        )),
    is_equipped INTEGER NOT NULL DEFAULT 0 CHECK(is_equipped IN (0, 1)),
    notes TEXT NOT NULL DEFAULT '',
    -- Migration 005 additions
    item_category TEXT NOT NULL DEFAULT 'gear',
    is_magical INTEGER NOT NULL DEFAULT 0,
    magical_bonus INTEGER NOT NULL DEFAULT 0,
    weapon_damage TEXT NOT NULL DEFAULT '',
    armor_ac_bonus INTEGER NOT NULL DEFAULT 0,
    is_heavy INTEGER NOT NULL DEFAULT 0,
    -- Migration 006 additions
    damage_type TEXT NOT NULL DEFAULT 'physical',
    material TEXT NOT NULL DEFAULT '',
    -- Migration 010 additions
    container_id TEXT NOT NULL DEFAULT '',
    -- Migration 011: slot expanded to include feet, hands_worn, accessory_1-5
    -- Migration 012 additions
    uses_remaining INTEGER NOT NULL DEFAULT -1,
    -- Migration 021 additions
    party_id TEXT REFERENCES parties(id) DEFAULT NULL,
    -- Migration 023 additions
    creature_id TEXT REFERENCES trained_creatures(id) DEFAULT NULL,
    -- Migration 024 additions
    vehicle_id TEXT REFERENCES draft_vehicles(id) DEFAULT NULL,
    -- Migration 032 additions
    location_cache_id TEXT REFERENCES location_caches(id) ON DELETE CASCADE DEFAULT NULL,
    -- Migration 134 additions
    -- -1 = value by item_key -> EquipmentCatalog.cost_cp (mundane equipment);
    -- >= 0 = authoritative per-item value in cp (gems, jewelry, trade goods, etc.)
    value_cp INTEGER NOT NULL DEFAULT -1,
    -- Migration 136 additions
    -- is_cursed = 1 makes the equip-state path refuse to UNEQUIP this item per
    -- RAW (acore_treasure_and_magic_items_rules.xml:233-237). Equipping is
    -- unrestricted (the owner doesn't know it's cursed). Negative magical_bonus
    -- on a cursed item already applies penalties through the same +N paths.
    is_cursed INTEGER NOT NULL DEFAULT 0 CHECK(is_cursed IN (0, 1)),
    -- Migration 138 additions
    -- Container-item runtime state for the cell-based treasure containers arc
    -- (gdd-treasure-item-backing.md §15). chest / barrel / sack hoards
    -- materialize into a backing inventory_items row that IS the container;
    -- the container's lock + trap state lives here so the per-cell interaction
    -- layer can gate opening without re-reading the source treasure_hoards
    -- row (which is_looted=1 after materialization).
    is_locked INTEGER NOT NULL DEFAULT 0 CHECK(is_locked IN (0, 1)),
    is_trapped INTEGER NOT NULL DEFAULT 0 CHECK(is_trapped IN (0, 1)),
    -- Migration 139 additions
    -- Extradimensional flag for magic containers (Bag of Holding etc.).
    -- When set on a container item, EncumbranceCalculator computes the
    -- container's aggregate weight as its OWN weight only (contents do not
    -- contribute regardless of how heavy they are). Default 0 = mundane
    -- container (aggregate = own weight + sum of contents).
    is_extradimensional INTEGER NOT NULL DEFAULT 0 CHECK(is_extradimensional IN (0, 1)),
    -- Migration 140 additions
    -- Bag of Devouring timer state. -1 = no active timer; >= 0 = future turn
    -- (per Timekeeping.get_total_turns()) at which contents are devoured.
    -- Activates on first item placed in empty bag; resets when bag empties
    -- (via removal or devour). See BagOfDevouringService for the mechanic.
    devouring_at_turn INTEGER NOT NULL DEFAULT -1,
    -- Migration 141 additions
    -- Container capacity in encumbrance units (1 unit = 1/1000 stone).
    -- 0 = no enforcement (V1 default for mundane containers). >0 = transfer
    -- paths refuse to add items that would push the container's total
    -- contents weight over this limit. Stamped from magic item catalog's
    -- container_behavior.capacity_units at materialization time.
    capacity_units INTEGER NOT NULL DEFAULT 0,
    -- Migration 149 additions
    -- Per-row consumable depletion state for the provisions system
    -- (rations / water / fodder — gdd-rations-foodstuffs.md, Option B).
    -- -1 = uninitialized / not a tracked consumable; the ProvisionsLedger
    --      treats an uninitialized food/water/fodder row as FULL
    --      (remaining person-days = quantity x catalog.consumable_person_days).
    -- >=0 = explicit person-days of consumable left in this row. Food/fodder
    --       rows are deleted at 0 (eaten); water containers persist empty at 0
    --       (refilled at a source). Distinct from uses_remaining (torch turns).
    consumable_units_remaining INTEGER NOT NULL DEFAULT -1
);

-- trained_creatures: companion animals (mounts, war animals, pack animals, etc.).
-- Stats derived from monster_catalog.json via species_id at runtime.
-- Migration 023 addition.
CREATE TABLE IF NOT EXISTS trained_creatures (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    -- Migration 035: party_id is required (NOT NULL)
    party_id TEXT NOT NULL REFERENCES parties(id),
    species_id TEXT NOT NULL,
    purchase_item_key TEXT NOT NULL DEFAULT '',
    name TEXT NOT NULL DEFAULT '',
    role TEXT NOT NULL DEFAULT 'L'
        CHECK(role IN ('M', 'WM', 'G', 'H', 'D', 'L', 'WB')),
    tricks_known TEXT NOT NULL DEFAULT '[]',
    trick_limit INTEGER NOT NULL DEFAULT 5,
    morale INTEGER NOT NULL DEFAULT 0,
    handler_id TEXT REFERENCES characters(id) DEFAULT NULL,
    introduced_handlers TEXT NOT NULL DEFAULT '[]',
    hp_current INTEGER NOT NULL DEFAULT 1,
    hp_max INTEGER NOT NULL DEFAULT 1,
    training_complete INTEGER NOT NULL DEFAULT 1 CHECK(training_complete IN (0, 1)),
    is_alive INTEGER NOT NULL DEFAULT 1 CHECK(is_alive IN (0, 1)),
    formation_col INTEGER NOT NULL DEFAULT -1,
    formation_row INTEGER NOT NULL DEFAULT -1,
    -- Migration 150 additions
    -- Per-animal fodder-starvation counter for the provisions system
    -- (gdd-rations-foodstuffs.md Phase 3). Days the creature has gone without
    -- fodder AND without grazing/hunting. Mirrors the PC starvation curve:
    -- 0-2 grace, then 1 hp/day. Resets to 0 on any day it is fed or grazes.
    fodder_starvation_days INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- draft_vehicles: carts and wagons hitched to draft teams.
-- Capacity depends on the draft team composition (see acore_equipment.xml:623-628).
-- Migration 024 addition.
CREATE TABLE IF NOT EXISTS draft_vehicles (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    party_id TEXT NOT NULL REFERENCES parties(id),
    item_key TEXT NOT NULL,
    name TEXT NOT NULL DEFAULT '',
    hitched_creatures TEXT NOT NULL DEFAULT '[]',
    is_destroyed INTEGER NOT NULL DEFAULT 0 CHECK(is_destroyed IN (0, 1)),
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- character_spells: active spell repertoire for all casters.
-- is_in_repertoire is always 1 for new rows (enforced by app logic).
-- is_memorized and memorized_slots are legacy; use character_spell_slots_expended instead.
CREATE TABLE IF NOT EXISTS character_spells (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    character_id TEXT NOT NULL REFERENCES characters(id),
    spell_key TEXT NOT NULL,
    spell_level INTEGER NOT NULL,
    is_memorized INTEGER NOT NULL DEFAULT 0 CHECK(is_memorized IN (0, 1)),
    is_in_repertoire INTEGER NOT NULL DEFAULT 1 CHECK(is_in_repertoire IN (0, 1)),
    memorized_slots INTEGER NOT NULL DEFAULT 0
);

-- Migration 018: Arcane spell formula tracking
-- Arcane only: spells for which the character possesses the formula.
-- Distinct from active repertoire (character_spells). Enables "known but not active" state.
CREATE TABLE IF NOT EXISTS character_spell_formulas (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    character_id TEXT NOT NULL REFERENCES characters(id),
    spell_key TEXT NOT NULL,
    spell_level INTEGER NOT NULL,
    UNIQUE(character_id, spell_key)
);

-- Migration 018: Daily expended spell slot tracking per level.
-- Replaces the per-spell is_memorized proxy. Cleared on rest.
CREATE TABLE IF NOT EXISTS character_spell_slots_expended (
    character_id TEXT NOT NULL REFERENCES characters(id),
    spell_level INTEGER NOT NULL,
    expended INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (character_id, spell_level)
);

CREATE TABLE IF NOT EXISTS hex_maps (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    name TEXT NOT NULL,
    scale TEXT NOT NULL CHECK(scale IN ('campaign_24mi', 'regional_6mi', 'local_15mi')),
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    -- Migration 119: cross-scale linkage. NULL parent_map_id = top-level map.
    -- For an inset, parent_anchor_(q,r) is the parent-map hex this child's
    -- (0,0) corresponds to, and parent_hex_footprint is a JSON list of
    -- parent-map [q,r] pairs that this inset covers. The "child scale must be
    -- finer than parent scale" rule is enforced at the repository boundary,
    -- not in SQL.
    parent_map_id TEXT REFERENCES hex_maps(id),
    parent_anchor_q INTEGER,
    parent_anchor_r INTEGER,
    parent_hex_footprint TEXT NOT NULL DEFAULT '[]',
    -- Migration 177: the cliff-detection threshold (adaptive percentile) pinned at the
    -- FIRST build of a regional_6mi map, reused on frontier growth so cliffs stay stable
    -- as the map grows (gdd-region-zoom-in.md §6). NULL → fall back to adaptive.
    cliff_threshold REAL
);

-- fog_state is per-campaign (scoped through hex_maps.campaign_id)
CREATE TABLE IF NOT EXISTS hex_cells (
    map_id TEXT NOT NULL REFERENCES hex_maps(id),
    q INTEGER NOT NULL,
    r INTEGER NOT NULL,
    elevation TEXT NOT NULL DEFAULT 'flat'
        CHECK(elevation IN ('flat', 'hills', 'mountains')),
    biome TEXT NOT NULL DEFAULT 'clear'
        CHECK(biome IN ('clear', 'woods', 'jungle', 'swamp', 'desert')),
    biome_subtype TEXT NOT NULL DEFAULT ''
        CHECK(biome_subtype IN (
            '',
            'forest_dense', 'forest_taiga',
            'mountains_volcanic', 'mountains_glacial',
            'clear_tundra', 'clear_savanna', 'clear_grassland',
            'clear_steppe', 'clear_scrub',
            'desert_badlands'
        )),
    water TEXT NOT NULL DEFAULT ''
        CHECK(water IN ('', 'ocean', 'lake')),
    civilization TEXT NOT NULL DEFAULT 'wilderness'
        CHECK(civilization IN ('civilized', 'borderlands', 'wilderness')),
    has_city INTEGER NOT NULL DEFAULT 0 CHECK(has_city IN (0, 1)),
    original_biome TEXT NOT NULL DEFAULT '',
    fog_state TEXT NOT NULL DEFAULT 'hidden'
        CHECK(fog_state IN ('hidden', 'explored', 'visible')),
    -- Migration 165: raw continuous elevation (≈0..1) from setting gen, persisted
    -- for the future 2D→3D wilderness renderer (gdd-wilderness-hex-3d.md). 0.0 =
    -- legacy / unknown (fixture maps).
    elevation_raw REAL NOT NULL DEFAULT 0.0,
    PRIMARY KEY (map_id, q, r)
);

-- Migration 020 + 130: Hex overlays (roads only — rivers are now first-class
-- edge entities in hex_river_edges per gdd-terrain-system.md §3.6).
-- Edge numbering: 0=N, 1=NE, 2=SE, 3=S, 4=SW, 5=NW (clockwise from North).
CREATE TABLE IF NOT EXISTS hex_overlays (
    map_id TEXT NOT NULL,
    q INTEGER NOT NULL,
    r INTEGER NOT NULL,
    overlay_type TEXT NOT NULL CHECK(overlay_type IN ('road')),
    edges TEXT NOT NULL DEFAULT '[]',
    flow_exit INTEGER NOT NULL DEFAULT -1,
    PRIMARY KEY (map_id, q, r, overlay_type),
    FOREIGN KEY (map_id) REFERENCES hex_maps(id)
);

-- Migration 130: River edges as first-class entities. Each row is one river
-- segment along the shared edge between two adjacent hexes. The lex-lower
-- (q, r) hex owns the entry; the neighbor is implied by `edge`. See
-- gdd-terrain-system.md §3.6 for the canonical ownership rule and field
-- semantics.
CREATE TABLE IF NOT EXISTS hex_river_edges (
    map_id          TEXT    NOT NULL REFERENCES hex_maps(id),
    hex_q           INTEGER NOT NULL,
    hex_r           INTEGER NOT NULL,
    edge            INTEGER NOT NULL CHECK(edge BETWEEN 0 AND 5),
    flow_clockwise  INTEGER NOT NULL DEFAULT 1 CHECK(flow_clockwise IN (0, 1)),
    navigability    TEXT    NOT NULL DEFAULT 'river_craft'
        CHECK(navigability IN ('none', 'small_craft', 'river_craft', 'large_craft')),
    crossing        TEXT    NOT NULL DEFAULT 'none'
        CHECK(crossing IN ('none', 'bridge', 'ford', 'ferry')),
    -- Migration 167: river width class from setting gen (free text; '' = unknown).
    width_category  TEXT    NOT NULL DEFAULT '',
    PRIMARY KEY (map_id, hex_q, hex_r, edge)
);

CREATE INDEX IF NOT EXISTS idx_hex_river_edges_owner
    ON hex_river_edges(map_id, hex_q, hex_r);

-- Migration 176: cliff / canyon edges — impassable elevation gradients
-- (gdd-cliffs-canyons.md §3). Per-edge feature mirroring hex_river_edges.
CREATE TABLE IF NOT EXISTS hex_cliff_edges (
    map_id       TEXT    NOT NULL REFERENCES hex_maps(id),
    hex_q        INTEGER NOT NULL,
    hex_r        INTEGER NOT NULL,
    edge         INTEGER NOT NULL CHECK(edge BETWEEN 0 AND 5),
    cliff_type   TEXT    NOT NULL DEFAULT 'cliff'
        CHECK(cliff_type IN ('cliff', 'canyon')),
    height_ft    INTEGER NOT NULL DEFAULT 0,
    high_side    INTEGER NOT NULL DEFAULT 0 CHECK(high_side IN (0, 1)),
    PRIMARY KEY (map_id, hex_q, hex_r, edge)
);

CREATE INDEX IF NOT EXISTS idx_hex_cliff_edges_owner
    ON hex_cliff_edges(map_id, hex_q, hex_r);

-- Migration 166: runtime `roads` as first-class entities (ordered hex path + class
-- + purpose + name). hex_overlays carries per-cell render geometry; this carries
-- the road entity so the game knows WHERE roads are and WHAT they are, and 6-mile
-- zoom-in can add new roads. Mirrors generator-side setting_roads.
CREATE TABLE IF NOT EXISTS roads (
    id            TEXT    PRIMARY KEY,
    campaign_id   TEXT    NOT NULL REFERENCES campaigns(id),
    map_id        TEXT    NOT NULL REFERENCES hex_maps(id),
    hexes         TEXT    NOT NULL DEFAULT '[]',
    road_class    TEXT    NOT NULL DEFAULT 'road'
        CHECK(road_class IN ('highway', 'road', 'track')),
    purpose       TEXT    NOT NULL DEFAULT '',
    name          TEXT    NOT NULL DEFAULT '',
    created_at    TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_roads_map ON roads(map_id);

CREATE TABLE IF NOT EXISTS domains (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    name TEXT NOT NULL,
    owner_character_id TEXT REFERENCES characters(id),
    location_map_id TEXT REFERENCES hex_maps(id),
    location_hex_q INTEGER,
    location_hex_r INTEGER,
    -- Three ACKS territory classifications only
    territory_type TEXT NOT NULL DEFAULT 'wilderness'
        CHECK(territory_type IN ('civilized', 'borderlands', 'wilderness')),
    -- Migration 097 (Q-MERC-15 Option A): urban_families relocated from
    -- domains to settlement_entrances. SoT lives on the settlement.
    peasant_families INTEGER NOT NULL DEFAULT 0,
    morale INTEGER NOT NULL DEFAULT 0,
    garrison_troops INTEGER NOT NULL DEFAULT 0,
    -- Migration 174: denormalized display-ready garrison (JSON: gp + per-unit-type
    -- counts) from the JJ Step-10 model (families × {2/3/4 gp by territory} → troops,
    -- ~25% vet). See gdd-region-zoom-in §5.6d. '{}' = no garrison.
    garrison_composition TEXT NOT NULL DEFAULT '{}',
    revenue_cp INTEGER NOT NULL DEFAULT 0,
    expenses_cp INTEGER NOT NULL DEFAULT 0,
    net_income_cp INTEGER NOT NULL DEFAULT 0,
    domain_xp_this_month INTEGER NOT NULL DEFAULT 0,
    -- Migration 025: ruler used in reputation cascade (ruler -> domain -> settlement)
    ruler_npc_id TEXT REFERENCES characters(id),
    -- Migration 056: Domain economy extensions (Domain Phase 0)
    religion TEXT NOT NULL DEFAULT '',
    -- Migration 128 (Phase 11D.3 / gdd-religion-conversion.md §4.1):
    -- `religion` is the DECLARED religion (the ruler's stated faith);
    -- `effective_religion` is the PRACTICED religion (what the populace
    -- actually worships). They diverge only during an active conversion arc
    -- (domain_religion_conversion.status='active'). Alignment is derived from
    -- effective_religion, not from religion — so the alignment penalty per
    -- acore_axioms L467-470 reflects the original alignment for the whole arc.
    effective_religion TEXT NOT NULL DEFAULT '',
    -- Migration 129 (Phase 11D.5 / gdd-tribal-warriors.md §4.1):
    -- Dormant tribal-warrior pool. Seeded at clanhold establishment to
    -- peasant_families; civilized domains hold it at 0. Maintained by
    -- levy / stand-down / casualty / population-change paths. Per the
    -- v1.2 design (Q-TW-7 resolution): casualties leave a permanent gap;
    -- population growth refills toward `peasant_families - levied`;
    -- dead warriors cannot replace themselves.
    available_tribal_warriors INTEGER NOT NULL DEFAULT 0,
    alignment TEXT NOT NULL DEFAULT 'neutral'
        CHECK(alignment IN ('lawful', 'neutral', 'chaotic')),
    tax_rate_cp_per_family INTEGER NOT NULL DEFAULT 200,
    liturgy_rate_cp_per_family INTEGER NOT NULL DEFAULT 100,
    tithe_rate_cp_per_family INTEGER NOT NULL DEFAULT 100,
    tribute_out_owed INTEGER NOT NULL DEFAULT 0,
    -- Migration 127 (Phase 11D.1): `is_chaotic_domain` DROPPED; replaced by
    -- the orthogonal `domain_style` column below + existing `alignment`.
    -- See gdd-domain-style-and-alignment.md §6 and §4 for the two-axis model.
    domain_style TEXT NOT NULL DEFAULT 'civilized'
        CHECK(domain_style IN ('civilized', 'clanhold')),
    is_active_adventuring_this_month INTEGER NOT NULL DEFAULT 0
        CHECK(is_active_adventuring_this_month IN (0, 1)),
    classification_progress_families INTEGER NOT NULL DEFAULT 0,
    liege_domain_id TEXT REFERENCES domains(id),
    realm_title TEXT NOT NULL DEFAULT 'Baron',
    is_repressed_this_month INTEGER NOT NULL DEFAULT 0
        CHECK(is_repressed_this_month IN (0, 1)),
    repression_cp_per_family_this_month INTEGER NOT NULL DEFAULT 0,
    treasury_cp INTEGER NOT NULL DEFAULT 0,
    -- Migration 063: Domain settings extensions (Domain Phase 2).
    auto_pay_policies TEXT NOT NULL DEFAULT '{}',
    deferred_maintenance_cp INTEGER NOT NULL DEFAULT 0,
    establishment_method TEXT NOT NULL DEFAULT '',
    established_calendar_day INTEGER NOT NULL DEFAULT 0,
    -- Migration 068: Pending activity modifiers (Domain Phase 3).
    administer_domain_completed_this_month INTEGER NOT NULL DEFAULT 0
        CHECK(administer_domain_completed_this_month IN (0, 1)),
    pending_investment_cp INTEGER NOT NULL DEFAULT 0,
    -- Migration 122: Phase 11B lifecycle authority. `lifecycle_state` is the
    -- canonical "is this domain mechanically alive?" column. Monthly tick
    -- skips abandoned / salted_to_ruin rows; ruined_stronghold and
    -- succession_pending continue to tick with reduced functionality.
    -- Migration 125 renamed 'lost_to_foreign' → 'salted_to_ruin' per the
    -- Phase 11D-prereq.0b conquest-taxonomy revision.
    lifecycle_state TEXT NOT NULL DEFAULT 'active'
        CHECK(lifecycle_state IN ('active', 'ruined_stronghold', 'succession_pending', 'abandoned', 'salted_to_ruin')),
    lifecycle_state_changed_day INTEGER NOT NULL DEFAULT 0,
    ruined_stronghold_grace_until_day INTEGER NOT NULL DEFAULT 0,
    -- Migration 123: Phase 11C succession state. Grace day is non-zero only
    -- when lifecycle_state='succession_pending'; designated_heir_kind is one
    -- of '', 'pc', 'henchman', 'non_henchman'.
    succession_pending_until_day INTEGER NOT NULL DEFAULT 0,
    designated_heir_character_id TEXT NOT NULL DEFAULT '',
    designated_heir_kind TEXT NOT NULL DEFAULT ''
        CHECK(designated_heir_kind IN ('', 'pc', 'henchman', 'non_henchman')),
    -- Migration 124: Phase 11D-prereq.0a realm substrate. Cached pointer to
    -- the realms row this domain belongs to. NULL means "compute via apex
    -- walk" (RealmGraph.apex_for_domain) as a fallback.
    realm_id TEXT REFERENCES realms(id),
    -- Migration 172: tick of the latest vassalage/conquest/protectorate event that
    -- subjugated this domain's polity (set by the setting→runtime materializer on
    -- war-vassal crowns). -1 = never subjugated. NPC/narrator history hook.
    subjugated_since_tick INTEGER NOT NULL DEFAULT -1,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_domains_realm
    ON domains(realm_id);
CREATE INDEX IF NOT EXISTS idx_domains_lifecycle_state
    ON domains(campaign_id, lifecycle_state);
-- Migration 127 (Phase 11D.1): index for style-driven monthly-tick filtering.
CREATE INDEX IF NOT EXISTS idx_domains_style
    ON domains(campaign_id, domain_style);

-- Migration 055: Domain hex land values (Domain Phase 0).
-- Per-hex 3-9 gp/family base land value (3d3 when surveyed) plus up to +3
-- improvement (25,000 gp per +1, never exceeding land_value 9).
-- Migration 119: added map_id so a single domain can own hexes on multiple
-- maps (e.g., a coarse 24-mile parent hex AND its 6-mile inset children).
-- UNIQUE constraint widened to (domain_id, map_id, hex_q, hex_r).
-- map_id has no FK REFERENCES — see migration 119 for rationale (legacy
-- test callers without a domain location_map_id still need to insert).
CREATE TABLE IF NOT EXISTS domain_hexes (
    id                     TEXT    PRIMARY KEY,
    domain_id              TEXT    NOT NULL REFERENCES domains(id),
    map_id                 TEXT    NOT NULL,
    hex_q                  INTEGER NOT NULL,
    hex_r                  INTEGER NOT NULL,
    land_value             INTEGER NOT NULL DEFAULT 5
        CHECK(land_value BETWEEN 3 AND 9),
    -- Migration 173: per-6-mile-hex peasant families (the input to the M4-1
    -- 6-mile vassal decomposition; conserved — a 24-mile hex's 16 children sum
    -- to its population_band). See gdd-region-zoom-in §5.5/§5.6a.
    families               INTEGER NOT NULL DEFAULT 0,
    surveyed_by            TEXT REFERENCES characters(id),
    is_littoral            INTEGER NOT NULL DEFAULT 0
        CHECK(is_littoral IN (0, 1)),
    land_improvement_level INTEGER NOT NULL DEFAULT 0
        CHECK(land_improvement_level BETWEEN 0 AND 3),
    created_at             TEXT    NOT NULL DEFAULT (datetime('now')),
    UNIQUE (domain_id, map_id, hex_q, hex_r)
);
CREATE INDEX IF NOT EXISTS idx_domain_hexes_domain_id
    ON domain_hexes (domain_id);
CREATE INDEX IF NOT EXISTS idx_domain_hexes_map_id
    ON domain_hexes (map_id);

-- Migration 183: per-domain requisition/loot accounting (army-warfare Phase B,
-- gdd-army-warfare.md §4.3 / daw_campaigning_armies.xml L324-347). Cross-army,
-- per-domain: 6-month requisition cooldown + 60 gp/family combined ceiling +
-- families lost. Ceiling resets each 6-month period (population-recovery proxy).
CREATE TABLE IF NOT EXISTS domain_extraction_ledger (
    campaign_id                        TEXT    NOT NULL REFERENCES campaigns(id),
    domain_id                          TEXT    NOT NULL REFERENCES domains(id),
    period_anchor_calendar_day         INTEGER NOT NULL DEFAULT 0,
    last_requisition_calendar_day      INTEGER NOT NULL DEFAULT -1,
    cumulative_extracted_gp_per_family REAL    NOT NULL DEFAULT 0.0,
    families_lost                      INTEGER NOT NULL DEFAULT 0,
    created_at                         TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                         TEXT    NOT NULL DEFAULT (datetime('now')),
    PRIMARY KEY (campaign_id, domain_id)
);
CREATE INDEX IF NOT EXISTS idx_domain_extraction_ledger_campaign
    ON domain_extraction_ledger(campaign_id);

-- Migration 057: Domain followers roster (Domain Phase 0 schema only;
-- Phase 5 ships the follower_arrival_resolver that writes here).
CREATE TABLE IF NOT EXISTS domain_followers (
    id                TEXT    PRIMARY KEY,
    domain_id         TEXT    NOT NULL REFERENCES domains(id),
    follower_class    TEXT    NOT NULL,
    count             INTEGER NOT NULL DEFAULT 0,
    equipped_kit_id   TEXT,
    arrival_phase     TEXT    NOT NULL DEFAULT 'pending'
        CHECK(arrival_phase IN ('pending', 'half_built', 'completed', 'post_completion')),
    morale_modifier   INTEGER NOT NULL DEFAULT 0,
    created_at        TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_domain_followers_domain_id
    ON domain_followers (domain_id);

-- Migration 058: Ledger entries (Domain Phase 0).
-- Append-only record of every gp line that touches a domain treasury.
-- One row per nonzero subcategory per monthly tick.
CREATE TABLE IF NOT EXISTS ledger_entries (
    id              TEXT    PRIMARY KEY,
    domain_id       TEXT    NOT NULL REFERENCES domains(id),
    calendar_day    INTEGER NOT NULL,
    category        TEXT    NOT NULL
        CHECK(category IN ('revenue', 'expense', 'tribute_in', 'tribute_out', 'investment', 'other')),
    subcategory     TEXT    NOT NULL,
    cp_amount       INTEGER NOT NULL,
    description     TEXT    NOT NULL DEFAULT '',
    source_event_id TEXT,
    created_at      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_ledger_entries_domain_id
    ON ledger_entries (domain_id);
CREATE INDEX IF NOT EXISTS idx_ledger_entries_calendar_day
    ON ledger_entries (calendar_day);

-- Migration 059: Follower arrival audit log (Domain Phase 0 schema only).
-- Permanent record of when each follower wave (50/25/25 per
-- §followers_arrival L111-116) arrived at a domain.
CREATE TABLE IF NOT EXISTS follower_arrivals (
    id                    TEXT    PRIMARY KEY,
    domain_id             TEXT    NOT NULL REFERENCES domains(id),
    calendar_day          INTEGER NOT NULL,
    wave_pct              INTEGER NOT NULL
        CHECK(wave_pct IN (50, 25, 25)),
    follower_count_total  INTEGER NOT NULL DEFAULT 0,
    equipment_kit         TEXT    NOT NULL DEFAULT '',
    created_at            TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_follower_arrivals_domain_id
    ON follower_arrivals (domain_id);

-- Migration 060: Strongholds (Domain Phase 1).
-- Summary-level data model per acore_stronghold_construction_costs.pdf and
-- acore_axioms §strongholds. The voxel-grid layout system from
-- gdd-stronghold-construction.md §9.1 is deferred.
CREATE TABLE IF NOT EXISTS strongholds (
    id                       TEXT    PRIMARY KEY,
    domain_id                TEXT REFERENCES domains(id),
    owner_character_id       TEXT REFERENCES characters(id),
    archetype                TEXT    NOT NULL DEFAULT 'fortress'
        CHECK(archetype IN ('fortress', 'sanctum', 'hideout', 'fastness', 'vault', 'clanhold')),
    archetype_power_id       TEXT    NOT NULL DEFAULT '',
    structure_type           TEXT    NOT NULL DEFAULT 'keep',
    cp_value                 INTEGER NOT NULL DEFAULT 0,
    shp                      INTEGER NOT NULL DEFAULT 0,
    ac                       INTEGER NOT NULL DEFAULT 6,
    garrison_capacity        INTEGER NOT NULL DEFAULT 0,
    completion_pct           INTEGER NOT NULL DEFAULT 0
        CHECK(completion_pct BETWEEN 0 AND 100),
    is_conforming_to_class   INTEGER NOT NULL DEFAULT 1
        CHECK(is_conforming_to_class IN (0, 1)),
    is_claimed               INTEGER NOT NULL DEFAULT 0
        CHECK(is_claimed IN (0, 1)),
    claimed_from_source      TEXT    NOT NULL DEFAULT ''
        CHECK(claimed_from_source IN ('', 'dungeon', 'ruin', 'conquest', 'inheritance', 'purchase', 'grant')),
    location_map_id          TEXT REFERENCES hex_maps(id),
    location_hex_q           INTEGER,
    location_hex_r           INTEGER,
    status                   TEXT    NOT NULL DEFAULT 'in_progress'
        CHECK(status IN ('in_progress', 'completed', 'paused', 'destroyed', 'claimed')),
    -- Migration 126 (Urban Growth Stocking §11.4): siting hook for player-
    -- built strongholds that register a parallel settlement_pois row.
    registered_settlement_poi_id TEXT
        REFERENCES settlement_pois(id) ON DELETE SET NULL,
    created_at               TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at               TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_strongholds_domain_id ON strongholds (domain_id);
CREATE INDEX IF NOT EXISTS idx_strongholds_owner    ON strongholds (owner_character_id);
CREATE INDEX IF NOT EXISTS idx_strongholds_hex      ON strongholds (location_map_id, location_hex_q, location_hex_r);

-- Migration 061: Stronghold commissions (Domain Phase 1).
-- 1 day per 500 gp; speed tier 100/150/200; engineer 250 gp/month per 100k gp;
-- 50% cleric/bladedancer cost reduction per acore_stronghold_construction_costs.pdf.
CREATE TABLE IF NOT EXISTS stronghold_commissions (
    id                          TEXT    PRIMARY KEY,
    stronghold_id               TEXT    NOT NULL REFERENCES strongholds(id),
    cp_committed                INTEGER NOT NULL DEFAULT 0,
    daily_construction_rate_cp  INTEGER NOT NULL DEFAULT 50000,
    speed_tier_pct              INTEGER NOT NULL DEFAULT 100
        CHECK(speed_tier_pct IN (100, 150, 200)),
    engineers_required          INTEGER NOT NULL DEFAULT 1,
    engineers_assigned          INTEGER NOT NULL DEFAULT 1,
    engineer_monthly_wage_cp    INTEGER NOT NULL DEFAULT 25000,
    supervisor_character_id     TEXT REFERENCES characters(id),
    magic_rate_modifier_pct     INTEGER NOT NULL DEFAULT 100,
    materials_strategy          TEXT    NOT NULL DEFAULT 'local'
        CHECK(materials_strategy IN ('local', 'purchased', 'scavenged', 'long_distance')),
    class_cost_reduction_pct    INTEGER NOT NULL DEFAULT 0
        CHECK(class_cost_reduction_pct IN (0, 50)),
    started_calendar_day        INTEGER NOT NULL,
    expected_halfway_day        INTEGER NOT NULL,
    expected_completion_day     INTEGER NOT NULL,
    cp_progressed               INTEGER NOT NULL DEFAULT 0,
    halfway_signal_fired        INTEGER NOT NULL DEFAULT 0
        CHECK(halfway_signal_fired IN (0, 1)),
    completed_calendar_day      INTEGER,
    status                      TEXT    NOT NULL DEFAULT 'in_progress'
        CHECK(status IN ('in_progress', 'completed', 'paused_engineers', 'paused_funds', 'paused_user', 'cancelled')),
    created_at                  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_commissions_stronghold ON stronghold_commissions (stronghold_id);
CREATE INDEX IF NOT EXISTS idx_commissions_status     ON stronghold_commissions (status);

-- Migration 062: Stronghold accessories (Domain Phase 1).
-- Upgrade items (arrow slits, doors, shifting walls, etc.) per
-- acore_stronghold_construction_costs.pdf p.127.
CREATE TABLE IF NOT EXISTS stronghold_accessories (
    id              TEXT    PRIMARY KEY,
    stronghold_id   TEXT    NOT NULL REFERENCES strongholds(id),
    accessory_type  TEXT    NOT NULL,
    cp_value        INTEGER NOT NULL DEFAULT 0,
    status          TEXT    NOT NULL DEFAULT 'planned'
        CHECK(status IN ('planned', 'in_progress', 'completed', 'destroyed')),
    created_at      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_accessories_stronghold ON stronghold_accessories (stronghold_id);

-- Migration 005: Character powers (modular power system)
CREATE TABLE IF NOT EXISTS character_powers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    character_id TEXT NOT NULL REFERENCES characters(id),
    power_id TEXT NOT NULL,
    unlock_level INTEGER NOT NULL DEFAULT 1,
    conditions TEXT NOT NULL DEFAULT '[]',
    progression_data TEXT NOT NULL DEFAULT '{}',
    is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0, 1))
);

-- Migration 002: Override system tables

-- override_log: append-only audit trail. Never delete rows.
CREATE TABLE IF NOT EXISTS override_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    game_day INTEGER NOT NULL DEFAULT 0,
    game_round INTEGER NOT NULL DEFAULT 0,
    applied_at TEXT NOT NULL DEFAULT (datetime('now')),
    override_type TEXT NOT NULL,
    target_id TEXT NOT NULL DEFAULT '',
    field_changed TEXT NOT NULL DEFAULT '',
    old_value TEXT NOT NULL DEFAULT '',
    new_value TEXT NOT NULL DEFAULT ''
);

-- game_snapshots: savegame slot METADATA (Phase S-2, gdd-savegame-system.md §6).
-- Each row is a named save slot; the actual game state is a whole-DB file at
-- user://saves/<id>.db (VACUUM INTO), so a slot is structurally complete.
-- snapshot_data now holds a small manifest (legacy JSON-blob rows predate this).
-- slot_kind / schema_version / location_label added by migration 147.
CREATE TABLE IF NOT EXISTS game_snapshots (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    label TEXT NOT NULL,
    snapshot_data TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    slot_kind TEXT NOT NULL DEFAULT 'manual',
    schema_version INTEGER NOT NULL DEFAULT 0,
    location_label TEXT NOT NULL DEFAULT ''
);

-- dungeon_entrances: hex placement record; dungeon_data populated by layout generator.
CREATE TABLE IF NOT EXISTS dungeon_entrances (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    map_id TEXT NOT NULL REFERENCES hex_maps(id),
    hex_q INTEGER NOT NULL,
    hex_r INTEGER NOT NULL,
    name TEXT NOT NULL DEFAULT 'Unknown Dungeon',
    dungeon_data TEXT NOT NULL DEFAULT ''
);

-- Migration 003: Dice roll log
-- Per-session only. Cleared on session end. Capped at 200 rows (DiceSystem auto-prunes oldest).

CREATE TABLE IF NOT EXISTS dice_rolls (
    id                  INTEGER  PRIMARY KEY AUTOINCREMENT,
    game_day            INTEGER  NOT NULL DEFAULT 0,
    roll_type           TEXT     NOT NULL DEFAULT '',
    sides               INTEGER  NOT NULL,
    count               INTEGER  NOT NULL DEFAULT 1,
    modifier            INTEGER  NOT NULL DEFAULT 0,
    individual_results  TEXT     NOT NULL DEFAULT '[]',
    raw_total           INTEGER  NOT NULL,
    modified_total      INTEGER  NOT NULL,
    was_overridden      INTEGER  NOT NULL DEFAULT 0,
    was_player_entered  INTEGER  NOT NULL DEFAULT 0,
    created_at          DATETIME NOT NULL DEFAULT (datetime('now'))
);

-- Migration 004: Timekeeping tables

-- campaign_clock: the single shared world clock per campaign. Not FK'd to
-- campaigns table so it can be seeded in tests and pre-campaign setup without
-- a campaigns row.
-- (party_clocks, the per-party time offsets from migration 004, was dropped
-- by migration 154 — single-shared-timeline ruling 2026-06-11.)
CREATE TABLE IF NOT EXISTS campaign_clock (
    campaign_id    TEXT    PRIMARY KEY,
    elapsed_rounds INTEGER NOT NULL DEFAULT 0,
    dawn_hour      INTEGER NOT NULL DEFAULT 6,
    dusk_hour      INTEGER NOT NULL DEFAULT 20
);

-- Migration 006: Active spell effects
CREATE TABLE IF NOT EXISTS active_effects (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    spell_key TEXT NOT NULL,
    caster_id TEXT NOT NULL,
    caster_level INTEGER NOT NULL DEFAULT 1,
    target_ids TEXT NOT NULL DEFAULT '[]',
    effect_type TEXT NOT NULL DEFAULT 'modifier'
        CHECK(effect_type IN ('modifier', 'flag', 'entity', 'condition', 'instant')),
    applied_modifiers TEXT NOT NULL DEFAULT '[]',
    applied_conditions TEXT NOT NULL DEFAULT '[]',
    applied_flags TEXT NOT NULL DEFAULT '[]',
    duration_type TEXT NOT NULL DEFAULT 'rounds'
        CHECK(duration_type IN ('rounds', 'turns', 'hours', 'days', 'permanent', 'concentration')),
    duration_remaining INTEGER NOT NULL DEFAULT -1,
    requires_concentration INTEGER NOT NULL DEFAULT 0 CHECK(requires_concentration IN (0, 1)),
    is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0, 1)),
    metadata TEXT NOT NULL DEFAULT '{}',
    created_at_round INTEGER NOT NULL DEFAULT 0,
    -- Migration 054: concentration mode classification (spell-system DSL).
    concentration_mode TEXT NOT NULL DEFAULT 'none'
        CHECK(concentration_mode IN ('none', 'continuous_focus', 'sustained', 'conditional'))
);

-- parties.dungeon_id, dungeon_level, dungeon_col, dungeon_row added by migration 017.
-- parties.settlement_id, settlement_node_id added by migration 019; settlement_node_id
-- realigned INTEGER -> TEXT by migration 148 (it is a string POI id, '' = no POI;
-- the migration-019 "street graph node / -1" model was replaced by SettlementMapController).
-- The original dungeon_map_cells table (migration 017) was dropped by migration 039
-- after the 12b cleanup — all voxel dungeon state lives in voxel_map_cells below.

-- Migration 146: per-entity live dungeon positions for full-fidelity savegame
-- restore (gdd-savegame-system.md §5.2). One row per party entity while in a
-- dungeon; written on save, DELETEd on dungeon exit.
CREATE TABLE IF NOT EXISTS dungeon_entity_positions (
    party_id    TEXT    NOT NULL REFERENCES parties(id),
    entity_id   TEXT    NOT NULL,
    dungeon_id  TEXT    NOT NULL,
    col         INTEGER NOT NULL,
    row         INTEGER NOT NULL,
    level       INTEGER NOT NULL,
    PRIMARY KEY (party_id, entity_id)
);
CREATE INDEX IF NOT EXISTS idx_dungeon_entity_positions_party
    ON dungeon_entity_positions(party_id);

-- Migration 036: Voxel grid cell storage (3D cube-cell model)
-- Sparse storage: one row per non-default voxel cell.

CREATE TABLE IF NOT EXISTS voxel_map_cells (
    map_id TEXT NOT NULL,
    col INTEGER NOT NULL,
    row INTEGER NOT NULL,
    level INTEGER NOT NULL,
    solidity TEXT NOT NULL DEFAULT 'air',
    feature TEXT NOT NULL DEFAULT 'open',
    floor_type TEXT NOT NULL DEFAULT 'none',
    door_state TEXT NOT NULL DEFAULT '',
    door_type TEXT NOT NULL DEFAULT '',
    door_detected INTEGER NOT NULL DEFAULT 1,
    fog_state TEXT NOT NULL DEFAULT 'hidden',
    room_id INTEGER NOT NULL DEFAULT -1,
    is_corridor INTEGER NOT NULL DEFAULT 0,
    cover_value INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (map_id, col, row, level)
);

-- Migration 019: Settlement entrances
-- Settlement layout stored as JSON in settlement_data.
-- Party position is a street graph node ID, not grid coordinates.
CREATE TABLE IF NOT EXISTS settlement_entrances (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    map_id TEXT NOT NULL REFERENCES hex_maps(id),
    hex_q INTEGER NOT NULL,
    hex_r INTEGER NOT NULL,
    name TEXT NOT NULL DEFAULT 'Unknown Settlement',
    market_class INTEGER NOT NULL DEFAULT 6,
    settlement_data TEXT NOT NULL DEFAULT '',
    -- Migration 025: reputation cascade + hostile gate enforcement
    parent_domain_id TEXT REFERENCES domains(id),
    barred_party_ids TEXT NOT NULL DEFAULT '[]',
    -- Migration 097 (Phase 10B Prereq.2a): settlement economy substrate.
    age_years INTEGER NOT NULL DEFAULT 500,
    dominant_race TEXT NOT NULL DEFAULT 'human',
    urban_families INTEGER NOT NULL DEFAULT 0,
    climate_override TEXT NOT NULL DEFAULT '',
    economy_inputs_changed_day INTEGER NOT NULL DEFAULT 0,
    customs_duty_rate_pct INTEGER NOT NULL DEFAULT 0,
    -- Migration 126: cumulative urban investment in gp for the maximum-
    -- population-by-total-investment cap per `acore_axioms_strongholds_and_
    -- domains.xml:641-648`. SettlementGrowthResolver increments this each
    -- month by the consumed investment_cp. Seeded to 10000gp (Class VI
    -- founding floor) so pre-existing settlements stay above the cap.
    cumulative_investment_gp INTEGER NOT NULL DEFAULT 10000,
    -- Migration 171: per-settlement world-history provenance (past ruling
    -- cultures/polities + founding), derived from setting_events by the
    -- setting→runtime materializer for the LLM narrator/NPC layer. JSON; '{}' = none.
    history_context TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX IF NOT EXISTS idx_settlement_entrances_parent_domain
    ON settlement_entrances(parent_domain_id);
CREATE INDEX IF NOT EXISTS idx_settlement_entrances_dominant_race
    ON settlement_entrances(dominant_race);

-- Migration 097 (Phase 10B Prereq.2a): demand-modifier cache.
-- Per gdd-settlement-economy.md §4.7 + §6.5. One row per
-- (settlement_entrance_id, merchandise_type). Source-of-truth for the
-- six-step RAW demand modifier output; the dice_4d4 columns are
-- consumed by Prereq.2c's market_price_resolver.
CREATE TABLE IF NOT EXISTS settlement_merchandise_demand (
    settlement_entrance_id        TEXT    NOT NULL REFERENCES settlement_entrances(id),
    merchandise_type              TEXT    NOT NULL,
    demand_modifier               INTEGER NOT NULL DEFAULT 0,
    generated_at_calendar_day     INTEGER NOT NULL DEFAULT 0,
    source_kind                   TEXT    NOT NULL DEFAULT 'generated'
        CHECK(source_kind IN ('generated', 'manual')),
    pre_trade_route_shift_value   INTEGER NOT NULL DEFAULT 0,
    dice_4d4_value                INTEGER NOT NULL DEFAULT 0,
    dice_last_rolled_calendar_day INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (settlement_entrance_id, merchandise_type)
);
CREATE INDEX IF NOT EXISTS idx_smd_settlement
    ON settlement_merchandise_demand(settlement_entrance_id);

-- Migration 098 (Phase 10B Prereq.2b): trade routes cache.
-- Per gdd-settlement-economy.md §5.5. One row per ordered pair
-- (settlement_a_id < settlement_b_id) of settlements connected by a
-- valid trade route per RAW criteria
-- (acore-setting-construction-rules.xml:358-365). invalidated is a soft-
-- delete flag so an in-flight region walk completes against a stable
-- snapshot on topology changes.
CREATE TABLE IF NOT EXISTS trade_routes (
    id                          TEXT    PRIMARY KEY,
    campaign_id                 TEXT    NOT NULL REFERENCES campaigns(id),
    settlement_a_id             TEXT    NOT NULL REFERENCES settlement_entrances(id),
    settlement_b_id             TEXT    NOT NULL REFERENCES settlement_entrances(id),
    path_kind                   TEXT    NOT NULL
        CHECK(path_kind IN ('road', 'water', 'mixed')),
    distance_hexes              INTEGER NOT NULL,
    discovered_at_calendar_day  INTEGER NOT NULL DEFAULT 0,
    invalidated                 INTEGER NOT NULL DEFAULT 0
        CHECK(invalidated IN (0, 1)),
    CHECK(settlement_a_id < settlement_b_id),
    UNIQUE(settlement_a_id, settlement_b_id)
);
CREATE INDEX IF NOT EXISTS idx_trade_routes_a
    ON trade_routes(settlement_a_id, invalidated);
CREATE INDEX IF NOT EXISTS idx_trade_routes_b
    ON trade_routes(settlement_b_id, invalidated);
CREATE INDEX IF NOT EXISTS idx_trade_routes_campaign
    ON trade_routes(campaign_id, invalidated);

-- Migration 099 (Phase 10B Prereq.4): merchant pool cache.
-- Per gdd-settlement-economy.md §7.8. One row per merchant per cohort.
-- Cohort lifecycle = 28 days; visibility gated by becomes_visible_calendar_day
-- (default INT32_MAX sentinel = invisible until solicit_merchants or
-- locate_merchandise flips it).
CREATE TABLE IF NOT EXISTS merchant_pool (
    id                              TEXT    PRIMARY KEY,
    campaign_id                     TEXT    NOT NULL REFERENCES campaigns(id),
    settlement_entrance_id          TEXT    NOT NULL REFERENCES settlement_entrances(id),
    merchandise_type                TEXT    NOT NULL,
    loads_available                 INTEGER NOT NULL DEFAULT 0,
    loads_initial                   INTEGER NOT NULL DEFAULT 0,
    created_at_calendar_day         INTEGER NOT NULL DEFAULT 0,
    expires_at_calendar_day         INTEGER NOT NULL DEFAULT 0,
    becomes_visible_calendar_day    INTEGER NOT NULL DEFAULT 2147483647,
    status                          TEXT    NOT NULL DEFAULT 'active'
        CHECK(status IN ('active', 'depleted', 'expired')),
    source_kind                     TEXT    NOT NULL DEFAULT 'monthly_refresh'
        CHECK(source_kind IN ('monthly_refresh', 'manual')),
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now')),
    -- Migration 104 (Phase 10B.2 Wave 1): LLM-promotion forward-compat hook
    -- (gdd-phase-10b-2-trade-block.md §0.1.1) + persuade-fail preservation
    -- path (§4.7 Path B). Both nullable; v1 has no caller populating either.
    promoted_npc_id                 TEXT    REFERENCES characters(id),
    refused_at_calendar_day         INTEGER
);
CREATE INDEX IF NOT EXISTS idx_merchant_pool_settlement_status
    ON merchant_pool(settlement_entrance_id, status);
CREATE INDEX IF NOT EXISTS idx_merchant_pool_settlement_merchandise
    ON merchant_pool(settlement_entrance_id, merchandise_type, status);
CREATE INDEX IF NOT EXISTS idx_merchant_pool_expiration
    ON merchant_pool(expires_at_calendar_day, status);
CREATE INDEX IF NOT EXISTS idx_merchant_pool_visibility
    ON merchant_pool(settlement_entrance_id, becomes_visible_calendar_day);

-- Migration 100 (Phase 10B Prereq.5a): ships persistence.
-- Per gdd-settlement-economy.md §9.2. Parallels draft_vehicles (migration 024)
-- for sea vessels. Catalog: data/equipment/maritime.json.
CREATE TABLE IF NOT EXISTS ships (
    id                              TEXT    PRIMARY KEY,
    campaign_id                     TEXT    NOT NULL REFERENCES campaigns(id),
    party_id                        TEXT    REFERENCES parties(id),
    vessel_key                      TEXT    NOT NULL,
    name                            TEXT    NOT NULL DEFAULT 'Unnamed Vessel',
    shp_max                         INTEGER NOT NULL DEFAULT 0,
    shp_current                     INTEGER NOT NULL DEFAULT 0,
    cargo_capacity_stone            INTEGER NOT NULL DEFAULT 0,
    crew_captain                    INTEGER NOT NULL DEFAULT 0,
    crew_sailors                    INTEGER NOT NULL DEFAULT 0,
    crew_rowers                     INTEGER NOT NULL DEFAULT 0,
    crew_marines                    INTEGER NOT NULL DEFAULT 0,
    monthly_operating_cost_cp       INTEGER NOT NULL DEFAULT 0,
    current_location_kind           TEXT    NOT NULL DEFAULT 'moored'
        CHECK(current_location_kind IN ('moored', 'at_sea', 'wrecked')),
    moored_at_settlement_id         TEXT    REFERENCES settlement_entrances(id),
    is_destroyed                    INTEGER NOT NULL DEFAULT 0
        CHECK(is_destroyed IN (0, 1)),
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_ships_party
    ON ships(party_id, is_destroyed);
CREATE INDEX IF NOT EXISTS idx_ships_campaign
    ON ships(campaign_id, is_destroyed);
CREATE INDEX IF NOT EXISTS idx_ships_moored
    ON ships(moored_at_settlement_id);

-- Migration 101 (Phase 10B Prereq.5b): cargo holds.
-- Per gdd-settlement-economy.md §9.4. One row per cargo acquisition with
-- XOR carrier (draft_vehicle_id or ship_id) and provenance via
-- source_acquisition_kind. ON DELETE CASCADE on both carriers (documented
-- defensive; v1 carrier destruction uses soft-delete which does not trigger
-- CASCADE).
CREATE TABLE IF NOT EXISTS cargo_holds (
    id                                  TEXT    PRIMARY KEY,
    campaign_id                         TEXT    NOT NULL REFERENCES campaigns(id),
    draft_vehicle_id                    TEXT    REFERENCES draft_vehicles(id) ON DELETE CASCADE,
    ship_id                             TEXT    REFERENCES ships(id) ON DELETE CASCADE,
    merchandise_type                    TEXT    NOT NULL,
    loads_count                         INTEGER NOT NULL DEFAULT 0,
    load_weight_stone                   INTEGER NOT NULL DEFAULT 0,
    market_value_at_acquisition_cp      INTEGER NOT NULL DEFAULT 0,
    source_acquisition_kind             TEXT    NOT NULL DEFAULT 'purchased'
        CHECK(source_acquisition_kind IN ('purchased', 'smuggled', 'stolen', 'shipping_contract')),
    acquired_at_settlement_id           TEXT    REFERENCES settlement_entrances(id),
    acquired_at_calendar_day            INTEGER NOT NULL DEFAULT 0,
    shipping_contract_id                TEXT,
    notes                               TEXT    NOT NULL DEFAULT '',
    created_at                          TEXT    NOT NULL DEFAULT (datetime('now')),
    CHECK ((draft_vehicle_id IS NOT NULL) <> (ship_id IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS idx_cargo_holds_draft_vehicle
    ON cargo_holds(draft_vehicle_id) WHERE draft_vehicle_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_cargo_holds_ship
    ON cargo_holds(ship_id) WHERE ship_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_cargo_holds_merchandise
    ON cargo_holds(merchandise_type);
CREATE INDEX IF NOT EXISTS idx_cargo_holds_campaign
    ON cargo_holds(campaign_id);

-- Migration 102 (Phase 10B Prereq.5c): shipping contracts.
-- Per gdd-settlement-economy.md §9.7. Tracks party-accepted contracts; the
-- `cargo_holds.shipping_contract_id` back-pointer (ungoverned by FK) links
-- contract rows to their cargo.
CREATE TABLE IF NOT EXISTS shipping_contracts (
    id                              TEXT    PRIMARY KEY,
    campaign_id                     TEXT    NOT NULL REFERENCES campaigns(id),
    accepted_by_party_id            TEXT    NOT NULL REFERENCES parties(id),
    origin_settlement_id            TEXT    NOT NULL REFERENCES settlement_entrances(id),
    destination_settlement_id       TEXT    NOT NULL REFERENCES settlement_entrances(id),
    merchandise_type                TEXT    NOT NULL,
    loads_count                     INTEGER NOT NULL DEFAULT 0,
    fee_cp                          INTEGER NOT NULL DEFAULT 0,
    deadline_calendar_day           INTEGER NOT NULL DEFAULT 0,
    status                          TEXT    NOT NULL DEFAULT 'accepted'
        CHECK(status IN ('accepted', 'in_transit', 'delivered', 'failed_deadline', 'cancelled')),
    accepted_at_calendar_day        INTEGER NOT NULL DEFAULT 0,
    delivered_at_calendar_day       INTEGER,
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_shipping_contracts_party
    ON shipping_contracts(accepted_by_party_id, status);
CREATE INDEX IF NOT EXISTS idx_shipping_contracts_destination
    ON shipping_contracts(destination_settlement_id, status);
CREATE INDEX IF NOT EXISTS idx_shipping_contracts_campaign
    ON shipping_contracts(campaign_id, status);

-- Migration 103 (Phase 10B Prereq.6): character legal status (sibling table
-- to characters). Per gdd-settlement-economy.md §10.3. Branded/Maimed/
-- Proscribed flags stack additively in prior_crimes_modifier_cache.
CREATE TABLE IF NOT EXISTS character_legal_status (
    character_id                    TEXT    PRIMARY KEY REFERENCES characters(id),
    is_branded                      INTEGER NOT NULL DEFAULT 0
        CHECK(is_branded IN (0, 1)),
    is_maimed                       INTEGER NOT NULL DEFAULT 0
        CHECK(is_maimed IN (0, 1)),
    is_proscribed                   INTEGER NOT NULL DEFAULT 0
        CHECK(is_proscribed IN (0, 1)),
    prior_crimes_modifier_cache     INTEGER NOT NULL DEFAULT 0,
    branded_at_calendar_day         INTEGER,
    maimed_at_calendar_day          INTEGER,
    proscribed_at_calendar_day      INTEGER,
    notes                           TEXT    NOT NULL DEFAULT '',
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                      TEXT    NOT NULL DEFAULT (datetime('now'))
);

-- Migration 025: Reputation system (Phase G-1)

CREATE TABLE IF NOT EXISTS factions (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    name TEXT NOT NULL,
    alignment TEXT NOT NULL DEFAULT 'neutral'
        CHECK(alignment IN ('lawful', 'neutral', 'chaotic')),
    faction_type TEXT NOT NULL DEFAULT 'tribal',
    home_domain_id TEXT REFERENCES domains(id),
    leader_npc_id TEXT REFERENCES characters(id),
    parent_faction_id TEXT REFERENCES factions(id),
    description TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    -- Faction Framework FF-1 (migration 188 / gdd-faction-framework.md §4.1)
    scope TEXT NOT NULL DEFAULT 'organization'
        CHECK(scope IN ('realm', 'organization', 'warband')),
    realm_id TEXT REFERENCES realms(id),        -- set only for scope='realm' mirror rows
    religion_id TEXT,
    culture_id TEXT,
    seat_poi_id TEXT,
    seat_settlement_id TEXT,
    treasury_gp INTEGER NOT NULL DEFAULT 0,
    member_count_abstract INTEGER NOT NULL DEFAULT 0,
    power_rating INTEGER NOT NULL DEFAULT 0,
    goal_primary TEXT,
    goal_secondary TEXT,
    volatility REAL NOT NULL DEFAULT 1.0,
    is_player_founded INTEGER NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'active'
        CHECK(status IN ('active', 'underground', 'disbanded', 'destroyed', 'absorbed')),
    personality_weight_biases TEXT
);

CREATE TABLE IF NOT EXISTS faction_memberships (
    faction_id TEXT NOT NULL REFERENCES factions(id),
    npc_id TEXT NOT NULL REFERENCES characters(id),
    role TEXT NOT NULL DEFAULT 'member',
    -- Faction Framework FF-1 (migration 188 / gdd-faction-framework.md §4.4)
    rank INTEGER NOT NULL DEFAULT 0,
    loyalty_mod INTEGER NOT NULL DEFAULT 0,
    standing INTEGER NOT NULL DEFAULT 0,
    is_secret INTEGER NOT NULL DEFAULT 0,
    joined_day INTEGER NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'member'
        CHECK(status IN ('petitioner', 'member', 'suspended', 'expelled', 'left', 'deceased')),
    PRIMARY KEY (faction_id, npc_id)
);

CREATE TABLE IF NOT EXISTS reputation_entries (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    party_id TEXT NOT NULL REFERENCES parties(id),
    scope_type TEXT NOT NULL
        CHECK(scope_type IN ('faction','settlement','domain','tier_a_npc','tier_b_npc','social_group')),
    scope_id TEXT NOT NULL,
    score INTEGER NOT NULL DEFAULT 0,
    tier TEXT NOT NULL DEFAULT 'neutral'
        CHECK(tier IN ('hostile','unfriendly','neutral','indifferent','friendly')),
    last_reason TEXT NOT NULL DEFAULT '',
    last_updated TEXT NOT NULL DEFAULT (datetime('now')),
    UNIQUE(campaign_id, party_id, scope_type, scope_id)
);

CREATE TABLE IF NOT EXISTS social_groups (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    name TEXT NOT NULL,
    group_type TEXT NOT NULL DEFAULT 'guild',
    description TEXT NOT NULL DEFAULT ''
);

-- domains.ruler_npc_id added by migration 025.

-- Migration 027: Henchman lifecycle (Phase G-2)

CREATE TABLE IF NOT EXISTS henchman_pools (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    settlement_id TEXT NOT NULL REFERENCES settlement_entrances(id),
    generated_month INTEGER NOT NULL,
    generated_year INTEGER NOT NULL,
    total_available INTEGER NOT NULL DEFAULT 0,
    search_cost_cp INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS henchman_pool_members (
    pool_id TEXT NOT NULL REFERENCES henchman_pools(id),
    character_id TEXT NOT NULL REFERENCES characters(id),
    allotment_week INTEGER NOT NULL DEFAULT 1,
    is_hired INTEGER NOT NULL DEFAULT 0 CHECK(is_hired IN (0, 1)),
    PRIMARY KEY (pool_id, character_id)
);

CREATE TABLE IF NOT EXISTS henchman_state (
    character_id TEXT PRIMARY KEY REFERENCES characters(id),
    morale_score INTEGER NOT NULL DEFAULT 0,
    treasure_share_percent INTEGER NOT NULL DEFAULT 15,
    unpaid_months INTEGER NOT NULL DEFAULT 0,
    is_grudging INTEGER NOT NULL DEFAULT 0 CHECK(is_grudging IN (0, 1)),
    is_fanatic INTEGER NOT NULL DEFAULT 0 CHECK(is_fanatic IN (0, 1)),
    hired_month INTEGER NOT NULL DEFAULT 0,
    hired_year INTEGER NOT NULL DEFAULT 0,
    departure_reason TEXT NOT NULL DEFAULT '',
    departure_settlement_id TEXT REFERENCES settlement_entrances(id),
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);


-- ---------------------------------------------------------------------------
-- Event scheduler (Migration 028)
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS scheduled_events (
    event_id        TEXT    PRIMARY KEY,
    campaign_id     TEXT    NOT NULL REFERENCES campaigns(id),
    fire_time       INTEGER NOT NULL,
    event_type      TEXT    NOT NULL,
    owner_id        TEXT    NOT NULL DEFAULT '',
    data_json       TEXT    NOT NULL DEFAULT '{}',
    priority        INTEGER NOT NULL DEFAULT 20,
    cancelled       INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS idx_scheduled_events_fire_time
    ON scheduled_events(campaign_id, fire_time);

CREATE INDEX IF NOT EXISTS idx_scheduled_events_owner
    ON scheduled_events(campaign_id, owner_id);

CREATE TABLE IF NOT EXISTS auto_pause_config (
    campaign_id     TEXT    NOT NULL REFERENCES campaigns(id),
    event_category  TEXT    NOT NULL,
    pause_tier      INTEGER NOT NULL DEFAULT 1,
    PRIMARY KEY (campaign_id, event_category)
);


-- ---------------------------------------------------------------------------
-- Shop inventory and commissions (Migration 029)
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS shop_inventory (
    id                  TEXT    PRIMARY KEY,
    campaign_id         TEXT    NOT NULL REFERENCES campaigns(id),
    settlement_id       TEXT    NOT NULL,
    poi_id              TEXT    NOT NULL,
    item_key            TEXT    NOT NULL,
    quantity_available  INTEGER NOT NULL DEFAULT 0,
    generated_at_round  INTEGER NOT NULL DEFAULT 0,
    UNIQUE(campaign_id, poi_id, item_key)
);

CREATE INDEX IF NOT EXISTS idx_shop_inventory_poi
    ON shop_inventory(campaign_id, poi_id);

CREATE TABLE IF NOT EXISTS commissions (
    id                  TEXT    PRIMARY KEY,
    campaign_id         TEXT    NOT NULL REFERENCES campaigns(id),
    settlement_id       TEXT    NOT NULL,
    poi_id              TEXT    NOT NULL,
    character_id        TEXT    NOT NULL REFERENCES characters(id),
    item_key            TEXT    NOT NULL,
    quantity            INTEGER NOT NULL DEFAULT 1,
    cost_cp             INTEGER NOT NULL DEFAULT 0,
    ordered_at_round    INTEGER NOT NULL DEFAULT 0,
    ready_at_round      INTEGER NOT NULL DEFAULT 0,
    picked_up           INTEGER NOT NULL DEFAULT 0 CHECK(picked_up IN (0, 1))
);

CREATE INDEX IF NOT EXISTS idx_commissions_poi
    ON commissions(campaign_id, poi_id);

CREATE INDEX IF NOT EXISTS idx_commissions_character
    ON commissions(campaign_id, character_id);


-- ---------------------------------------------------------------------------
-- Settlement PoI visit log (Migration 030; known_city_routes dropped by 041)
-- ---------------------------------------------------------------------------
-- visited_pois retained for narrative tracking only (quest/dialogue references
-- like "have you been to X?"); does NOT gate menu visibility in v2 settlement
-- exploration UI.

CREATE TABLE IF NOT EXISTS visited_pois (
    id                  TEXT    PRIMARY KEY,
    campaign_id         TEXT    NOT NULL REFERENCES campaigns(id),
    settlement_id       TEXT    NOT NULL,
    poi_id              TEXT    NOT NULL,
    discovered_at_round INTEGER NOT NULL DEFAULT 0,
    discovery_method    TEXT    NOT NULL DEFAULT 'visited',
    UNIQUE(campaign_id, settlement_id, poi_id)
);

CREATE INDEX IF NOT EXISTS idx_visited_pois_lookup
    ON visited_pois(campaign_id, settlement_id);

-- ============================================================================
-- Abandoned Characters (migration 031)
-- ============================================================================

CREATE TABLE IF NOT EXISTS abandoned_characters (
    character_id TEXT    NOT NULL,
    dungeon_id   TEXT    NOT NULL,
    level_num    INTEGER NOT NULL DEFAULT 1,
    col          INTEGER NOT NULL DEFAULT 0,
    row          INTEGER NOT NULL DEFAULT 0,
    abandoned_at INTEGER NOT NULL DEFAULT 0,
    resolved     INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (character_id, dungeon_id)
);

-- ============================================================================
-- Location Caches (migration 032; migration 037 extends dungeon keys to 3D)
-- ============================================================================
-- location_key formats:
--   hex:             "hex:<q>,<r>"
--   dungeon_cell:    "dungeon:<dungeon_id>:cell:<col>,<row>,<level>"   -- level axis added in migration 037
--   settlement_node: "settlement:<settlement_id>:poi:<poi_id>"

CREATE TABLE IF NOT EXISTS location_caches (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    location_type TEXT NOT NULL CHECK(location_type IN ('hex', 'dungeon_cell', 'settlement_node')),
    location_key TEXT NOT NULL,
    cache_variant TEXT NOT NULL CHECK(cache_variant IN ('loose', 'locked_container', 'hidden_wilderness')),
    container_item_id TEXT REFERENCES inventory_items(id) ON DELETE SET NULL,
    is_persistent INTEGER NOT NULL DEFAULT 0,
    decay_check_day INTEGER DEFAULT NULL,
    created_at_day INTEGER NOT NULL,
    raid_monthly_modifier INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS location_caches_by_location
    ON location_caches(campaign_id, location_type, location_key);

CREATE INDEX IF NOT EXISTS location_caches_by_decay_day
    ON location_caches(decay_check_day)
    WHERE decay_check_day IS NOT NULL;

-- ============================================================================
-- Character Preferences (migration 033)
-- ============================================================================

CREATE TABLE IF NOT EXISTS character_preferences (
    character_id TEXT NOT NULL PRIMARY KEY REFERENCES characters(id) ON DELETE CASCADE,
    preferred_tags TEXT NOT NULL DEFAULT '[]'
);

-- ============================================================================
-- Familiars (migration 044)
-- ============================================================================
-- A familiar is a magical animal companion bonded to a single master (PC).
-- Form determines body (AC, movement, attacks, special abilities); HD, max HP,
-- INT, and proficiency count are derived from master and cached here.
-- See generation/gdd-familiars.md.

CREATE TABLE IF NOT EXISTS familiars (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    master_character_id TEXT NOT NULL REFERENCES characters(id),
    form_key TEXT NOT NULL,
    cosmetic_species TEXT NOT NULL DEFAULT '',
    name TEXT NOT NULL DEFAULT '',
    hp_current INTEGER NOT NULL DEFAULT 1,
    hp_max_cached INTEGER NOT NULL DEFAULT 1,
    -- HD progression (derived from master level — see gdd-familiars.md §3.3)
    hd_dice INTEGER NOT NULL DEFAULT 0,
    hd_modifier_hp INTEGER NOT NULL DEFAULT 0,
    is_half_hd INTEGER NOT NULL DEFAULT 1 CHECK(is_half_hd IN (0, 1)),
    -- Attack / save progression (derived from master level via HD)
    attack_save_class TEXT NOT NULL DEFAULT 'NM' CHECK(attack_save_class IN ('NM', 'fighter')),
    attack_save_level INTEGER NOT NULL DEFAULT 0,
    damage_bonus INTEGER NOT NULL DEFAULT 0,
    int_cached INTEGER NOT NULL DEFAULT 10,
    proficiency_count_cached INTEGER NOT NULL DEFAULT 0,
    proficiencies_chosen TEXT NOT NULL DEFAULT '[]',
    is_alive INTEGER NOT NULL DEFAULT 1 CHECK(is_alive IN (0, 1)),
    bonded_at_master_level INTEGER NOT NULL DEFAULT 1,
    death_save_pending INTEGER NOT NULL DEFAULT 0 CHECK(death_save_pending IN (0, 1)),
    position_voxel_x INTEGER NOT NULL DEFAULT 0,
    position_voxel_y INTEGER NOT NULL DEFAULT 0,
    position_voxel_z INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_familiars_master
    ON familiars(master_character_id);

CREATE UNIQUE INDEX IF NOT EXISTS idx_familiars_living_per_master
    ON familiars(master_character_id) WHERE is_alive = 1;

-- Migration 064: Active adventuring audit log (Domain Phase 2).
-- Append-only record of each domain's monthly active-adventuring resolution
-- per the project-resolved seven-trigger heuristic
-- (gdd-domain-tab.md §6.2 + docs/domain-roadmap-corrected.md Phase 2).
CREATE TABLE IF NOT EXISTS active_adventuring_log (
    id              TEXT    PRIMARY KEY,
    domain_id       TEXT    NOT NULL REFERENCES domains(id),
    calendar_day    INTEGER NOT NULL,
    is_active       INTEGER NOT NULL DEFAULT 0
        CHECK(is_active IN (0, 1)),
    triggers_json   TEXT    NOT NULL DEFAULT '{}',
    created_at      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_active_adventuring_log_domain_id
    ON active_adventuring_log (domain_id);
CREATE INDEX IF NOT EXISTS idx_active_adventuring_log_calendar_day
    ON active_adventuring_log (calendar_day);

-- Migration 065: Activity state (Domain Phase 3).
-- Persists per-character ongoing-frequency activities across game days.
-- Singular and Restricted activities resolve atomically inside the
-- EventScheduler and do NOT persist between days. See gdd-realtime-scheduler.md
-- §4.8.3 and gdd-domain-tab.md §15.1 for the tick-tolerance / absence model.
CREATE TABLE IF NOT EXISTS activity_state (
    id                   TEXT    PRIMARY KEY,
    campaign_id          TEXT    NOT NULL REFERENCES campaigns(id),
    character_id         TEXT    NOT NULL REFERENCES characters(id),
    activity_def_id      TEXT    NOT NULL,
    frequency_type       TEXT    NOT NULL
        CHECK(frequency_type IN ('singular', 'restricted', 'ongoing')),
    status               TEXT    NOT NULL DEFAULT 'active'
        CHECK(status IN ('active', 'completed', 'forfeited', 'abandoned')),
    location_kind        TEXT    NOT NULL DEFAULT 'anywhere',
    location_ref         TEXT    NOT NULL DEFAULT '',
    time_cost_rounds     INTEGER NOT NULL DEFAULT 0,
    ticks_required       INTEGER NOT NULL DEFAULT 1,
    ticks_accumulated    INTEGER NOT NULL DEFAULT 0,
    absence_accumulated  INTEGER NOT NULL DEFAULT 0,
    started_calendar_day INTEGER NOT NULL DEFAULT 0,
    last_session_day     INTEGER NOT NULL DEFAULT 0,
    cp_committed         INTEGER NOT NULL DEFAULT 0,
    params_json          TEXT    NOT NULL DEFAULT '{}',
    scheduled_event_id   TEXT    NOT NULL DEFAULT '',
    created_at           TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at           TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_activity_state_character
    ON activity_state (character_id);
CREATE INDEX IF NOT EXISTS idx_activity_state_activity_def
    ON activity_state (activity_def_id);
CREATE INDEX IF NOT EXISTS idx_activity_state_status
    ON activity_state (status);
CREATE INDEX IF NOT EXISTS idx_activity_state_campaign
    ON activity_state (campaign_id);

-- Migration 066: Character activity state (Domain Phase 3 - Strenuous Accountant).
-- Streak counter for the strenuous-day / overtime rules per ax_campaign_play.xml
-- §effort_rules L166-172 and §overtime_rules L173-186. The attack_throw_penalty
-- column is denormalized so combat hot-path reads do not have to recompute.
CREATE TABLE IF NOT EXISTS character_activity_state (
    character_id              TEXT    PRIMARY KEY REFERENCES characters(id),
    strenuous_days_in_streak  INTEGER NOT NULL DEFAULT 0,
    overtime_days_in_streak   INTEGER NOT NULL DEFAULT 0,
    last_rest_day             INTEGER NOT NULL DEFAULT 0,
    attack_throw_penalty      INTEGER NOT NULL DEFAULT 0,
    last_updated_calendar_day INTEGER NOT NULL DEFAULT 0,
    created_at                TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                TEXT    NOT NULL DEFAULT (datetime('now'))
);

-- Migration 067: Restricted-frequency activity cooldowns (Domain Phase 3).
-- Per-(character, activity_def) cooldown gating Restricted activities per
-- ax_campaign_play.xml §frequency_types L156-158.
CREATE TABLE IF NOT EXISTS restricted_cooldowns (
    campaign_id          TEXT    NOT NULL REFERENCES campaigns(id),
    character_id         TEXT    NOT NULL REFERENCES characters(id),
    activity_def_id      TEXT    NOT NULL,
    cooldown_until_round INTEGER NOT NULL,
    created_at           TEXT    NOT NULL DEFAULT (datetime('now')),
    PRIMARY KEY (character_id, activity_def_id)
);
CREATE INDEX IF NOT EXISTS idx_restricted_cooldowns_campaign
    ON restricted_cooldowns (campaign_id);

-- Migration 069: Troop units (Domain Phase 5 — Troops Tab + Garrison Sub-Tab).
-- Per `daw_armies_recruitment.xml` §army_sources six troop sources: mercenaries,
-- conscripts, militia, followers, slave_soldiers, vassal_troops. monthly_cost_gp
-- is denormalized (= wage + specialist + 4 × weekly supply per
-- daw_campaigns_troop_tables_summary.xml). starting_count drives the 25%-
-- casualties Calamity threshold per §morale_and_loyalty.
CREATE TABLE IF NOT EXISTS troop_units (
    id                       TEXT    PRIMARY KEY,
    campaign_id              TEXT    NOT NULL REFERENCES campaigns(id),
    owner_character_id       TEXT    NOT NULL REFERENCES characters(id),
    assigned_domain_id       TEXT    REFERENCES domains(id),
    assigned_stronghold_id   TEXT    REFERENCES strongholds(id),
    source_type              TEXT    NOT NULL DEFAULT 'mercenary'
        CHECK(source_type IN (
            'mercenary', 'conscript', 'militia',
            'follower', 'slave_soldier', 'vassal',
            'tribal_warrior'  -- Migration 129 (Phase 11D.5)
        )),
    troop_type               TEXT    NOT NULL,
    race                     TEXT    NOT NULL DEFAULT 'human',
    tier                     TEXT    NOT NULL DEFAULT 'average'
        CHECK(tier IN ('untrained', 'average', 'veteran')),
    starting_count           INTEGER NOT NULL DEFAULT 0,
    count                    INTEGER NOT NULL DEFAULT 0,
    battle_rating            REAL    NOT NULL DEFAULT 0.0,
    monthly_wage_cp          INTEGER NOT NULL DEFAULT 0,
    monthly_supply_cp        INTEGER NOT NULL DEFAULT 0,
    monthly_specialist_cp    INTEGER NOT NULL DEFAULT 0,
    monthly_cost_cp          INTEGER NOT NULL DEFAULT 0,
    morale                   INTEGER NOT NULL DEFAULT 0,
    is_veteran               INTEGER NOT NULL DEFAULT 0
        CHECK(is_veteran IN (0, 1)),
    is_trained               INTEGER NOT NULL DEFAULT 1
        CHECK(is_trained IN (0, 1)),
    unit_xp                  INTEGER NOT NULL DEFAULT 0,
    assignment_kind          TEXT    NOT NULL DEFAULT 'available'
        CHECK(assignment_kind IN ('garrison', 'on_campaign', 'available')),
    hire_calendar_day        INTEGER NOT NULL DEFAULT 0,
    equipment_kit            TEXT    NOT NULL DEFAULT '',
    status                   TEXT    NOT NULL DEFAULT 'active'
        CHECK(status IN ('active', 'departed')),
    departure_kind           TEXT    NOT NULL DEFAULT '',
    departure_calendar_day   INTEGER NOT NULL DEFAULT 0,
    -- Migration 088 (Phase 9C): per-unit disease state per RAW daw_vagaries.xml §disease.
    is_diseased                  INTEGER NOT NULL DEFAULT 0
        CHECK(is_diseased IN (0, 1)),
    disease_type                 TEXT    NOT NULL DEFAULT '',
    disease_recovery_calendar_day INTEGER NOT NULL DEFAULT 0,
    disease_save_failed_by       INTEGER NOT NULL DEFAULT 0,
    disease_natural_roll         INTEGER NOT NULL DEFAULT 0,
    -- Migration 090 (Phase 9C polish): per-troop save vs Death.
    -- DiseaseResolver consumes this; defaults by tier are seeded in the migration.
    save_vs_death                INTEGER NOT NULL DEFAULT 14,
    -- Migration 129 (Phase 11D.5): 3-month-spoils morale-trigger counter
    -- for tribal_warrior source_type per gdd-tribal-warriors.md §7. Other
    -- source_types leave it at 0 forever.
    months_without_qualifying_spoils INTEGER NOT NULL DEFAULT 0
        CHECK(months_without_qualifying_spoils >= 0),
    created_at               TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_troop_units_campaign
    ON troop_units (campaign_id);
CREATE INDEX IF NOT EXISTS idx_troop_units_domain
    ON troop_units (assigned_domain_id);
CREATE INDEX IF NOT EXISTS idx_troop_units_owner
    ON troop_units (owner_character_id);
CREATE INDEX IF NOT EXISTS idx_troop_units_stronghold
    ON troop_units (assigned_stronghold_id);
CREATE INDEX IF NOT EXISTS idx_troop_units_diseased
    ON troop_units(is_diseased) WHERE is_diseased = 1;
CREATE INDEX IF NOT EXISTS idx_troop_units_disease_recovery
    ON troop_units(disease_recovery_calendar_day) WHERE is_diseased = 1;

-- Migration 070: Armies (Phase 6A — DaW Army Warfare composition layer).
-- Per gdd-army-warfare.md §2.1 and daw_armies_recruitment.xml. Aggregates
-- troop_units (069) under one apex commander + officer hierarchy (071) +
-- unit assignments (072), with supply state (073) and recon cooldowns (074).
CREATE TABLE IF NOT EXISTS armies (
    id                              TEXT    PRIMARY KEY,
    campaign_id                     TEXT    NOT NULL REFERENCES campaigns(id),
    name                            TEXT    NOT NULL,
    political_owner_id              TEXT    NOT NULL REFERENCES characters(id),
    command_character_id            TEXT    NOT NULL REFERENCES characters(id),
    state                           TEXT    NOT NULL DEFAULT 'assembling'
        CHECK(state IN (
            'assembling', 'encamped', 'marching',
            'requisitioning', 'looting', 'besieging',
            'battling', 'withdrawing', 'disbanded'
        )),
    map_id                          TEXT    REFERENCES hex_maps(id),
    hex_q                           INTEGER,
    hex_r                           INTEGER,
    garrison_stronghold_id          TEXT    REFERENCES strongholds(id),
    formed_calendar_day             INTEGER NOT NULL DEFAULT 0,
    disbanded_calendar_day          INTEGER NOT NULL DEFAULT 0,
    unit_scale                      TEXT    NOT NULL DEFAULT 'platoon'
        CHECK(unit_scale IN ('platoon', 'company', 'battalion', 'brigade')),
    strategic_stance                TEXT    NOT NULL DEFAULT 'defensive'
        CHECK(strategic_stance IN ('offensive', 'defensive', 'evasive')),
    forced_march_bonus_expires_leg_id TEXT NOT NULL DEFAULT '',
    consecutive_marching_days       INTEGER NOT NULL DEFAULT 0,
    last_returned_to_garrison_day_index INTEGER NOT NULL DEFAULT 0,
    daily_penalty_state             TEXT    NOT NULL DEFAULT '{}',
    rng_seed_stream                 INTEGER NOT NULL DEFAULT 0,
    notes                           TEXT    NOT NULL DEFAULT '',
    -- Migration 186: one-off vs standing muster tag driving post-battle teardown.
    -- Code-validated (no CHECK) against ArmyRepository.PROVENANCE_*:
    -- 'standing' | 'resistance_levy' | 'call_to_arms'.
    provenance                      TEXT    NOT NULL DEFAULT 'standing',
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_armies_campaign ON armies(campaign_id);
CREATE INDEX IF NOT EXISTS idx_armies_owner ON armies(political_owner_id);
CREATE INDEX IF NOT EXISTS idx_armies_command ON armies(command_character_id);
CREATE INDEX IF NOT EXISTS idx_armies_state ON armies(state);
CREATE INDEX IF NOT EXISTS idx_armies_hex ON armies(map_id, hex_q, hex_r);

-- Migration 071: Army officers — three-tier hierarchy
-- (army_leader / division_commander / lieutenant) per gdd-army-warfare.md §2.2.
-- Leadership / Strategic / Morale Modifier stored snapshot per RAW
-- (daw_armies_recruitment.xml §officer_characteristics L763-789).
CREATE TABLE IF NOT EXISTS army_officers (
    id                       TEXT    PRIMARY KEY,
    army_id                  TEXT    NOT NULL REFERENCES armies(id),
    character_id             TEXT    NOT NULL REFERENCES characters(id),
    rank                     TEXT    NOT NULL
        CHECK(rank IN ('army_leader', 'division_commander', 'lieutenant', 'former_commander')),
    parent_officer_id        TEXT    REFERENCES army_officers(id),
    leadership_ability       INTEGER NOT NULL DEFAULT 4,
    strategic_ability        INTEGER NOT NULL DEFAULT 0,
    morale_modifier          INTEGER NOT NULL DEFAULT 0,
    derivation_source        TEXT    NOT NULL DEFAULT 'pc'
        CHECK(derivation_source IN (
            'pc', 'henchman', 'mercenary_officer', 'monster', 'named_npc'
        )),
    monthly_wage_cp          INTEGER NOT NULL DEFAULT 0,
    appointed_calendar_day   INTEGER NOT NULL DEFAULT 0,
    removed_calendar_day     INTEGER NOT NULL DEFAULT 0,
    created_at               TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_army_officers_army ON army_officers(army_id);
CREATE INDEX IF NOT EXISTS idx_army_officers_character ON army_officers(character_id);
CREATE INDEX IF NOT EXISTS idx_army_officers_parent ON army_officers(parent_officer_id);

-- Migration 072: Army unit assignments — joins troop_units to armies under
-- a parent_officer per gdd-army-warfare.md §2.3. Partial unique index
-- enforces "at most one active assignment per troop_unit".
CREATE TABLE IF NOT EXISTS army_unit_assignments (
    id                       TEXT    PRIMARY KEY,
    army_id                  TEXT    NOT NULL REFERENCES armies(id),
    troop_unit_id            TEXT    NOT NULL REFERENCES troop_units(id),
    parent_officer_id        TEXT    NOT NULL REFERENCES army_officers(id),
    role                     TEXT    NOT NULL DEFAULT 'line'
        CHECK(role IN ('line', 'reserve', 'baggage', 'scout')),
    assigned_calendar_day    INTEGER NOT NULL DEFAULT 0,
    released_calendar_day    INTEGER NOT NULL DEFAULT 0,
    release_reason           TEXT    NOT NULL DEFAULT ''
        CHECK(release_reason IN (
            '', 'voluntary', 'casualty', 'desertion', 'disband', 'transfer'
        )),
    destination              TEXT    NOT NULL DEFAULT '',
    created_at               TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_army_assignments_army ON army_unit_assignments(army_id);
CREATE INDEX IF NOT EXISTS idx_army_assignments_unit ON army_unit_assignments(troop_unit_id);
CREATE INDEX IF NOT EXISTS idx_army_assignments_officer ON army_unit_assignments(parent_officer_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_army_assignments_active_unit
    ON army_unit_assignments(troop_unit_id)
    WHERE released_calendar_day = 0;

-- Migration 073: Army supply state — weighted-line supply geometry per
-- daw_campaigning_armies.xml §supply L226-374; gdd-army-warfare.md §2.4.
-- One row per army (1:1).
CREATE TABLE IF NOT EXISTS army_supply_state (
    army_id                       TEXT    PRIMARY KEY REFERENCES armies(id),
    supply_base_stronghold_id     TEXT    REFERENCES strongholds(id),
    supply_line_status            TEXT    NOT NULL DEFAULT 'out_of_supply_no_base'
        CHECK(supply_line_status IN (
            'in_supply',
            'out_of_supply_blocked',
            'out_of_supply_overextended',
            'out_of_supply_no_base',
            'simplified'
        )),
    weekly_supply_cost_cp         INTEGER NOT NULL DEFAULT 0,
    current_stockpile_cp          INTEGER NOT NULL DEFAULT 0,
    supply_line_weighted_hexes    INTEGER NOT NULL DEFAULT 0,
    last_supply_check_calendar_day INTEGER NOT NULL DEFAULT 0,
    consecutive_unsupplied_weeks  INTEGER NOT NULL DEFAULT 0,
    requisition_cooldowns_json    TEXT    NOT NULL DEFAULT '{}',
    partial_supply_priority_json  TEXT    NOT NULL DEFAULT '[]',
    created_at                    TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_army_supply_state_status
    ON army_supply_state(supply_line_status);

-- Migration 074: Reconnaissance cooldowns — recon rate-limiting per
-- gdd-army-warfare.md §4.9.6 (1 roll per opposing-army-pair per game-day).
CREATE TABLE IF NOT EXISTS reconnaissance_cooldowns (
    observer_army_id        TEXT    NOT NULL REFERENCES armies(id),
    observed_army_id        TEXT    NOT NULL REFERENCES armies(id),
    last_roll_calendar_day  INTEGER NOT NULL DEFAULT 0,
    last_result             TEXT    NOT NULL DEFAULT '',
    PRIMARY KEY (observer_army_id, observed_army_id)
);
CREATE INDEX IF NOT EXISTS idx_recon_cooldowns_observer
    ON reconnaissance_cooldowns(observer_army_id);

-- Migration 075: Field battles (Phase 6B — DaW abstract battle resolver).
-- Per gdd-army-warfare.md §2.5 + daw_axioms_pitching_battle.xml §battle_resolution
-- L233-386. Renumbered from the GDD's 070 (Phase 5 took 065-069; Phase 6A 070-074).
CREATE TABLE IF NOT EXISTS field_battles (
    id                              TEXT    PRIMARY KEY,
    campaign_id                     TEXT    NOT NULL REFERENCES campaigns(id),
    map_id                          TEXT    REFERENCES hex_maps(id),
    hex_q                           INTEGER NOT NULL DEFAULT 0,
    hex_r                           INTEGER NOT NULL DEFAULT 0,
    attacker_army_id                TEXT    NOT NULL REFERENCES armies(id),
    defender_army_id                TEXT    NOT NULL REFERENCES armies(id),
    terrain_type                    TEXT    NOT NULL DEFAULT 'clear_or_grass',
    starting_bpc                    INTEGER NOT NULL DEFAULT 1,
    current_bpc                     INTEGER NOT NULL DEFAULT 1,
    current_phase                   TEXT    NOT NULL DEFAULT 'missile'
        CHECK(current_phase IN ('missile', 'skirmish', 'melee', 'aftermath', 'concluded')),
    battle_turn_number              INTEGER NOT NULL DEFAULT 1,
    attacker_terrain_advantage      TEXT    NOT NULL DEFAULT 'regular'
        CHECK(attacker_terrain_advantage IN ('regular', 'advantageous', 'highly_advantageous')),
    defender_terrain_advantage      TEXT    NOT NULL DEFAULT 'regular'
        CHECK(defender_terrain_advantage IN ('regular', 'advantageous', 'highly_advantageous')),
    attacker_surprised              INTEGER NOT NULL DEFAULT 0
        CHECK(attacker_surprised IN (0, 1)),
    defender_surprised              INTEGER NOT NULL DEFAULT 0
        CHECK(defender_surprised IN (0, 1)),
    attacker_choice                 TEXT    NOT NULL DEFAULT ''
        CHECK(attacker_choice IN ('', 'advance', 'hold', 'withdraw')),
    defender_choice                 TEXT    NOT NULL DEFAULT ''
        CHECK(defender_choice IN ('', 'advance', 'hold', 'withdraw')),
    outcome                         TEXT    NOT NULL DEFAULT ''
        CHECK(outcome IN (
            '', 'attacker_victory', 'defender_victory',
            'mutual_withdrawal_draw',
            'attacker_voluntary_withdrawal', 'defender_voluntary_withdrawal',
            'attacker_annihilation', 'defender_annihilation'
        )),
    started_calendar_day            INTEGER NOT NULL DEFAULT 0,
    ended_calendar_day              INTEGER NOT NULL DEFAULT 0,
    is_player_involved              INTEGER NOT NULL DEFAULT 0
        CHECK(is_player_involved IN (0, 1)),
    weather_condition               TEXT    NOT NULL DEFAULT 'calm',
    rng_seed                        INTEGER NOT NULL DEFAULT 0,
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_field_battles_campaign ON field_battles(campaign_id);
CREATE INDEX IF NOT EXISTS idx_field_battles_active ON field_battles(outcome) WHERE outcome = '';
CREATE INDEX IF NOT EXISTS idx_field_battles_attacker ON field_battles(attacker_army_id);
CREATE INDEX IF NOT EXISTS idx_field_battles_defender ON field_battles(defender_army_id);

-- Migration 076: Battle unit states — per-unit per-battle state.
-- Per gdd-army-warfare.md §2.5 + daw_axioms_pitching_battle.xml §battle_resolution.
CREATE TABLE IF NOT EXISTS battle_unit_states (
    id                              TEXT    PRIMARY KEY,
    battle_id                       TEXT    NOT NULL REFERENCES field_battles(id),
    troop_unit_id                   TEXT    NOT NULL REFERENCES troop_units(id),
    side                            TEXT    NOT NULL
        CHECK(side IN ('attacker', 'defender')),
    zone                            TEXT    NOT NULL DEFAULT 'melee'
        CHECK(zone IN ('missile', 'skirmish', 'melee', 'reserve')),
    status                          TEXT    NOT NULL DEFAULT 'engaged'
        CHECK(status IN ('engaged', 'wavering', 'fleeing', 'routed', 'destroyed', 'rallied')),
    br_at_battle_start              REAL    NOT NULL DEFAULT 0.0,
    br_current                      REAL    NOT NULL DEFAULT 0.0,
    hits_absorbed_this_phase        INTEGER NOT NULL DEFAULT 0,
    morale_state_modifier           INTEGER NOT NULL DEFAULT 0,
    parent_officer_id               TEXT    REFERENCES army_officers(id),
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_battle_unit_states_battle ON battle_unit_states(battle_id);
CREATE INDEX IF NOT EXISTS idx_battle_unit_states_side ON battle_unit_states(battle_id, side);
CREATE INDEX IF NOT EXISTS idx_battle_unit_states_zone ON battle_unit_states(battle_id, side, zone);

-- Migration 077: Battle log — append-only event trace per gdd-army-warfare.md §2.6.
CREATE TABLE IF NOT EXISTS battle_log (
    id                       TEXT    PRIMARY KEY,
    battle_id                TEXT    NOT NULL REFERENCES field_battles(id),
    sequence_number          INTEGER NOT NULL,
    turn_number              INTEGER NOT NULL DEFAULT 1,
    phase                    TEXT    NOT NULL DEFAULT '',
    bpc_at_event             INTEGER NOT NULL DEFAULT 0,
    event_type               TEXT    NOT NULL,
    side                     TEXT    NOT NULL DEFAULT ''
        CHECK(side IN ('', 'attacker', 'defender')),
    payload_json             TEXT    NOT NULL DEFAULT '{}',
    created_calendar_day     INTEGER NOT NULL DEFAULT 0,
    created_at               TEXT    NOT NULL DEFAULT (datetime('now')),
    UNIQUE (battle_id, sequence_number)
);
CREATE INDEX IF NOT EXISTS idx_battle_log_battle ON battle_log(battle_id, sequence_number);
CREATE INDEX IF NOT EXISTS idx_battle_log_event_type ON battle_log(event_type);

-- Migration 079: vassal_assignments — Phase 7 Realm AI vassalage records.
-- Each row records the liege ↔ vassal relationship (with optional
-- vassal_domain_id), is_henchman_vassal flag (per RAW §non_henchman_vassals),
-- and loyalty roll history. The inverse pointer domains.liege_domain_id
-- (Phase 0) is the source of truth for tribute and apex chain walks.
CREATE TABLE IF NOT EXISTS vassal_assignments (
    id                      TEXT    PRIMARY KEY,
    campaign_id             TEXT    NOT NULL REFERENCES campaigns(id),
    liege_character_id      TEXT    NOT NULL REFERENCES characters(id),
    vassal_character_id     TEXT    NOT NULL REFERENCES characters(id),
    vassal_domain_id        TEXT    REFERENCES domains(id),
    assigned_calendar_day   INTEGER NOT NULL DEFAULT 0,
    status                  TEXT    NOT NULL DEFAULT 'active'
        CHECK(status IN ('active', 'departed', 'revolted', 'deceased')),
    is_henchman_vassal      INTEGER NOT NULL DEFAULT 1
        CHECK(is_henchman_vassal IN (0, 1)),
    base_loyalty_modifier   INTEGER NOT NULL DEFAULT 0,
    last_loyalty_roll_day   INTEGER NOT NULL DEFAULT 0,
    last_loyalty_outcome    TEXT    NOT NULL DEFAULT '',
    created_at              TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at              TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_vassal_assignments_liege
    ON vassal_assignments(liege_character_id);
CREATE INDEX IF NOT EXISTS idx_vassal_assignments_vassal
    ON vassal_assignments(vassal_character_id);
CREATE INDEX IF NOT EXISTS idx_vassal_assignments_domain
    ON vassal_assignments(vassal_domain_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_vassal_assignments_unique_active
    ON vassal_assignments(liege_character_id, vassal_character_id)
    WHERE status = 'active';

-- Migration 080: vassal_obligations — Phase 8 Favors & Duties Monthly System
-- per acore_axioms_strongholds_and_domains.xml §favors_and_duties L352-372.
-- Each row records one favor (granted to vassal) or duty (demanded of
-- vassal). Both ongoing and one-time obligations are stored.
CREATE TABLE IF NOT EXISTS vassal_obligations (
    id                          TEXT    PRIMARY KEY,
    vassal_assignment_id        TEXT    NOT NULL REFERENCES vassal_assignments(id),
    kind                        TEXT    NOT NULL
        CHECK(kind IN ('favor', 'duty')),
    type                        TEXT    NOT NULL,
    magnitude                   INTEGER NOT NULL DEFAULT 0,
    cp_value                    INTEGER NOT NULL DEFAULT 0,
    is_one_time                 INTEGER NOT NULL DEFAULT 0
        CHECK(is_one_time IN (0, 1)),
    issued_calendar_day         INTEGER NOT NULL DEFAULT 0,
    due_calendar_day            INTEGER NOT NULL DEFAULT 0,
    status                      TEXT    NOT NULL DEFAULT 'active'
        CHECK(status IN ('active', 'revoked', 'completed', 'defaulted')),
    loyalty_modifier_applied    INTEGER NOT NULL DEFAULT 0,
    -- Migration 089 (Phase 9C): magnitude_pct for call_to_arms (% of vassal
    -- realm garrison called). 50=half (default), 100=full garrison (counts
    -- as 2 duties per RAW daw_armies_recruitment.xml §vassal_troops L660).
    magnitude_pct               INTEGER NOT NULL DEFAULT 50,
    created_at                  TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_vassal_obligations_assignment
    ON vassal_obligations(vassal_assignment_id);
CREATE INDEX IF NOT EXISTS idx_vassal_obligations_kind
    ON vassal_obligations(vassal_assignment_id, kind, status);
CREATE INDEX IF NOT EXISTS idx_vassal_obligations_status
    ON vassal_obligations(status);

-- Migration 089: call_to_arms_state — Phase 9C call-to-arms muster lifecycle.
CREATE TABLE IF NOT EXISTS call_to_arms_state (
    id                          TEXT    PRIMARY KEY,
    obligation_id               TEXT    NOT NULL REFERENCES vassal_obligations(id),
    lord_army_id                TEXT    NOT NULL REFERENCES armies(id),
    vassal_character_id         TEXT    NOT NULL REFERENCES characters(id),
    issued_calendar_day         INTEGER NOT NULL,
    period_unit                 TEXT    NOT NULL DEFAULT 'week'
        CHECK(period_unit IN ('week', 'month', 'season')),
    period_days                 INTEGER NOT NULL DEFAULT 7,
    target_total_units          INTEGER NOT NULL DEFAULT 0,
    units_arrived_first_tranche  INTEGER NOT NULL DEFAULT 0,
    units_arrived_second_tranche INTEGER NOT NULL DEFAULT 0,
    units_arrived_third_tranche  INTEGER NOT NULL DEFAULT 0,
    is_completed                INTEGER NOT NULL DEFAULT 0
        CHECK(is_completed IN (0, 1)),
    revoked_calendar_day        INTEGER NOT NULL DEFAULT 0,
    payload_json                TEXT    NOT NULL DEFAULT '{}',
    created_at                  TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_call_to_arms_state_obligation
    ON call_to_arms_state(obligation_id);
CREATE INDEX IF NOT EXISTS idx_call_to_arms_state_lord_army
    ON call_to_arms_state(lord_army_id);
CREATE INDEX IF NOT EXISTS idx_call_to_arms_state_vassal
    ON call_to_arms_state(vassal_character_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_call_to_arms_state_unique_active
    ON call_to_arms_state(obligation_id) WHERE revoked_calendar_day = 0;

-- Migration 082: domain_threats — Phase 9A active-threat tracking per
-- ax_domain_level_encounters.xml + acore_axioms §bandits L611-630.
-- Kinds: encounter / bandit_swarm / npc_challenger / settled_lair /
--   hostile_extraction (migration 185 — an NPC army looting/requisitioning
--   the player's domain; the player Resists or Concedes from the threats sub-tab).
-- Partial unique indexes ensure at most one active bandit_swarm and
-- npc_challenger per domain, and at most one active hostile_extraction per
-- (domain, raider army).
CREATE TABLE IF NOT EXISTS domain_threats (
    id                          TEXT    PRIMARY KEY,
    campaign_id                 TEXT    NOT NULL REFERENCES campaigns(id),
    domain_id                   TEXT    NOT NULL REFERENCES domains(id),
    kind                        TEXT    NOT NULL
        CHECK(kind IN ('encounter', 'bandit_swarm', 'npc_challenger', 'settled_lair', 'hostile_extraction')),
    status                      TEXT    NOT NULL DEFAULT 'active'
        CHECK(status IN ('active', 'defeated', 'negotiated', 'departed')),
    creature_key                TEXT    NOT NULL DEFAULT '',
    creature_count              INTEGER NOT NULL DEFAULT 0,
    platoon_br                  REAL    NOT NULL DEFAULT 0.0,
    is_lair                     INTEGER NOT NULL DEFAULT 0
        CHECK(is_lair IN (0, 1)),
    is_lingering                INTEGER NOT NULL DEFAULT 0
        CHECK(is_lingering IN (0, 1)),
    reaction                    TEXT    NOT NULL DEFAULT ''
        CHECK(reaction IN ('', 'hostile', 'unfriendly', 'neutral', 'mercantilist', 'friendly')),
    bandit_count                INTEGER NOT NULL DEFAULT 0,
    challenger_character_id     TEXT    REFERENCES characters(id),
    challenger_level            INTEGER NOT NULL DEFAULT 0,
    linked_army_id              TEXT    REFERENCES armies(id),
    linked_hex_q                INTEGER,
    linked_hex_r                INTEGER,
    morale_penalty              INTEGER NOT NULL DEFAULT 0,
    spawned_calendar_day        INTEGER NOT NULL DEFAULT 0,
    resolved_calendar_day       INTEGER NOT NULL DEFAULT 0,
    payload_json                TEXT    NOT NULL DEFAULT '{}',
    created_at                  TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_domain_threats_domain ON domain_threats(domain_id);
CREATE INDEX IF NOT EXISTS idx_domain_threats_status ON domain_threats(status, domain_id);
CREATE INDEX IF NOT EXISTS idx_domain_threats_linked_army
    ON domain_threats(linked_army_id) WHERE linked_army_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_domain_threats_unique_active_bandit_swarm
    ON domain_threats(domain_id) WHERE kind = 'bandit_swarm' AND status = 'active';
CREATE UNIQUE INDEX IF NOT EXISTS idx_domain_threats_unique_active_challenger
    ON domain_threats(domain_id) WHERE kind = 'npc_challenger' AND status = 'active';
CREATE UNIQUE INDEX IF NOT EXISTS idx_domain_threats_unique_active_hostile_extraction
    ON domain_threats(domain_id, linked_army_id) WHERE kind = 'hostile_extraction' AND status = 'active';

-- Migration 083: market_class_modifiers — Phase 9A temporary market-class
-- shifts driven by Vagaries-of-Recruitment commerce_disrupted/commerce_improves
-- and Vagaries-of-War war_profiteers (price multiplier).
CREATE TABLE IF NOT EXISTS market_class_modifiers (
    id                          TEXT    PRIMARY KEY,
    campaign_id                 TEXT    NOT NULL REFERENCES campaigns(id),
    settlement_entrance_id      TEXT    REFERENCES settlement_entrances(id),
    source_kind                 TEXT    NOT NULL DEFAULT 'unknown'
        CHECK(source_kind IN (
            'unknown',
            'vagary_recruitment_commerce_disrupted',
            'vagary_recruitment_commerce_improves',
            'vagary_war_war_profiteers',
            'manual'
        )),
    delta                       INTEGER NOT NULL DEFAULT 0,
    price_multiplier_pct        INTEGER NOT NULL DEFAULT 100,
    affected_categories         TEXT    NOT NULL DEFAULT '',
    issued_calendar_day         INTEGER NOT NULL DEFAULT 0,
    expires_calendar_day        INTEGER NOT NULL DEFAULT 0,
    status                      TEXT    NOT NULL DEFAULT 'active'
        CHECK(status IN ('active', 'expired', 'revoked')),
    payload_json                TEXT    NOT NULL DEFAULT '{}',
    created_at                  TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_market_class_modifiers_settlement
    ON market_class_modifiers(settlement_entrance_id, status);
CREATE INDEX IF NOT EXISTS idx_market_class_modifiers_campaign
    ON market_class_modifiers(campaign_id, status);
CREATE INDEX IF NOT EXISTS idx_market_class_modifiers_expiry
    ON market_class_modifiers(expires_calendar_day, status)
    WHERE status = 'active';

-- Migration 084: sieges — Phase 9B Full DaW siege subsystem (state row).
CREATE TABLE IF NOT EXISTS sieges (
    id                          TEXT PRIMARY KEY,
    campaign_id                 TEXT NOT NULL REFERENCES campaigns(id),
    stronghold_id               TEXT NOT NULL REFERENCES strongholds(id),
    domain_id                   TEXT REFERENCES domains(id),
    besieging_army_id           TEXT NOT NULL REFERENCES armies(id),
    defending_army_id           TEXT REFERENCES armies(id),
    map_id                      TEXT REFERENCES hex_maps(id),
    hex_q                       INTEGER,
    hex_r                       INTEGER,
    resolution_mode             TEXT    NOT NULL DEFAULT 'simplified'
        CHECK(resolution_mode IN ('simplified', 'full')),
    current_phase               TEXT    NOT NULL DEFAULT 'blockade'
        CHECK(current_phase IN ('blockade', 'reduction', 'assault', 'concluded')),
    starting_shp                INTEGER NOT NULL,
    current_shp                 INTEGER NOT NULL,
    damage_dealt_total          INTEGER NOT NULL DEFAULT 0,
    damage_repaired_total       INTEGER NOT NULL DEFAULT 0,
    breach_count                INTEGER NOT NULL DEFAULT 0,
    unit_capacity               INTEGER NOT NULL,
    material                    TEXT    NOT NULL DEFAULT 'stone'
        CHECK(material IN ('stone', 'wood')),
    is_blockaded                INTEGER NOT NULL DEFAULT 0
        CHECK(is_blockaded IN (0, 1)),
    blockade_method             TEXT    NOT NULL DEFAULT ''
        CHECK(blockade_method IN ('', 'units', 'ships', 'fortifications', 'mixed')),
    circumvallation_feet        INTEGER NOT NULL DEFAULT 0,
    is_circumvallation_complete INTEGER NOT NULL DEFAULT 0
        CHECK(is_circumvallation_complete IN (0, 1)),
    water_facing_pct            INTEGER NOT NULL DEFAULT 0,
    stored_supplies_cp          INTEGER NOT NULL,
    weeks_unsupplied            INTEGER NOT NULL DEFAULT 0,
    starvation_penalty_stacks   INTEGER NOT NULL DEFAULT 0,
    simplified_total_days       INTEGER NOT NULL DEFAULT 0,
    simplified_site_modifier    REAL    NOT NULL DEFAULT 1.0,
    started_calendar_day        INTEGER NOT NULL,
    expected_end_calendar_day   INTEGER NOT NULL DEFAULT 0,
    concluded_calendar_day      INTEGER NOT NULL DEFAULT 0,
    outcome                     TEXT    NOT NULL DEFAULT ''
        CHECK(outcome IN ('', 'captured', 'liberated', 'destroyed', 'surrendered',
                          'departed', 'sallied_won', 'sallied_lost')),
    -- Phase D (migration 184): defender posture. 'undecided' = pre-Phase-D behavior; the
    -- withstand_siege action sets 'hold_fast' (garrison holds inside, no sortie). Read ONLY in
    -- the voluntary 'sally' branch of siege_resolver.apply_method.
    defender_posture            TEXT    NOT NULL DEFAULT 'undecided',
    payload_json                TEXT    NOT NULL DEFAULT '{}',
    created_at                  TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_sieges_stronghold ON sieges(stronghold_id);
CREATE INDEX IF NOT EXISTS idx_sieges_domain     ON sieges(domain_id);
CREATE INDEX IF NOT EXISTS idx_sieges_besieger   ON sieges(besieging_army_id);
CREATE INDEX IF NOT EXISTS idx_sieges_campaign   ON sieges(campaign_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_sieges_unique_active_per_stronghold
    ON sieges(stronghold_id) WHERE current_phase != 'concluded';

-- Migration 085: siege_actions — Phase 9B per-action ledger.
CREATE TABLE IF NOT EXISTS siege_actions (
    id                  TEXT    PRIMARY KEY,
    siege_id            TEXT    NOT NULL REFERENCES sieges(id),
    calendar_day        INTEGER NOT NULL,
    actor_side          TEXT    NOT NULL
        CHECK(actor_side IN ('besieger', 'defender')),
    action_type         TEXT    NOT NULL
        CHECK(action_type IN (
            'bombardment', 'artillery_duel', 'siege_mining_progress',
            'siege_mining_detonation', 'countermining_progress', 'magic_reduction',
            'arson', 'subversion', 'subversion_breach_expired',
            'smuggling', 'sabotage', 'repair', 'sally',
            'surrender_offer', 'surrender_accepted', 'assault_turn',
            'circumvallation_progress', 'supplies_consumed',
            'starvation_penalty', 'mining_accident', 'blockade_completed'
        )),
    shp_damage_dealt    INTEGER NOT NULL DEFAULT 0,
    shp_repaired        INTEGER NOT NULL DEFAULT 0,
    breaches_added      INTEGER NOT NULL DEFAULT 0,
    supplies_delta_cp   INTEGER NOT NULL DEFAULT 0,
    related_battle_id   TEXT    REFERENCES field_battles(id),
    payload_json        TEXT    NOT NULL DEFAULT '{}',
    created_at          TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_siege_actions_siege
    ON siege_actions(siege_id, calendar_day);
CREATE INDEX IF NOT EXISTS idx_siege_actions_type
    ON siege_actions(siege_id, action_type);

-- Migration 086: siege_artillery — Phase 9B per-side artillery and siege equipment.
CREATE TABLE IF NOT EXISTS siege_artillery (
    id              TEXT    PRIMARY KEY,
    siege_id        TEXT    NOT NULL REFERENCES sieges(id),
    side            TEXT    NOT NULL
        CHECK(side IN ('besieger', 'defender')),
    equipment_type  TEXT    NOT NULL,
    count           INTEGER NOT NULL DEFAULT 1,
    is_destroyed    INTEGER NOT NULL DEFAULT 0
        CHECK(is_destroyed IN (0, 1)),
    notes           TEXT    NOT NULL DEFAULT '',
    created_at      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_siege_artillery_siege
    ON siege_artillery(siege_id, side);

-- Migration 087: siege_mines — Phase 9B siege mining and countermining state.
CREATE TABLE IF NOT EXISTS siege_mines (
    id                          TEXT    PRIMARY KEY,
    siege_id                    TEXT    NOT NULL REFERENCES sieges(id),
    side                        TEXT    NOT NULL
        CHECK(side IN ('besieger', 'defender')),
    supervising_engineer_id     TEXT    REFERENCES characters(id),
    workers_assigned            INTEGER NOT NULL DEFAULT 0
        CHECK(workers_assigned BETWEEN 0 AND 100),
    cubic_feet_total            INTEGER NOT NULL DEFAULT 20000,
    cubic_feet_completed        INTEGER NOT NULL DEFAULT 0,
    construction_rate_cp_per_day INTEGER NOT NULL DEFAULT 0,
    petard_damage               INTEGER NOT NULL DEFAULT 0,
    is_detected                 INTEGER NOT NULL DEFAULT 0
        CHECK(is_detected IN (0, 1)),
    detected_calendar_day       INTEGER NOT NULL DEFAULT 0,
    is_completed                INTEGER NOT NULL DEFAULT 0
        CHECK(is_completed IN (0, 1)),
    is_destroyed_by_accident    INTEGER NOT NULL DEFAULT 0
        CHECK(is_destroyed_by_accident IN (0, 1)),
    detonated_calendar_day      INTEGER NOT NULL DEFAULT 0,
    countermine_target_id       TEXT    REFERENCES siege_mines(id),
    started_calendar_day        INTEGER NOT NULL DEFAULT 0,
    created_at                  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_siege_mines_siege
    ON siege_mines(siege_id, side);
CREATE INDEX IF NOT EXISTS idx_siege_mines_active
    ON siege_mines(siege_id)
    WHERE is_completed = 0 AND is_destroyed_by_accident = 0;
-- Migration 091: Faith block (Domain Phase 10A.2).
--
-- Tables backing the divine-caster surface (Cleric / Bladedancer / Priestess /
-- Shaman / Dwarven Craftpriest / Witch / Lightblessed Wonderworker). RAW
-- citations from ax_campaign_play.xml §divine L380-500 and §end_of_month
-- L109-112.
--
-- Per Q11 [RESOLVED 2026-05-10]: divine casters with full spell_research also
-- get the Magical Research bucket; their research projects use the Phase 10B.1
-- magic_research_projects table (separate from this migration's tables).


-- congregants: per-character-per-domain congregant count + pending-gp accumulator.
-- Migration 128 (Phase 11D.3 / gdd-religion-conversion.md §4.1): rebuilt to
-- per-character-per-domain. The conversion mechanic needs to know how many
-- of a caster's congregants live in each domain, since the 60% completion
-- threshold sums target-religion congregants WITHIN the conversion's target
-- domain, not the caster's lifetime total.
--
-- The pending-gp accumulator tracks gp committed THIS month (via missionaries,
-- charitable spells, or ceremonial sacrifices) that will roll into next
-- month's growth roll. The growth roll happens in the domain monthly tick
-- (1d10 + Cha mod per 1,000 gp per ax_campaign_play.xml §congregant_growth
-- L20-22), AFTER which monthly_growth_pending_cp is reduced by the gp that
-- triggered the rolls.
--
-- domain_id may be '' sentinel for dev-test rows where no primary domain
-- is resolvable. No FK on domain_id — the row tracks even after domain
-- teardown (per GDD §4.1).
CREATE TABLE IF NOT EXISTS congregants (
    id                             TEXT    PRIMARY KEY,
    character_id                   TEXT    NOT NULL REFERENCES characters(id),
    domain_id                      TEXT    NOT NULL DEFAULT '',
    count                          INTEGER NOT NULL DEFAULT 0
        CHECK(count >= 0),
    monthly_growth_pending_cp      INTEGER NOT NULL DEFAULT 0
        CHECK(monthly_growth_pending_cp >= 0),
    last_resolved_calendar_day     INTEGER NOT NULL DEFAULT 0,
    created_at                     TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                     TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_congregants_caster_domain
    ON congregants(character_id, domain_id);
CREATE INDEX IF NOT EXISTS idx_congregants_domain
    ON congregants(domain_id);

-- domain_religion_conversion: active conversion arcs per
-- gdd-religion-conversion.md §4.1. One row per arc; one active arc per
-- domain (enforced by repository-level check at write).
-- Migration 128 (Phase 11D.3).
CREATE TABLE IF NOT EXISTS domain_religion_conversion (
    id                          TEXT    PRIMARY KEY,
    campaign_id                 TEXT    NOT NULL REFERENCES campaigns(id),
    domain_id                   TEXT    NOT NULL REFERENCES domains(id),
    from_religion               TEXT    NOT NULL,
    to_religion                 TEXT    NOT NULL,
    from_alignment              TEXT    NOT NULL
        CHECK(from_alignment IN ('lawful', 'neutral', 'chaotic')),
    to_alignment                TEXT    NOT NULL
        CHECK(to_alignment IN ('lawful', 'neutral', 'chaotic')),
    progress_pct                INTEGER NOT NULL DEFAULT 0
        CHECK(progress_pct BETWEEN 0 AND 100),
    driving_character_id        TEXT    REFERENCES characters(id),
    started_calendar_day        INTEGER NOT NULL,
    last_progressed_calendar_day INTEGER NOT NULL DEFAULT 0,
    status                      TEXT    NOT NULL DEFAULT 'active'
        CHECK(status IN ('active', 'completed', 'aborted', 'failed_morale')),
    total_invested_cp           INTEGER NOT NULL DEFAULT 0,
    months_at_rebellious        INTEGER NOT NULL DEFAULT 0
        CHECK(months_at_rebellious >= 0),
    created_at                  TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_drc_domain_active
    ON domain_religion_conversion(domain_id, status);
CREATE INDEX IF NOT EXISTS idx_drc_campaign_active
    ON domain_religion_conversion(campaign_id, status);


-- character_divine_power: per-character divine-power gp balance.
-- Per ax_campaign_play.xml §extract_divine_power L460-473, divine power is
-- generated weekly via extract_divine_power activity (10 gp per 50 congregants
-- + 0..8 gp per 10 families if ruler/spiritual advisor). It is NOT auto-
-- accumulated; the caster must take the activity each week.
-- Per §perform_blood_sacrifice L475-487: chaotic divine casters generate DP
-- equal to creature XP value.
-- Per §consecrate_fields L423-439 + §consecrate_ruler L441-458: DP is spent
-- on consecration activities (2 gp per family for fields; equal to monthly
-- revenue for ruler).
-- Per §consecrate_altar L408-421 rule "Divine power may be spent in lieu of
-- gp if a humbler-looking altar is desired": DP can substitute for gp on
-- altar construction (optional, player toggle).
CREATE TABLE IF NOT EXISTS character_divine_power (
    character_id                  TEXT    PRIMARY KEY REFERENCES characters(id),
    divine_power_cp               INTEGER NOT NULL DEFAULT 0
        CHECK(divine_power_cp >= 0),
    last_extraction_calendar_day  INTEGER NOT NULL DEFAULT 0,
    created_at                    TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                    TEXT    NOT NULL DEFAULT (datetime('now'))
);


-- consecrated_altars: consecration projects (in-progress) + completed altars.
-- Per ax_campaign_play.xml §consecrate_altar L408-421: 1 day per 500 gp of
-- altar value. Aura size = 100 sq ft per 100 gp spent. A chaotic-aligned
-- altar creates a "sinkhole of evil"; lawful creates a "pinnacle of good".
-- Once consecrated, the altar's aura persists until dispelled or the altar
-- is physically broken and blessed.
--
-- location_kind: where the altar is physically situated. v1 supports the
-- four enumerated values; future variants (e.g. on-board-a-ship) can extend
-- the CHECK constraint.
-- location_ref: the id of the location (stronghold_id, settlement_entrance_id,
-- hex coordinates encoded as JSON, dungeon_room_id) per location_kind.
CREATE TABLE IF NOT EXISTS consecrated_altars (
    id                       TEXT    PRIMARY KEY,
    character_id             TEXT    NOT NULL REFERENCES characters(id),
    location_kind            TEXT    NOT NULL DEFAULT 'stronghold'
        CHECK(location_kind IN ('stronghold', 'settlement_poi', 'wilderness_hex', 'dungeon_room')),
    location_ref             TEXT    NOT NULL DEFAULT '',
    cp_invested              INTEGER NOT NULL DEFAULT 0
        CHECK(cp_invested >= 0),
    dp_substituted_cp        INTEGER NOT NULL DEFAULT 0
        CHECK(dp_substituted_cp >= 0),
    alignment                TEXT    NOT NULL DEFAULT 'lawful'
        CHECK(alignment IN ('lawful', 'neutral', 'chaotic')),
    aura_size_sq_ft          INTEGER NOT NULL DEFAULT 0
        CHECK(aura_size_sq_ft >= 0),
    completion_pct           INTEGER NOT NULL DEFAULT 0
        CHECK(completion_pct BETWEEN 0 AND 100),
    status                   TEXT    NOT NULL DEFAULT 'in_progress'
        CHECK(status IN ('in_progress', 'completed', 'broken_unblessed')),
    started_calendar_day     INTEGER NOT NULL DEFAULT 0,
    completed_calendar_day   INTEGER,
    created_at               TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at               TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_consecrated_altars_character ON consecrated_altars(character_id);
CREATE INDEX IF NOT EXISTS idx_consecrated_altars_status    ON consecrated_altars(status);


-- pending_divine_effects: queue of delayed / continuous effects produced by
-- consecrate_fields (one-shot land-value bump fires on next monthly tick) and
-- consecrate_ruler (12-month buff window). Future divine effect kinds can
-- extend the effect_kind CHECK constraint without schema change.
--
-- Lifecycle:
--   * status='pending' AND applies_at_calendar_day <= now → apply the effect,
--     transition to 'applied'.
--   * status='applied' AND expires_at_calendar_day > 0 AND expires_at <= now
--     → transition to 'expired'. (One-shot effects set expires_at = 0 so they
--     stay 'applied' permanently after firing.)
--   * Continuous buffs (consecrate_ruler) are checked each monthly tick: if
--     a row exists with status='applied' AND expires_at > now, apply the
--     buff this month.
--
-- effect_payload_json: per-effect data shape. Examples:
--   consecrate_fields_land_value: {"delta_gp_per_family": +1, "peasant_families": N}
--   consecrate_ruler_buff:        {"base_morale_bonus": 1, "vassal_loyalty_bonus": 1, "double_vagary_rolls": true}
CREATE TABLE IF NOT EXISTS pending_divine_effects (
    id                       TEXT    PRIMARY KEY,
    domain_id                TEXT    REFERENCES domains(id),
    character_id             TEXT    REFERENCES characters(id),
    effect_kind              TEXT    NOT NULL
        CHECK(effect_kind IN (
            'consecrate_fields_land_value',
            'consecrate_ruler_buff'
        )),
    effect_payload_json      TEXT    NOT NULL DEFAULT '{}',
    issued_calendar_day      INTEGER NOT NULL DEFAULT 0,
    applies_at_calendar_day  INTEGER NOT NULL DEFAULT 0,
    expires_at_calendar_day  INTEGER NOT NULL DEFAULT 0,
    status                   TEXT    NOT NULL DEFAULT 'pending'
        CHECK(status IN ('pending', 'applied', 'expired', 'cancelled')),
    created_at               TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at               TEXT    NOT NULL DEFAULT (datetime('now')),
    CHECK ((domain_id IS NOT NULL) OR (character_id IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS idx_pending_divine_effects_apply
    ON pending_divine_effects(applies_at_calendar_day, status);
CREATE INDEX IF NOT EXISTS idx_pending_divine_effects_expire
    ON pending_divine_effects(expires_at_calendar_day, status)
    WHERE status = 'applied';
CREATE INDEX IF NOT EXISTS idx_pending_divine_effects_domain
    ON pending_divine_effects(domain_id);
CREATE INDEX IF NOT EXISTS idx_pending_divine_effects_character
    ON pending_divine_effects(character_id);


-- Migration 093: Magical Research block (Domain Phase 10B.1a).
--
-- Tables backing the arcane-caster + Lightblessed Wonderworker surface.
-- Per Q15-Q25 [RESOLVED 2026-05-11]: schema + UI shell only in 10B.1a;
-- activity handlers + monthly-tick promotion-roll logic ship in
-- 10B.1b-h. See generation/gdd-domain-tab.md §12.4 + §12.7 and
-- docs/phase-10-plan.md §10B.1 for the surface spec.

CREATE TABLE IF NOT EXISTS magic_research_projects (
    id                          TEXT    PRIMARY KEY,
    campaign_id                 TEXT    NOT NULL REFERENCES campaigns(id),
    character_id                TEXT    NOT NULL REFERENCES characters(id),
    project_kind                TEXT    NOT NULL DEFAULT 'spell'
        CHECK(project_kind IN ('spell', 'magic_item', 'construct', 'monster')),
    target_spell_key            TEXT    NOT NULL DEFAULT '',
    target_spell_level          INTEGER NOT NULL DEFAULT 0,
    target_item_kind            TEXT    NOT NULL DEFAULT '',
    cp_committed                INTEGER NOT NULL DEFAULT 0
        CHECK(cp_committed >= 0),
    days_total                  INTEGER NOT NULL DEFAULT 0
        CHECK(days_total >= 0),
    days_completed              INTEGER NOT NULL DEFAULT 0
        CHECK(days_completed >= 0),
    target_value                INTEGER NOT NULL DEFAULT 18
        CHECK(target_value BETWEEN 3 AND 30),
    library_id                  TEXT REFERENCES libraries(id),
    workshop_id                 TEXT REFERENCES workshops(id),
    status                      TEXT    NOT NULL DEFAULT 'in_progress'
        CHECK(status IN ('in_progress', 'completed', 'abandoned', 'failed')),
    started_calendar_day        INTEGER NOT NULL DEFAULT 0,
    completed_calendar_day      INTEGER,
    params_json                 TEXT    NOT NULL DEFAULT '{}',
    created_at                  TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_magic_research_projects_character
    ON magic_research_projects (character_id);
CREATE INDEX IF NOT EXISTS idx_magic_research_projects_status
    ON magic_research_projects (status);

CREATE TABLE IF NOT EXISTS libraries (
    id                                TEXT    PRIMARY KEY,
    campaign_id                       TEXT    NOT NULL REFERENCES campaigns(id),
    owner_character_id                TEXT    NOT NULL REFERENCES characters(id),
    stronghold_id                     TEXT REFERENCES strongholds(id),
    structure_kind                    TEXT    NOT NULL DEFAULT 'sanctum_library'
        CHECK(structure_kind IN (
            'sanctum_library', 'tower_library', 'tower_workshop_library', 'other'
        )),
    cp_invested                       INTEGER NOT NULL DEFAULT 0
        CHECK(cp_invested >= 0),
    max_spell_level_supported         INTEGER NOT NULL DEFAULT 1
        CHECK(max_spell_level_supported BETWEEN 1 AND 9),
    magic_research_throw_bonus        INTEGER NOT NULL DEFAULT 0
        CHECK(magic_research_throw_bonus BETWEEN 0 AND 4),
    status                            TEXT    NOT NULL DEFAULT 'operational'
        CHECK(status IN ('building', 'operational', 'damaged', 'destroyed')),
    created_calendar_day              INTEGER NOT NULL DEFAULT 0,
    created_at                        TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                        TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_libraries_owner       ON libraries (owner_character_id);
CREATE INDEX IF NOT EXISTS idx_libraries_stronghold  ON libraries (stronghold_id);
CREATE INDEX IF NOT EXISTS idx_libraries_status      ON libraries (status);

CREATE TABLE IF NOT EXISTS workshops (
    id                                TEXT    PRIMARY KEY,
    campaign_id                       TEXT    NOT NULL REFERENCES campaigns(id),
    owner_character_id                TEXT    NOT NULL REFERENCES characters(id),
    stronghold_id                     TEXT REFERENCES strongholds(id),
    structure_kind                    TEXT    NOT NULL DEFAULT 'tower_workshop'
        CHECK(structure_kind IN (
            'tower_workshop', 'sanctum_workshop', 'other'
        )),
    cp_invested                       INTEGER NOT NULL DEFAULT 0
        CHECK(cp_invested >= 0),
    max_item_value_supported_cp       INTEGER NOT NULL DEFAULT 0
        CHECK(max_item_value_supported_cp >= 0),
    magic_research_throw_bonus        INTEGER NOT NULL DEFAULT 0
        CHECK(magic_research_throw_bonus BETWEEN 0 AND 4),
    status                            TEXT    NOT NULL DEFAULT 'operational'
        CHECK(status IN ('building', 'operational', 'damaged', 'destroyed')),
    created_calendar_day              INTEGER NOT NULL DEFAULT 0,
    created_at                        TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                        TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_workshops_owner       ON workshops (owner_character_id);
CREATE INDEX IF NOT EXISTS idx_workshops_stronghold  ON workshops (stronghold_id);
CREATE INDEX IF NOT EXISTS idx_workshops_status      ON workshops (status);

CREATE TABLE IF NOT EXISTS followers (
    id                        TEXT    PRIMARY KEY,
    campaign_id               TEXT    NOT NULL REFERENCES campaigns(id),
    owner_character_id        TEXT    NOT NULL REFERENCES characters(id),
    stronghold_id             TEXT REFERENCES strongholds(id),
    source_kind               TEXT    NOT NULL DEFAULT 'generic'
        CHECK(source_kind IN (
            'aspirant',
            'class_follower',
            'race_follower',
            'bardic_recruit',
            'venturer_apprentice',
            'syndicate_member',
            'generic'
        )),
    intended_class            TEXT    NOT NULL DEFAULT ''
        CHECK(intended_class IN (
            '', 'mage', 'cleric', 'witch', 'warlock', 'elven_enchanter'
        )),
    name                      TEXT    NOT NULL,
    race                      TEXT    NOT NULL DEFAULT 'human',
    character_class           TEXT    NOT NULL DEFAULT 'normal_man',
    combat_progression        TEXT    NOT NULL DEFAULT 'fighter'
        CHECK(combat_progression IN ('fighter', 'cleric', 'thief', 'mage')),
    level                     INTEGER NOT NULL DEFAULT 0
        CHECK(level >= 0),
    xp                        INTEGER NOT NULL DEFAULT 0
        CHECK(xp >= 0),
    alignment                 TEXT    NOT NULL DEFAULT 'neutral'
        CHECK(alignment IN ('lawful', 'neutral', 'chaotic')),
    strength                  INTEGER NOT NULL DEFAULT 10,
    intelligence              INTEGER NOT NULL DEFAULT 10,
    wisdom                    INTEGER NOT NULL DEFAULT 10,
    dexterity                 INTEGER NOT NULL DEFAULT 10,
    constitution              INTEGER NOT NULL DEFAULT 10,
    charisma                  INTEGER NOT NULL DEFAULT 10,
    hp_max                    INTEGER NOT NULL DEFAULT 1,
    hp_current                INTEGER NOT NULL DEFAULT 1,
    status                    TEXT    NOT NULL DEFAULT 'present'
        CHECK(status IN (
            'aspirant_in_training',
            'present',
            'on_adventure',
            'departed',
            'promoted_to_henchman',
            'failed_promotion'
        )),
    joined_calendar_day       INTEGER NOT NULL DEFAULT 0,
    promotion_eligible_day    INTEGER,
    departed_day              INTEGER,
    promoted_to_henchman_id   TEXT REFERENCES characters(id),
    notes                     TEXT    NOT NULL DEFAULT '',
    params_json               TEXT    NOT NULL DEFAULT '{}',
    created_at                TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_followers_owner       ON followers (owner_character_id);
CREATE INDEX IF NOT EXISTS idx_followers_stronghold  ON followers (stronghold_id);
CREATE INDEX IF NOT EXISTS idx_followers_status      ON followers (status);
CREATE INDEX IF NOT EXISTS idx_followers_source_kind ON followers (source_kind);
CREATE INDEX IF NOT EXISTS idx_followers_promotion_day
    ON followers (promotion_eligible_day, status)
    WHERE status = 'aspirant_in_training';


-- Migration 094: Magic item enchanting (Domain Phase 10B.1c).
--
-- Runtime-mutable catalog of player-crafted magic items. Deliberately
-- separate from the static data/equipment/*.json catalog consumed by
-- ShopInventoryGenerator so shops will NOT see crafted items. Each row IS
-- the formula per RAW §formulas_and_samples L151 "A spellcaster automatically
-- has a formula for any magic item he has previously created."

CREATE TABLE IF NOT EXISTS crafted_magic_items (
    id                              TEXT    PRIMARY KEY,
    campaign_id                     TEXT    NOT NULL REFERENCES campaigns(id),
    creator_character_id            TEXT    NOT NULL REFERENCES characters(id),
    name                            TEXT    NOT NULL,
    item_category                   TEXT    NOT NULL DEFAULT 'wondrous'
        CHECK(item_category IN (
            'weapon', 'armor', 'shield',
            'scroll', 'potion',
            'wand', 'rod', 'staff', 'ring', 'wondrous'
        )),
    base_item_key                   TEXT    NOT NULL DEFAULT '',
    effect_kind                     TEXT    NOT NULL DEFAULT 'one_use'
        CHECK(effect_kind IN (
            'one_use',
            'charged',
            'permanent_unlimited',
            'permanent_per_turn',
            'permanent_per_3_turns',
            'permanent_per_hour',
            'permanent_3_per_day',
            'permanent_per_day',
            'permanent_per_week',
            'weapon_plus_1', 'weapon_plus_2', 'weapon_plus_3',
            'armor_plus_1',  'armor_plus_2',  'armor_plus_3'
        )),
    primary_spell_key               TEXT    NOT NULL DEFAULT '',
    primary_spell_level             INTEGER NOT NULL DEFAULT 0
        CHECK(primary_spell_level >= 0),
    spell_keys_json                 TEXT    NOT NULL DEFAULT '[]',
    charges_max                     INTEGER,
    charges_remaining               INTEGER,
    magical_bonus                   INTEGER NOT NULL DEFAULT 0
        CHECK(magical_bonus >= 0 AND magical_bonus <= 3),
    weapon_damage                   TEXT    NOT NULL DEFAULT '',
    armor_ac_bonus                  INTEGER NOT NULL DEFAULT 0,
    encumbrance_units               INTEGER NOT NULL DEFAULT 100,
    gp_cost_base                    INTEGER NOT NULL DEFAULT 0
        CHECK(gp_cost_base >= 0),
    gp_cost_precious_materials      INTEGER NOT NULL DEFAULT 0
        CHECK(gp_cost_precious_materials >= 0),
    special_components_xp           INTEGER NOT NULL DEFAULT 0
        CHECK(special_components_xp >= 0),
    days_to_create                  INTEGER NOT NULL DEFAULT 0
        CHECK(days_to_create >= 0),
    used_formula                    INTEGER NOT NULL DEFAULT 0
        CHECK(used_formula IN (0, 1)),
    workshop_id                     TEXT REFERENCES workshops(id),
    notes                           TEXT    NOT NULL DEFAULT '',
    created_calendar_day            INTEGER NOT NULL DEFAULT 0,
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_crafted_magic_items_creator
    ON crafted_magic_items (creator_character_id);
CREATE INDEX IF NOT EXISTS idx_crafted_magic_items_category
    ON crafted_magic_items (item_category);
CREATE INDEX IF NOT EXISTS idx_crafted_magic_items_effect_kind
    ON crafted_magic_items (effect_kind);


-- Migration 095: Construct creation (Domain Phase 10B.1e).
--
-- Per acore-campaign-general-and-magic-research.xml §constructs L373-415.
-- Two tables: construct_designs (formula/template) + construct_instances
-- (actual bodies). v1 10B.1e combines design+create in one research_magic
-- project; the two-step RAW split is a future polish.

CREATE TABLE IF NOT EXISTS construct_designs (
    id                          TEXT    PRIMARY KEY,
    campaign_id                 TEXT    NOT NULL REFERENCES campaigns(id),
    creator_character_id        TEXT    NOT NULL REFERENCES characters(id),
    name                        TEXT    NOT NULL,
    hit_dice                    INTEGER NOT NULL DEFAULT 1
        CHECK(hit_dice >= 1),
    armor_class                 INTEGER NOT NULL DEFAULT 0
        CHECK(armor_class >= 0),
    attacks_per_round           INTEGER NOT NULL DEFAULT 1
        CHECK(attacks_per_round BETWEEN 1 AND 4),
    max_damage_per_round        INTEGER NOT NULL DEFAULT 1
        CHECK(max_damage_per_round >= 1),
    damage_expression           TEXT    NOT NULL DEFAULT '1d6',
    special_abilities_json      TEXT    NOT NULL DEFAULT '[]',
    gp_cost_total               INTEGER NOT NULL DEFAULT 0
        CHECK(gp_cost_total >= 0),
    days_to_design              INTEGER NOT NULL DEFAULT 0
        CHECK(days_to_design >= 0),
    library_id                  TEXT REFERENCES libraries(id),
    designed_calendar_day       INTEGER NOT NULL DEFAULT 0,
    created_at                  TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_construct_designs_creator
    ON construct_designs (creator_character_id);
CREATE INDEX IF NOT EXISTS idx_construct_designs_hd
    ON construct_designs (hit_dice);

CREATE TABLE IF NOT EXISTS construct_instances (
    id                          TEXT    PRIMARY KEY,
    campaign_id                 TEXT    NOT NULL REFERENCES campaigns(id),
    design_id                   TEXT    NOT NULL REFERENCES construct_designs(id),
    creator_character_id        TEXT    NOT NULL REFERENCES characters(id),
    owner_character_id          TEXT REFERENCES characters(id),
    name                        TEXT    NOT NULL,
    hp_max                      INTEGER NOT NULL DEFAULT 1
        CHECK(hp_max >= 1),
    hp_current                  INTEGER NOT NULL DEFAULT 1,
    location_kind               TEXT    NOT NULL DEFAULT 'stronghold'
        CHECK(location_kind IN ('stronghold', 'with_owner', 'wilderness_hex', 'dungeon_room', 'other')),
    location_ref                TEXT    NOT NULL DEFAULT '',
    workshop_id                 TEXT REFERENCES workshops(id),
    gp_cost_total               INTEGER NOT NULL DEFAULT 0,
    days_to_create              INTEGER NOT NULL DEFAULT 0,
    status                      TEXT    NOT NULL DEFAULT 'active'
        CHECK(status IN ('active', 'damaged', 'inactive', 'destroyed')),
    created_calendar_day        INTEGER NOT NULL DEFAULT 0,
    destroyed_calendar_day      INTEGER,
    notes                       TEXT    NOT NULL DEFAULT '',
    created_at                  TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_construct_instances_creator
    ON construct_instances (creator_character_id);
CREATE INDEX IF NOT EXISTS idx_construct_instances_design
    ON construct_instances (design_id);
CREATE INDEX IF NOT EXISTS idx_construct_instances_status
    ON construct_instances (status);


-- Migration 096: Cross-breeding (Domain Phase 10B.1f).
--
-- Per acore-campaign-general-and-magic-research.xml §crossbreeds L417-484.
-- v1 scope per Q19: cross-breeding only; monster-from-scratch deferred.
-- Three tables: laboratories (research-site), crossbreed_species
-- (formula/template), crossbreed_instances (actual creatures).

CREATE TABLE IF NOT EXISTS laboratories (
    id                                TEXT    PRIMARY KEY,
    campaign_id                       TEXT    NOT NULL REFERENCES campaigns(id),
    owner_character_id                TEXT    NOT NULL REFERENCES characters(id),
    stronghold_id                     TEXT REFERENCES strongholds(id),
    structure_kind                    TEXT    NOT NULL DEFAULT 'crossbreeding_laboratory'
        CHECK(structure_kind IN (
            'crossbreeding_laboratory', 'sanctum_laboratory', 'tower_laboratory', 'other'
        )),
    cp_invested                       INTEGER NOT NULL DEFAULT 0
        CHECK(cp_invested >= 0),
    max_crossbreed_cost_cp            INTEGER NOT NULL DEFAULT 0
        CHECK(max_crossbreed_cost_cp >= 0),
    magic_research_throw_bonus        INTEGER NOT NULL DEFAULT 0
        CHECK(magic_research_throw_bonus BETWEEN 0 AND 4),
    status                            TEXT    NOT NULL DEFAULT 'operational'
        CHECK(status IN ('building', 'operational', 'damaged', 'destroyed')),
    created_calendar_day              INTEGER NOT NULL DEFAULT 0,
    created_at                        TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                        TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_laboratories_owner      ON laboratories (owner_character_id);
CREATE INDEX IF NOT EXISTS idx_laboratories_stronghold ON laboratories (stronghold_id);
CREATE INDEX IF NOT EXISTS idx_laboratories_status     ON laboratories (status);

CREATE TABLE IF NOT EXISTS crossbreed_species (
    id                          TEXT    PRIMARY KEY,
    campaign_id                 TEXT    NOT NULL REFERENCES campaigns(id),
    creator_character_id        TEXT    NOT NULL REFERENCES characters(id),
    name                        TEXT    NOT NULL,
    progenitor_a_name           TEXT    NOT NULL DEFAULT '',
    progenitor_b_name           TEXT    NOT NULL DEFAULT '',
    progenitor_a_hd             INTEGER NOT NULL DEFAULT 1
        CHECK(progenitor_a_hd >= 1),
    progenitor_b_hd             INTEGER NOT NULL DEFAULT 1
        CHECK(progenitor_b_hd >= 1),
    progenitor_a_alignment      TEXT    NOT NULL DEFAULT 'neutral'
        CHECK(progenitor_a_alignment IN ('lawful', 'neutral', 'chaotic')),
    progenitor_b_alignment      TEXT    NOT NULL DEFAULT 'neutral'
        CHECK(progenitor_b_alignment IN ('lawful', 'neutral', 'chaotic')),
    hit_dice                    INTEGER NOT NULL DEFAULT 1
        CHECK(hit_dice >= 1),
    armor_class                 INTEGER NOT NULL DEFAULT 0
        CHECK(armor_class >= 0),
    attacks_per_round           INTEGER NOT NULL DEFAULT 1
        CHECK(attacks_per_round BETWEEN 1 AND 6),
    max_damage_per_round        INTEGER NOT NULL DEFAULT 1
        CHECK(max_damage_per_round >= 1),
    damage_expression           TEXT    NOT NULL DEFAULT '1d6',
    morale                      INTEGER NOT NULL DEFAULT 0,
    movement_kind               TEXT    NOT NULL DEFAULT 'progenitor_a'
        CHECK(movement_kind IN ('progenitor_a', 'progenitor_b', 'both')),
    special_abilities_json      TEXT    NOT NULL DEFAULT '[]',
    alignment                   TEXT    NOT NULL DEFAULT 'neutral'
        CHECK(alignment IN ('lawful', 'neutral', 'chaotic')),
    types_json                  TEXT    NOT NULL DEFAULT '["fantastic"]',
    gp_cost_total               INTEGER NOT NULL DEFAULT 0
        CHECK(gp_cost_total >= 0),
    days_to_create              INTEGER NOT NULL DEFAULT 0
        CHECK(days_to_create >= 0),
    laboratory_id               TEXT REFERENCES laboratories(id),
    designed_calendar_day       INTEGER NOT NULL DEFAULT 0,
    created_at                  TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_crossbreed_species_creator
    ON crossbreed_species (creator_character_id);
CREATE INDEX IF NOT EXISTS idx_crossbreed_species_hd
    ON crossbreed_species (hit_dice);

CREATE TABLE IF NOT EXISTS crossbreed_instances (
    id                          TEXT    PRIMARY KEY,
    campaign_id                 TEXT    NOT NULL REFERENCES campaigns(id),
    species_id                  TEXT    NOT NULL REFERENCES crossbreed_species(id),
    creator_character_id        TEXT    NOT NULL REFERENCES characters(id),
    owner_character_id          TEXT REFERENCES characters(id),
    name                        TEXT    NOT NULL,
    hp_max                      INTEGER NOT NULL DEFAULT 1
        CHECK(hp_max >= 1),
    hp_current                  INTEGER NOT NULL DEFAULT 1,
    location_kind               TEXT    NOT NULL DEFAULT 'stronghold'
        CHECK(location_kind IN ('stronghold', 'with_owner', 'wilderness_hex', 'dungeon_room', 'laboratory', 'other')),
    location_ref                TEXT    NOT NULL DEFAULT '',
    laboratory_id               TEXT REFERENCES laboratories(id),
    -- Migration 133: enum corrected to the RAW Monster Reaction tiers
    -- (acore_adventures_and_encounters.xml:936-958); migration 096 erroneously
    -- had ('...','friendly','helpful') -- 'helpful' is the Friendly tier's
    -- descriptor, not a tier, and 'indifferent' is the real 9-11 tier.
    initial_reaction            TEXT
        CHECK(initial_reaction IS NULL OR initial_reaction IN ('hostile', 'unfriendly', 'neutral', 'indifferent', 'friendly')),
    status                      TEXT    NOT NULL DEFAULT 'alive'
        CHECK(status IN ('alive', 'escaped', 'killed', 'controlled')),
    gp_cost_total               INTEGER NOT NULL DEFAULT 0,
    days_to_create              INTEGER NOT NULL DEFAULT 0,
    created_calendar_day        INTEGER NOT NULL DEFAULT 0,
    killed_calendar_day         INTEGER,
    notes                       TEXT    NOT NULL DEFAULT '',
    created_at                  TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_crossbreed_instances_creator
    ON crossbreed_instances (creator_character_id);
CREATE INDEX IF NOT EXISTS idx_crossbreed_instances_species
    ON crossbreed_instances (species_id);
CREATE INDEX IF NOT EXISTS idx_crossbreed_instances_status
    ON crossbreed_instances (status);

-- Migration 105 (Phase 10B.2 Wave 1): shipping_contract_offers.
-- Per gdd-phase-10b-2-trade-block.md §7.2. Per-visit transient offers;
-- INSERTed on market entry (ShippingContractOfferRoller.roll_for_visit,
-- Wave 4); DELETEd on departure (VisitStateManager.on_party_departed_settlement)
-- or on accept (accept_shipping_contract handler).
CREATE TABLE IF NOT EXISTS shipping_contract_offers (
    id                              TEXT    PRIMARY KEY,
    campaign_id                     TEXT    NOT NULL REFERENCES campaigns(id),
    party_id                        TEXT    NOT NULL REFERENCES parties(id),
    origin_settlement_id            TEXT    NOT NULL REFERENCES settlement_entrances(id),
    destination_settlement_id       TEXT    NOT NULL REFERENCES settlement_entrances(id),
    merchandise_type                TEXT    NOT NULL,
    loads_count                     INTEGER NOT NULL DEFAULT 0,
    load_weight_stone               INTEGER NOT NULL DEFAULT 0,
    route_mode                      TEXT    NOT NULL DEFAULT 'road'
        CHECK(route_mode IN ('road', 'water')),
    distance_miles                  INTEGER NOT NULL DEFAULT 0,
    fee_cp                          INTEGER NOT NULL DEFAULT 0,
    deadline_calendar_day           INTEGER NOT NULL DEFAULT 0,
    rolled_at_calendar_day          INTEGER NOT NULL DEFAULT 0,
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_shipping_contract_offers_party
    ON shipping_contract_offers(party_id, origin_settlement_id);

-- Migration 106 (Phase 10B.2 Wave 1): monopoly_holdings.
-- Per gdd-phase-10b-2-trade-block.md §8.1. (character_id, settlement_id,
-- merchandise_type) triples that confer the RAW monopolist benefits.
-- Empty by default in v1; consumed by MonopolyRegistry for has_monopoly /
-- favor_for_buy / favor_for_sell. Population is later work (Phase 10B.3
-- decree extension or future domain block enhancement).
CREATE TABLE IF NOT EXISTS monopoly_holdings (
    id                              TEXT    PRIMARY KEY,
    campaign_id                     TEXT    NOT NULL REFERENCES campaigns(id),
    character_id                    TEXT    NOT NULL REFERENCES characters(id),
    settlement_id                   TEXT    NOT NULL REFERENCES settlement_entrances(id),
    merchandise_type                TEXT    NOT NULL,
    granted_at_calendar_day         INTEGER NOT NULL DEFAULT 0,
    granted_by_character_id         TEXT    REFERENCES characters(id),
    granted_by_authority            TEXT    NOT NULL DEFAULT 'domain_ruler'
        CHECK(granted_by_authority IN ('domain_ruler', 'judge', 'inherited', 'purchased')),
    expires_at_calendar_day         INTEGER,
    notes                           TEXT    NOT NULL DEFAULT '',
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now')),
    UNIQUE(character_id, settlement_id, merchandise_type)
);
CREATE INDEX IF NOT EXISTS idx_monopoly_holdings_character
    ON monopoly_holdings(character_id);
CREATE INDEX IF NOT EXISTS idx_monopoly_holdings_settlement_merch
    ON monopoly_holdings(settlement_id, merchandise_type);

-- Migration 107 (Phase 10B.2 Wave 1): party_visit_state.
-- Per gdd-phase-10b-2-trade-block.md §9.3. Per-visit state with composite
-- PK (party_id, settlement_id). INSERTed on settlement entry; DELETEd on
-- departure. Tracks entry-toll first-fire + active character + entry day
-- for stabling math.
CREATE TABLE IF NOT EXISTS party_visit_state (
    party_id                        TEXT    NOT NULL REFERENCES parties(id),
    settlement_id                   TEXT    NOT NULL REFERENCES settlement_entrances(id),
    entry_calendar_day              INTEGER NOT NULL DEFAULT 0,
    entry_toll_paid_flag            INTEGER NOT NULL DEFAULT 0
        CHECK(entry_toll_paid_flag IN (0, 1)),
    entry_toll_paid_cp              INTEGER NOT NULL DEFAULT 0,
    active_character_at_entry       TEXT    REFERENCES characters(id),
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now')),
    PRIMARY KEY (party_id, settlement_id)
);


-- Migration 118 (Phase 10B.3): Syndicate (Hijinks) schema.
-- Five tables — syndicates, syndicate_members, hijink_assignments,
-- caught_perpetrators, lay_low_state. All money columns are cp.
-- See db/migrations/118_syndicate_schema.sql for the full RAW citation set.

CREATE TABLE IF NOT EXISTS syndicates (
    id                              TEXT    PRIMARY KEY,
    campaign_id                     TEXT    NOT NULL REFERENCES campaigns(id),
    boss_character_id               TEXT    NOT NULL REFERENCES characters(id),
    -- VESTIGIAL since Migration 143 (Thief→Syndicate refactor): the hideout is
    -- now its own `hideouts` row, NOT a strongholds row. Left in place
    -- (non-destructive) but never written by FoundSyndicateFlow; use hideout_id.
    hideout_stronghold_id           TEXT    REFERENCES strongholds(id),
    base_settlement_entrance_id     TEXT    REFERENCES settlement_entrances(id),
    syndicate_size_max              INTEGER NOT NULL DEFAULT 0,
    current_size                    INTEGER NOT NULL DEFAULT 0,
    status                          TEXT    NOT NULL DEFAULT 'active'
        CHECK(status IN ('active', 'disbanded', 'seized')),
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                      TEXT    NOT NULL DEFAULT (datetime('now')),
    -- Migration 143: source-of-truth FK to the syndicate's hideout (its own
    -- structure, distinct from strongholds; see the `hideouts` table below).
    hideout_id                      TEXT    REFERENCES hideouts(id)
);
CREATE INDEX IF NOT EXISTS idx_syndicates_campaign
    ON syndicates(campaign_id);
CREATE INDEX IF NOT EXISTS idx_syndicates_boss
    ON syndicates(boss_character_id);
CREATE INDEX IF NOT EXISTS idx_syndicates_hideout
    ON syndicates(hideout_stronghold_id);

CREATE TABLE IF NOT EXISTS syndicate_members (
    id                              TEXT    PRIMARY KEY,
    syndicate_id                    TEXT    NOT NULL REFERENCES syndicates(id),
    character_id_if_named           TEXT    REFERENCES characters(id),
    level                           INTEGER NOT NULL DEFAULT 1,
    follower_kind                   TEXT    NOT NULL DEFAULT 'thief'
        CHECK(follower_kind IN (
            'thief', 'assassin', 'elven_nightblade', 'ruffian', 'other'
        )),
    status                          TEXT    NOT NULL DEFAULT 'active'
        CHECK(status IN (
            'active', 'laying_low', 'jailed', 'dead', 'departed'
        )),
    hijink_eligible                 INTEGER NOT NULL DEFAULT 1
        CHECK(hijink_eligible IN (0, 1)),
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_syndicate_members_syndicate
    ON syndicate_members(syndicate_id);
CREATE INDEX IF NOT EXISTS idx_syndicate_members_status
    ON syndicate_members(syndicate_id, status);
CREATE INDEX IF NOT EXISTS idx_syndicate_members_character
    ON syndicate_members(character_id_if_named);

CREATE TABLE IF NOT EXISTS hijink_assignments (
    id                              TEXT    PRIMARY KEY,
    syndicate_id                    TEXT    NOT NULL REFERENCES syndicates(id),
    syndicate_member_id             TEXT    REFERENCES syndicate_members(id),
    boss_character_id               TEXT    NOT NULL REFERENCES characters(id),
    hideout_id                      TEXT    REFERENCES strongholds(id),
    hijink_kind                     TEXT    NOT NULL
        CHECK(hijink_kind IN (
            'assassinating', 'carousing', 'smuggling',
            'spying', 'stealing', 'treasure_hunting'
        )),
    planning_state                  TEXT    NOT NULL DEFAULT 'unplanned'
        CHECK(planning_state IN (
            'unplanned', 'planning', 'planned', 'in_progress', 'complete'
        )),
    planning_days_required          INTEGER NOT NULL DEFAULT 0,
    planning_days_completed         INTEGER NOT NULL DEFAULT 0,
    status                          TEXT    NOT NULL DEFAULT 'queued'
        CHECK(status IN (
            'queued', 'planning', 'active', 'resolved', 'aborted'
        )),
    started_day                     INTEGER NOT NULL DEFAULT 0,
    completed_day                   INTEGER,
    target_id                       TEXT    NOT NULL DEFAULT '',
    throw_result                    INTEGER,
    cp_yield                        INTEGER NOT NULL DEFAULT 0,
    caught                          INTEGER NOT NULL DEFAULT 0
        CHECK(caught IN (0, 1)),
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_hijink_assignments_syndicate
    ON hijink_assignments(syndicate_id);
CREATE INDEX IF NOT EXISTS idx_hijink_assignments_member
    ON hijink_assignments(syndicate_member_id);
CREATE INDEX IF NOT EXISTS idx_hijink_assignments_status
    ON hijink_assignments(syndicate_id, status);

CREATE TABLE IF NOT EXISTS caught_perpetrators (
    id                              TEXT    PRIMARY KEY,
    character_id                    TEXT    NOT NULL REFERENCES characters(id),
    hijink_assignment_id            TEXT    REFERENCES hijink_assignments(id),
    crime_type                      TEXT    NOT NULL,
    time_languishing_days           INTEGER NOT NULL DEFAULT 0,
    attorney_rank                   INTEGER NOT NULL DEFAULT 0,
    bribe_amount_cp                 INTEGER NOT NULL DEFAULT 0,
    interpleader_id                 TEXT    REFERENCES characters(id),
    verdict                         TEXT,
    fine_cp                         INTEGER NOT NULL DEFAULT 0,
    punishment_kind                 TEXT,
    punishment_resolved             INTEGER NOT NULL DEFAULT 0
        CHECK(punishment_resolved IN (0, 1)),
    prior_crimes_modifier           INTEGER NOT NULL DEFAULT 0,
    arrested_day                    INTEGER NOT NULL DEFAULT 0,
    resolved_day                    INTEGER,
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_caught_perpetrators_character
    ON caught_perpetrators(character_id);
CREATE INDEX IF NOT EXISTS idx_caught_perpetrators_hijink
    ON caught_perpetrators(hijink_assignment_id);
CREATE INDEX IF NOT EXISTS idx_caught_perpetrators_unresolved
    ON caught_perpetrators(punishment_resolved, resolved_day);

CREATE TABLE IF NOT EXISTS lay_low_state (
    character_id                    TEXT    PRIMARY KEY REFERENCES characters(id),
    base_id                         TEXT    NOT NULL,
    started_day                     INTEGER NOT NULL,
    ends_day                        INTEGER NOT NULL,
    created_at                      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_lay_low_state_base
    ON lay_low_state(base_id, ends_day);

-- Migration 143: hideouts (Thief→Syndicate refactor). A hideout is the
-- syndicate's secret base — its OWN structure, NOT a strongholds row. It never
-- secures a domain, attracts no families, and sits in the same-or-adjacent
-- 6-mile hex as its host settlement (RAW ax_thief_skill_update.xml:48-69).
-- cp_value is money × 100, funded at founding to >= the market-class minimum.
-- market_class snapshots the host settlement (INTEGER 1..6; 6 = Class VI).
CREATE TABLE IF NOT EXISTS hideouts (
    id                           TEXT    PRIMARY KEY,
    campaign_id                  TEXT    NOT NULL REFERENCES campaigns(id),
    syndicate_id                 TEXT    REFERENCES syndicates(id),
    owner_character_id           TEXT    NOT NULL REFERENCES characters(id),
    host_settlement_entrance_id  TEXT    NOT NULL REFERENCES settlement_entrances(id),
    market_class                 INTEGER NOT NULL DEFAULT 6,
    cp_value                     INTEGER NOT NULL DEFAULT 0,
    location_map_id              TEXT    REFERENCES hex_maps(id),
    location_hex_q               INTEGER,
    location_hex_r               INTEGER,
    status                       TEXT    NOT NULL DEFAULT 'active'
        CHECK(status IN ('active', 'abandoned', 'seized')),
    created_at                   TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                   TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_hideouts_campaign  ON hideouts(campaign_id);
CREATE INDEX IF NOT EXISTS idx_hideouts_owner     ON hideouts(owner_character_id);
CREATE INDEX IF NOT EXISTS idx_hideouts_syndicate ON hideouts(syndicate_id);

-- Migration 144: guildhouses (Venturer→Guildhouse refactor). A guildhouse is the
-- Venturer's mercantile base — its OWN structure (RAW: "follows hideout rules"),
-- NOT a strongholds row. Secures no domain. cp_value funded to >= the market-class
-- minimum (HideoutCostTable). monopoly_seized=1 once an L12 venturer seizes
-- settlement monopoly here (1gp/urban-family/month). Apprentices are NOT here —
-- they are `followers` rows with source_kind='venturer_apprentice'.
CREATE TABLE IF NOT EXISTS guildhouses (
    id                           TEXT    PRIMARY KEY,
    campaign_id                  TEXT    NOT NULL REFERENCES campaigns(id),
    owner_character_id           TEXT    NOT NULL REFERENCES characters(id),
    host_settlement_entrance_id  TEXT    NOT NULL REFERENCES settlement_entrances(id),
    market_class                 INTEGER NOT NULL DEFAULT 6,
    cp_value                     INTEGER NOT NULL DEFAULT 0,
    location_map_id              TEXT    REFERENCES hex_maps(id),
    location_hex_q               INTEGER,
    location_hex_r               INTEGER,
    monopoly_seized              INTEGER NOT NULL DEFAULT 0
        CHECK(monopoly_seized IN (0, 1)),
    monopoly_seized_day          INTEGER,
    status                       TEXT    NOT NULL DEFAULT 'active'
        CHECK(status IN ('active', 'abandoned', 'seized')),
    created_at                   TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at                   TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_guildhouses_campaign   ON guildhouses(campaign_id);
CREATE INDEX IF NOT EXISTS idx_guildhouses_owner      ON guildhouses(owner_character_id);
CREATE INDEX IF NOT EXISTS idx_guildhouses_settlement ON guildhouses(host_settlement_entrance_id);

-- Migration 121: domain_departure_log — Phase 11A append-only chronicle
-- of significant losses and lifecycle changes per gdd-domain-tab.md §14.
-- domain_id intentionally has no FK so the log survives a hard domain
-- row deletion (the "conquered by foreign realm" terminal case).
-- This table is APPEND-ONLY: no UPDATE, no DELETE — see coding_conventions.md.
CREATE TABLE IF NOT EXISTS domain_departure_log (
    id                       TEXT    PRIMARY KEY,
    campaign_id              TEXT    NOT NULL REFERENCES campaigns(id),
    domain_id                TEXT    NOT NULL,
    calendar_day             INTEGER NOT NULL,
    event_type               TEXT    NOT NULL
        CHECK(event_type IN (
            'established',
            'classification_advanced',
            'classification_regressed',
            'territory_lost',
            'stronghold_lost',
            'defeat',
            'pillaged',
            'ruler_changed',
            'ruler_died',
            'succession_started',
            'succession_resolved',
            'succession_lapsed',
            'vassal_lost',
            'vassal_promoted',
            'religion_converted',
            'monster_settled',
            'calamity',
            'morale_tier_dropped',
            'conquered',
            'abandoned',
            'restored',
            -- Migration 129 (Phase 11D.5) tribal-warrior event types
            -- per gdd-tribal-warriors.md §4.1.
            'tribal_warriors_levied',
            'tribal_warriors_stood_down',
            'tribal_warriors_released_for_population_loss',
            'tribal_warriors_morale_check_triggered',
            'tribal_warriors_loyalty_failed',
            'tribal_warriors_called_to_arms'
        )),
    summary                  TEXT    NOT NULL DEFAULT '',
    full_details_json        TEXT    NOT NULL DEFAULT '{}',
    related_ledger_entry_ids TEXT    NOT NULL DEFAULT '[]',
    related_encounter_ids    TEXT    NOT NULL DEFAULT '[]',
    created_at               TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_domain_departure_log_domain_calendar
    ON domain_departure_log(domain_id, calendar_day DESC);
CREATE INDEX IF NOT EXISTS idx_domain_departure_log_campaign_calendar
    ON domain_departure_log(campaign_id, calendar_day DESC);

-- Migration 124: Phase 11D-prereq.0a realm substrate. Realms are explicit
-- rows now; tracked realms map 1:1 with apex domains (the realm head is
-- the apex's owner), foreign realms exist without a corresponding domain
-- (flavor backdrop for off-map conquerors instantiated by 11D-prereq.0b).
CREATE TABLE IF NOT EXISTS realms (
    id                       TEXT    PRIMARY KEY,
    campaign_id              TEXT    NOT NULL REFERENCES campaigns(id),
    name                     TEXT    NOT NULL,
    head_character_id        TEXT    REFERENCES characters(id),
    alignment                TEXT
        CHECK(alignment IS NULL OR alignment IN ('lawful', 'neutral', 'chaotic')),
    dominant_religion        TEXT    NOT NULL DEFAULT '',
    culture                  TEXT    NOT NULL DEFAULT '',
    realm_kind               TEXT    NOT NULL DEFAULT 'tracked'
        CHECK(realm_kind IN ('tracked', 'foreign')),
    created_at               TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at               TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_realms_campaign
    ON realms(campaign_id);
CREATE INDEX IF NOT EXISTS idx_realms_head_character
    ON realms(head_character_id);

-- Pair-symmetric diplomatic-disposition cache. Repository enforces canonical
-- ordering (realm_a_id < realm_b_id lexicographically) so each pair has at
-- most one row. Disposition bands map to 2d6 reaction-table outcomes;
-- transitions happen via project-designed events, not RAW rolls.
CREATE TABLE IF NOT EXISTS realm_relations (
    id                       TEXT    PRIMARY KEY,
    campaign_id              TEXT    NOT NULL REFERENCES campaigns(id),
    realm_a_id               TEXT    NOT NULL REFERENCES realms(id),
    realm_b_id               TEXT    NOT NULL REFERENCES realms(id),
    disposition              TEXT    NOT NULL DEFAULT 'neutral'
        CHECK(disposition IN ('hostile', 'unfriendly', 'neutral', 'cordial', 'friendly', 'allied')),
    last_changed_day         INTEGER NOT NULL DEFAULT 0,
    created_at               TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at               TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_realm_relations_pair
    ON realm_relations(realm_a_id, realm_b_id);

-- ---------------------------------------------------------------------------
-- Migration 126: Urban Growth Stocking — settlement_pois table per
-- `generation/gdd-urban-growth-stocking.md` §11.1. Substrate for the POI
-- emergence pipeline (Stages C-H land in later sessions).
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS settlement_pois (
    id TEXT PRIMARY KEY,
    settlement_id TEXT NOT NULL REFERENCES settlement_entrances(id) ON DELETE CASCADE,
    type TEXT NOT NULL
        CHECK (type IN (
            'religious_site', 'mercenary_guild_hall', 'mages_guild_hall',
            'named_tavern', 'workshop', 'port'
        )),
    tier TEXT NOT NULL DEFAULT ''
        CHECK (tier IN ('', 'shrine', 'temple')),
    status TEXT NOT NULL DEFAULT 'active'
        CHECK (status IN (
            'emerging', 'active', 'understaffed', 'dormant', 'abandoned'
        )),
    builder_kind TEXT NOT NULL DEFAULT 'emergent'
        CHECK (builder_kind IN ('emergent', 'character')),
    builder_character_id TEXT REFERENCES characters(id) ON DELETE SET NULL,
    emerged_via TEXT NOT NULL DEFAULT ''
        CHECK (emerged_via IN (
            '', 'class_advancement', 'player_commission', 'stronghold_register',
            'baseline_emergence'
        )),
    established_at_calendar_day INTEGER NOT NULL DEFAULT 0,
    gp_value INTEGER NOT NULL DEFAULT 0,
    l3_plus_npc_count INTEGER NOT NULL DEFAULT 0,
    l1_l2_adherent_count INTEGER NOT NULL DEFAULT 0
        CHECK (l1_l2_adherent_count >= 0),
    attached_religion TEXT NOT NULL DEFAULT '',
    attached_specialist_kind TEXT NOT NULL DEFAULT '',
    stocked_character_id TEXT REFERENCES characters(id) ON DELETE SET NULL,
    baseline_head_npc_character_id TEXT REFERENCES characters(id) ON DELETE SET NULL,
    preferred_district_class TEXT NOT NULL DEFAULT '',
    owner_faction_id TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now')),
    CHECK (
        (builder_kind = 'emergent' AND builder_character_id IS NULL)
        OR
        (builder_kind = 'character' AND builder_character_id IS NOT NULL)
    ),
    CHECK (
        (type = 'religious_site' AND tier IN ('shrine', 'temple'))
        OR (type <> 'religious_site' AND tier = '')
    )
);
CREATE INDEX IF NOT EXISTS idx_settlement_pois_settlement
    ON settlement_pois(settlement_id);
CREATE INDEX IF NOT EXISTS idx_settlement_pois_type
    ON settlement_pois(type);
CREATE INDEX IF NOT EXISTS idx_settlement_pois_religion
    ON settlement_pois(attached_religion)
    WHERE attached_religion <> '';
CREATE INDEX IF NOT EXISTS idx_settlement_pois_specialist_kind
    ON settlement_pois(attached_specialist_kind)
    WHERE attached_specialist_kind <> '';
CREATE INDEX IF NOT EXISTS idx_settlement_pois_tier
    ON settlement_pois(tier)
    WHERE tier <> '';

-- Migration 126: daily spellcasting service availability per
-- `gdd-urban-growth-stocking.md` §11.4a. Lazy-init by §8.5.2's query — no
-- background process pre-populates this table. 7-day retention sweep ships
-- with Stage H.
CREATE TABLE IF NOT EXISTS settlement_poi_spell_offers (
    id TEXT PRIMARY KEY,
    poi_id TEXT NOT NULL REFERENCES settlement_pois(id) ON DELETE CASCADE,
    calendar_day INTEGER NOT NULL,
    tradition TEXT NOT NULL
        CHECK (tradition IN ('divine', 'arcane')),
    spell_level INTEGER NOT NULL
        CHECK (spell_level BETWEEN 1 AND 6),
    count_initial INTEGER NOT NULL
        CHECK (count_initial >= 0),
    count_remaining INTEGER NOT NULL
        CHECK (count_remaining >= 0 AND count_remaining <= count_initial),
    unit_cost_gp INTEGER NOT NULL
        CHECK (unit_cost_gp >= 0),
    UNIQUE (poi_id, calendar_day, tradition, spell_level)
);
CREATE INDEX IF NOT EXISTS idx_settlement_poi_spell_offers_lookup
    ON settlement_poi_spell_offers(poi_id, calendar_day);

-- Migration 126: tier-cache maintenance triggers per §11.4. Religious_sites
-- track 'shrine'/'temple' tier as a denormalized cache; the triggers below
-- keep the cache in sync with the consecrated_altars rows attached via
-- (location_kind='settlement_poi', location_ref=<settlement_pois.id>).
CREATE TRIGGER IF NOT EXISTS trg_consecrated_altars_promote_religious_site
AFTER UPDATE OF status ON consecrated_altars
WHEN NEW.status = 'completed' AND NEW.location_kind = 'settlement_poi'
BEGIN
    UPDATE settlement_pois
    SET tier = 'temple',
        updated_at = datetime('now')
    WHERE id = NEW.location_ref
      AND type = 'religious_site';
END;

CREATE TRIGGER IF NOT EXISTS trg_consecrated_altars_promote_on_insert
AFTER INSERT ON consecrated_altars
WHEN NEW.status = 'completed' AND NEW.location_kind = 'settlement_poi'
BEGIN
    UPDATE settlement_pois
    SET tier = 'temple',
        updated_at = datetime('now')
    WHERE id = NEW.location_ref
      AND type = 'religious_site';
END;

CREATE TRIGGER IF NOT EXISTS trg_consecrated_altars_demote_religious_site
AFTER UPDATE OF status ON consecrated_altars
WHEN NEW.status = 'broken_unblessed' AND NEW.location_kind = 'settlement_poi'
BEGIN
    UPDATE settlement_pois
    SET tier = CASE
            WHEN EXISTS (
                SELECT 1 FROM consecrated_altars ca
                WHERE ca.location_kind = 'settlement_poi'
                  AND ca.location_ref = settlement_pois.id
                  AND ca.status = 'completed'
                  AND ca.id <> NEW.id
            ) THEN 'temple'
            ELSE 'shrine'
        END,
        updated_at = datetime('now')
    WHERE id = NEW.location_ref
      AND type = 'religious_site';
END;

-- Migration 126: characters.home_poi_id index (Q-UGS-28).
CREATE INDEX IF NOT EXISTS idx_characters_home_poi
    ON characters(home_poi_id)
    WHERE home_poi_id IS NOT NULL;

-- Migration 126: characters.npc_role index (Q-UGS-29).
CREATE INDEX IF NOT EXISTS idx_characters_npc_role
    ON characters(npc_role)
    WHERE npc_role <> 'player';

-- ===========================================================================
-- Migration 132: Random Dungeon Generator V1 persistence (DG-V1.C).
-- Six self-contained tables (no FK to `dungeons`); dungeon_id is the external
-- linkage. See db/migrations/132_dungeon_generator_v1.sql for the full rationale.
-- ===========================================================================

CREATE TABLE IF NOT EXISTS dungeon_floors (
    id                      TEXT    PRIMARY KEY,
    dungeon_id              TEXT    NOT NULL,
    floor_index             INTEGER NOT NULL,
    floor_tier              INTEGER NOT NULL DEFAULT 1,
    is_entrance_floor       INTEGER NOT NULL DEFAULT 0 CHECK(is_entrance_floor IN (0, 1)),
    dungeon_type            TEXT    NOT NULL DEFAULT 'wizards_dungeon',
    dungeon_size            TEXT    NOT NULL DEFAULT 'medium',
    structure_type          TEXT    NOT NULL DEFAULT 'subterranean',
    grid_width              INTEGER NOT NULL,
    grid_height             INTEGER NOT NULL,
    entrance_x              INTEGER NOT NULL DEFAULT -1,
    entrance_y              INTEGER NOT NULL DEFAULT -1,
    generation_seed         INTEGER NOT NULL DEFAULT 0,
    total_monster_xp        INTEGER NOT NULL DEFAULT 0,
    total_treasure_gp_value INTEGER NOT NULL DEFAULT 0,
    xp_to_gp_ratio          REAL    NOT NULL DEFAULT 0.0,
    encounter_table_row     INTEGER NOT NULL DEFAULT 0,
    cells_json              TEXT    NOT NULL DEFAULT '[]',
    stairs_json             TEXT    NOT NULL DEFAULT '[]',
    created_at              TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_dungeon_floors_dungeon ON dungeon_floors(dungeon_id);

CREATE TABLE IF NOT EXISTS dungeon_rooms (
    id                TEXT    PRIMARY KEY,
    dungeon_id        TEXT    NOT NULL,
    floor_id          TEXT    NOT NULL,
    room_id_in_floor  INTEGER NOT NULL,
    bounds_x          INTEGER NOT NULL,
    bounds_y          INTEGER NOT NULL,
    bounds_w          INTEGER NOT NULL,
    bounds_h          INTEGER NOT NULL,
    area_sqft         INTEGER NOT NULL DEFAULT 0,
    center_x          INTEGER NOT NULL DEFAULT 0,
    center_y          INTEGER NOT NULL DEFAULT 0,
    original_purpose  TEXT    NOT NULL DEFAULT '',
    current_purpose   TEXT    NOT NULL DEFAULT '',
    contents_kind     TEXT    NOT NULL DEFAULT 'empty'
        CHECK(contents_kind IN ('empty', 'monster', 'monster_lair', 'trap_placeholder', 'unique_placeholder')),
    monster_group_id  TEXT,
    treasure_hoard_id TEXT
);
CREATE INDEX IF NOT EXISTS idx_dungeon_rooms_dungeon ON dungeon_rooms(dungeon_id);
CREATE INDEX IF NOT EXISTS idx_dungeon_rooms_floor ON dungeon_rooms(floor_id);
CREATE INDEX IF NOT EXISTS idx_dungeon_rooms_floor_roomid ON dungeon_rooms(floor_id, room_id_in_floor);

CREATE TABLE IF NOT EXISTS dungeon_doors (
    id                     TEXT    PRIMARY KEY,
    dungeon_id             TEXT    NOT NULL,
    floor_id               TEXT    NOT NULL,
    position_x             INTEGER NOT NULL,
    position_y             INTEGER NOT NULL,
    type                   TEXT    NOT NULL
        CHECK(type IN ('arch', 'unlocked', 'locked', 'trapped', 'portcullis')),
    is_secret              INTEGER NOT NULL DEFAULT 0 CHECK(is_secret IN (0, 1)),
    door_state             TEXT    NOT NULL DEFAULT '',
    door_material          TEXT    NOT NULL DEFAULT 'wood_standard'
        CHECK(door_material IN ('', 'curtain_cloth', 'curtain_leather', 'wood_standard', 'wood_thick', 'stone', 'metal')),
    is_evil                INTEGER NOT NULL DEFAULT 0 CHECK(is_evil IN (0, 1)),
    connects_room_ids      TEXT    NOT NULL DEFAULT '[]',
    required_key_id        TEXT,
    wired_lever_position_x INTEGER NOT NULL DEFAULT -1,
    wired_lever_position_y INTEGER NOT NULL DEFAULT -1
);
CREATE INDEX IF NOT EXISTS idx_dungeon_doors_dungeon ON dungeon_doors(dungeon_id);
CREATE INDEX IF NOT EXISTS idx_dungeon_doors_floor ON dungeon_doors(floor_id);

CREATE TABLE IF NOT EXISTS monster_groups (
    id                   TEXT    PRIMARY KEY,
    dungeon_id           TEXT    NOT NULL,
    floor_id             TEXT    NOT NULL,
    room_id              TEXT    NOT NULL,
    monster_name         TEXT    NOT NULL DEFAULT '',
    monster_xp_each      INTEGER NOT NULL DEFAULT 0,
    number_appearing     INTEGER NOT NULL DEFAULT 0,
    hd                   TEXT    NOT NULL DEFAULT '',
    associated_creatures TEXT    NOT NULL DEFAULT '[]',
    is_lair              INTEGER NOT NULL DEFAULT 0 CHECK(is_lair IN (0, 1)),
    morale               INTEGER NOT NULL DEFAULT 0,
    alignment            TEXT    NOT NULL DEFAULT '',
    treasure_type_letter TEXT,
    initial_inventory    TEXT    NOT NULL DEFAULT '[]'
);
CREATE INDEX IF NOT EXISTS idx_monster_groups_dungeon ON monster_groups(dungeon_id);
CREATE INDEX IF NOT EXISTS idx_monster_groups_floor ON monster_groups(floor_id);

CREATE TABLE IF NOT EXISTS treasure_hoards (
    id                   TEXT    PRIMARY KEY,
    dungeon_id           TEXT    NOT NULL,
    floor_id             TEXT    NOT NULL,
    room_id              TEXT    NOT NULL,
    source               TEXT    NOT NULL
        CHECK(source IN ('lair', 'unprotected_empty', 'unprotected_trap_placeholder', 'unprotected_unique_placeholder')),
    treasure_type_letter TEXT,
    copper               INTEGER NOT NULL DEFAULT 0,
    silver               INTEGER NOT NULL DEFAULT 0,
    electrum             INTEGER NOT NULL DEFAULT 0,
    gold                 INTEGER NOT NULL DEFAULT 0,
    platinum             INTEGER NOT NULL DEFAULT 0,
    gems                 TEXT    NOT NULL DEFAULT '[]',
    jewelry              TEXT    NOT NULL DEFAULT '[]',
    magic_items          TEXT    NOT NULL DEFAULT '[]',
    total_gp_value       INTEGER NOT NULL DEFAULT 0,
    is_hidden            INTEGER NOT NULL DEFAULT 0 CHECK(is_hidden IN (0, 1)),
    -- Migration 135: runtime loot-consumption flag (0 = unlooted, 1 = claimed)
    is_looted            INTEGER NOT NULL DEFAULT 0,
    -- Migration 137: per-cell placement + container properties
    -- (cell -1/-1/0 = not yet placed; container_type NULL = unassigned)
    cell_x               INTEGER NOT NULL DEFAULT -1,
    cell_y               INTEGER NOT NULL DEFAULT -1,
    cell_z               INTEGER NOT NULL DEFAULT 0,
    container_type       TEXT
        CHECK(container_type IS NULL OR container_type IN
            ('chest', 'barrel', 'sack', 'coin_pile', 'gear_pile')),
    is_locked            INTEGER NOT NULL DEFAULT 0 CHECK(is_locked IN (0, 1)),
    is_trapped           INTEGER NOT NULL DEFAULT 0 CHECK(is_trapped IN (0, 1))
);
CREATE INDEX IF NOT EXISTS idx_treasure_hoards_dungeon ON treasure_hoards(dungeon_id);
CREATE INDEX IF NOT EXISTS idx_treasure_hoards_floor ON treasure_hoards(floor_id);

CREATE TABLE IF NOT EXISTS key_items (
    id                    TEXT    PRIMARY KEY,
    dungeon_id            TEXT    NOT NULL,
    opens_door_floor_id   TEXT    NOT NULL,
    opens_door_position_x INTEGER NOT NULL,
    opens_door_position_y INTEGER NOT NULL,
    placed_in             TEXT    NOT NULL
        CHECK(placed_in IN ('monster_group_inventory', 'treasure_hoard', 'loose_in_room')),
    placed_in_room_id     TEXT,
    placed_on_floor_id    TEXT
);
CREATE INDEX IF NOT EXISTS idx_key_items_dungeon ON key_items(dungeon_id);


-- ===========================================================================
-- Dungeon Faction Generation (Wave 3 Track D; migration 201).
-- gdd-dungeon-factions.md §7 output records. Dungeon-CONTENT tables keyed on
-- dungeon_id (no FK / no campaign_id — the dungeon id lives in
-- dungeon_entrances.dungeon_data JSON); purged dungeon-scoped in
-- CampaignRepository._campaign_scope_entries(). Room references ride as JSON int
-- arrays. FF-5 will ADD parent_faction_id + allegiance_kind to dungeon_factions.
-- ===========================================================================
CREATE TABLE IF NOT EXISTS dungeon_factions (
    id                        TEXT    PRIMARY KEY,
    dungeon_id                TEXT    NOT NULL,
    dungeon_level             INTEGER NOT NULL DEFAULT 1,
    name                      TEXT    NOT NULL DEFAULT '',
    species                   TEXT    NOT NULL DEFAULT '',
    secondary_species         TEXT    NOT NULL DEFAULT '[]',
    alignment                 TEXT    NOT NULL DEFAULT 'neutral'
        CHECK(alignment IN ('lawful', 'neutral', 'chaotic')),
    faction_type              TEXT    NOT NULL DEFAULT 'tribal',
    leader_npc_id             TEXT    NOT NULL DEFAULT '',
    leader_room_id            INTEGER NOT NULL DEFAULT -1,
    leader_hd                 REAL    NOT NULL DEFAULT 0,
    starting_population       INTEGER NOT NULL DEFAULT 0,
    current_population        INTEGER NOT NULL DEFAULT 0,
    patrol_size               TEXT    NOT NULL DEFAULT '1d4',
    members_on_patrol         INTEGER NOT NULL DEFAULT 0,
    lair_room_ids             TEXT    NOT NULL DEFAULT '[]',
    core_room_ids             TEXT    NOT NULL DEFAULT '[]',
    patrol_room_ids           TEXT    NOT NULL DEFAULT '[]',
    frontier_room_ids         TEXT    NOT NULL DEFAULT '[]',
    alert_state               TEXT    NOT NULL DEFAULT 'unaware'
        CHECK(alert_state IN ('unaware', 'cautious', 'alerted', 'mobilized')),
    default_reaction_modifier INTEGER NOT NULL DEFAULT 0,
    personality_weight_biases TEXT    NOT NULL DEFAULT '{}',
    morale_modifier           INTEGER NOT NULL DEFAULT 0,
    population_loss_percent    REAL    NOT NULL DEFAULT 0,
    created_at                TEXT    NOT NULL DEFAULT (datetime('now')),
    -- FF-5 (§9.1, migration 206): the additive link to the strategic factions
    -- registry. NULL parent + 'none' kind = unlinked = pre-FF-5 behaviour (§9.4).
    parent_faction_id         TEXT,
    allegiance_kind           TEXT    NOT NULL DEFAULT 'none'
);
CREATE INDEX IF NOT EXISTS idx_dungeon_factions_dungeon ON dungeon_factions(dungeon_id);

CREATE TABLE IF NOT EXISTS dungeon_faction_relationships (
    id                 TEXT PRIMARY KEY,
    dungeon_id         TEXT NOT NULL,
    faction_a_id       TEXT NOT NULL,
    faction_b_id       TEXT NOT NULL,
    relationship       TEXT NOT NULL DEFAULT 'neutral'
        CHECK(relationship IN ('allied', 'neutral', 'rival', 'hostile', 'vassal', 'unaware')),
    contested_room_ids TEXT NOT NULL DEFAULT '[]',
    notes              TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS idx_dungeon_faction_rel_dungeon
    ON dungeon_faction_relationships(dungeon_id);
CREATE INDEX IF NOT EXISTS idx_dungeon_faction_rel_pair
    ON dungeon_faction_relationships(faction_a_id, faction_b_id);

CREATE TABLE IF NOT EXISTS dungeon_solitary_threats (
    id               TEXT    PRIMARY KEY,
    dungeon_id       TEXT    NOT NULL,
    dungeon_level    INTEGER NOT NULL DEFAULT 1,
    room_id          INTEGER NOT NULL DEFAULT -1,
    monster_type     TEXT    NOT NULL DEFAULT '',
    hd               REAL    NOT NULL DEFAULT 0,
    alignment        TEXT    NOT NULL DEFAULT 'neutral',
    territory_radius INTEGER NOT NULL DEFAULT 1,
    tribute_from     TEXT    NOT NULL DEFAULT '[]',
    notes            TEXT    NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS idx_dungeon_solitary_threats_dungeon
    ON dungeon_solitary_threats(dungeon_id);

-- FF-5 (§9.3, migration 207): once-per-conflict-per-dungeon allegiance-pass cap
-- (§11.3). One row per (dungeon, conflict) already passed. Dungeon-CONTENT.
CREATE TABLE IF NOT EXISTS dungeon_link_conflict_passes (
    dungeon_id   TEXT    NOT NULL,
    conflict_id  TEXT    NOT NULL,
    faction_id   TEXT    NOT NULL DEFAULT '',
    decision     TEXT    NOT NULL DEFAULT '',
    passed_day   INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (dungeon_id, conflict_id)
);
CREATE INDEX IF NOT EXISTS idx_dungeon_link_conflict_passes_dungeon
    ON dungeon_link_conflict_passes(dungeon_id);


-- ===========================================================================
-- Setting-generation canonical data (migration 156)
-- ===========================================================================

-- Migration 156: Setting-generation canonical data (Stage 0 of the
-- pre-game setting-generation pipeline — docs/setting-generation-build-handoff.md).
--
-- These tables hold the permanent campaign world produced by the 8-layer
-- pipeline (generation/gdd-setting-generation.md §3; sim output contract §7.2).
-- They are written ONLY by engine/subsystems/generation/world/* during
-- campaign creation, frozen by the Layer-8 post-approval lock
-- (setting_parameters.is_locked), and read-only for all downstream systems
-- after the lock. They are deliberately separate from the play-time tables
-- (hex_maps / hex_cells / domains / realms): the play layer is materialized
-- FROM this canonical data at the party-creation handoff and may then evolve;
-- the canonical setting never changes.
--
-- Determinism note: all TEXT ids in these tables are DETERMINISTIC,
-- generation-assigned ids (pol_0001, evt_000123_004, ...), never
-- CampaignRepository.generate_id() — the §9.1 determinism hash test compares
-- two generation runs row-for-row, so random ids would break it.

-- Campaign parameters + seed (gdd-setting-generation.md §11.2; the full
-- slider vector is one canonical-JSON blob — same seed + same params_json
-- must reproduce the world bit-identically).
CREATE TABLE IF NOT EXISTS setting_parameters (
    campaign_id TEXT PRIMARY KEY REFERENCES campaigns(id),
    campaign_seed INTEGER NOT NULL,
    params_json TEXT NOT NULL DEFAULT '{}',
    pipeline_version INTEGER NOT NULL DEFAULT 1,
    is_locked INTEGER NOT NULL DEFAULT 0 CHECK(is_locked IN (0, 1)),
    world_hash TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- Per-24-mile-hex canonical data: Layer 1-2 terrain/climate plus the Layer-4
-- hex substrate of the sim output contract (§7.2). Enum CHECKs mirror
-- hex_cells / gdd-terrain-system.md §3 exactly.
CREATE TABLE IF NOT EXISTS setting_hexes (
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    q INTEGER NOT NULL,
    r INTEGER NOT NULL,
    -- Layer 1: geography
    elevation_raw REAL NOT NULL DEFAULT 0.0,
    elevation TEXT NOT NULL DEFAULT 'flat'
        CHECK(elevation IN ('flat', 'hills', 'mountains')),
    water TEXT NOT NULL DEFAULT ''
        CHECK(water IN ('', 'ocean', 'lake')),
    -- Layer 2: climate
    temperature REAL NOT NULL DEFAULT 0.0,
    precipitation REAL NOT NULL DEFAULT 0.0,
    effective_latitude REAL NOT NULL DEFAULT 0.0,
    koppen TEXT NOT NULL DEFAULT '',
    biome TEXT NOT NULL DEFAULT 'clear'
        CHECK(biome IN ('clear', 'woods', 'jungle', 'swamp', 'desert')),
    biome_subtype TEXT NOT NULL DEFAULT ''
        CHECK(biome_subtype IN (
            '',
            'forest_dense', 'forest_taiga',
            'mountains_volcanic', 'mountains_glacial',
            'clear_tundra', 'clear_savanna', 'clear_grassland',
            'clear_steppe', 'clear_scrub',
            'desert_badlands'
        )),
    original_biome TEXT NOT NULL DEFAULT '',
    -- Layer 4: sim substrate (history-sim §5; weights are JSON dicts
    -- culture_id/alignment -> float, sum 1.0 within tolerance)
    culture_weights TEXT NOT NULL DEFAULT '{}',
    alignment_weights TEXT NOT NULL DEFAULT '{}',
    population_band INTEGER NOT NULL DEFAULT 0,
    territory_class TEXT NOT NULL DEFAULT 'wilderness'
        CHECK(territory_class IN ('civilized', 'borderlands', 'wilderness')),
    owner_polity_id TEXT NOT NULL DEFAULT '',
    land_value INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (campaign_id, q, r)
);

-- Layer-1 river graph — a first-class output (region painting and the sim
-- both consume it). Same edge model as hex_river_edges
-- (gdd-terrain-system.md §3.6: canonical owner = lexicographically lower
-- (q, r); edge 0=N .. 5=NW), plus the generation-time width category
-- (gdd-setting-generation.md §4.4: each tributary junction steps the width).
CREATE TABLE IF NOT EXISTS setting_river_edges (
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    hex_q INTEGER NOT NULL,
    hex_r INTEGER NOT NULL,
    edge INTEGER NOT NULL CHECK(edge BETWEEN 0 AND 5),
    flow_clockwise INTEGER NOT NULL DEFAULT 0 CHECK(flow_clockwise IN (0, 1)),
    width_category TEXT NOT NULL DEFAULT 'stream'
        CHECK(width_category IN ('stream', 'creek', 'river', 'major_river')),
    navigability TEXT NOT NULL DEFAULT 'none'
        CHECK(navigability IN ('none', 'small_craft', 'river_craft', 'large_craft')),
    crossing TEXT NOT NULL DEFAULT 'none'
        CHECK(crossing IN ('none', 'bridge', 'ford', 'ferry')),
    PRIMARY KEY (campaign_id, hex_q, hex_r, edge)
);

-- Polities — every polity the history sim ever instantiated, surviving and
-- fallen (fell_tick NULL = survives to game-start). Fields per the §7.2
-- contract + history-sim §5. Hex membership is NOT duplicated here: a
-- surviving polity's hexes are setting_hexes rows with owner_polity_id = id;
-- a fallen polity's heartland is in setting_fallen_polities.
CREATE TABLE IF NOT EXISTS setting_polities (
    id TEXT NOT NULL,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    culture_id TEXT NOT NULL,
    alignment TEXT NOT NULL DEFAULT 'neutral'
        CHECK(alignment IN ('lawful', 'neutral', 'chaotic')),
    tier_index INTEGER NOT NULL DEFAULT 0 CHECK(tier_index BETWEEN 0 AND 6),
    title TEXT NOT NULL DEFAULT '',
    ruler_class TEXT NOT NULL DEFAULT '',
    ruler_level INTEGER NOT NULL DEFAULT 0,
    ruler_quality TEXT NOT NULL DEFAULT 'average'
        CHECK(ruler_quality IN ('strong', 'average', 'weak')),
    capital_q INTEGER NOT NULL DEFAULT 0,
    capital_r INTEGER NOT NULL DEFAULT 0,
    liege_id TEXT NOT NULL DEFAULT '',
    vassalized_by_war INTEGER NOT NULL DEFAULT 0 CHECK(vassalized_by_war IN (0, 1)),
    founded_tick INTEGER NOT NULL DEFAULT 0,
    fell_tick INTEGER,
    fade_onset_tick INTEGER,
    civ_or_clan_state TEXT NOT NULL DEFAULT 'civ'
        CHECK(civ_or_clan_state IN ('civ', 'clan')),
    garrison_coverage REAL NOT NULL DEFAULT 0.0,
    morale_seed TEXT NOT NULL DEFAULT '[]',
    internal_vassals TEXT NOT NULL DEFAULT '[]',
    name TEXT NOT NULL DEFAULT '',
    culture_synthesis_parents TEXT NOT NULL DEFAULT '[]',
    PRIMARY KEY (campaign_id, id)
);

-- Finalization decomposition (Realms/Titles refactor Phase 5; migration 170).
-- Each row is a vassal domain within a civ polity's own territory: the RAW 4-6
-- hierarchy (political_divisions_of_realms) decomposed to the 24-mile County floor —
-- one leaf per settled hex, interior grouping nodes for the Duchy+ tiers. liege_domain_id
-- = parent domain (''=under the polity ruler); polity_id = owning polity. id is
-- "dom_<q>_<r>" (leaf) or "idom_<q>_<r>_<depth>" (interior). Structure by the sim,
-- ruler_name/realm_name by Layer 5 naming. Beastman/clan polities are not decomposed.
CREATE TABLE IF NOT EXISTS setting_domains (
    id TEXT NOT NULL,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    polity_id TEXT NOT NULL,
    liege_domain_id TEXT NOT NULL DEFAULT '',
    tier_index INTEGER NOT NULL DEFAULT 0 CHECK(tier_index BETWEEN 0 AND 6),
    title TEXT NOT NULL DEFAULT '',
    ruler_class TEXT NOT NULL DEFAULT '',
    ruler_level INTEGER NOT NULL DEFAULT 0,
    ruler_name TEXT NOT NULL DEFAULT '',
    realm_name TEXT NOT NULL DEFAULT '',
    seat_q INTEGER NOT NULL DEFAULT 0,
    seat_r INTEGER NOT NULL DEFAULT 0,
    families INTEGER NOT NULL DEFAULT 0,
    hex_count INTEGER NOT NULL DEFAULT 0,
    depth INTEGER NOT NULL DEFAULT 0,
    is_personal_domain INTEGER NOT NULL DEFAULT 0 CHECK(is_personal_domain IN (0, 1)),
    PRIMARY KEY (campaign_id, id)
);

CREATE INDEX IF NOT EXISTS idx_setting_domains_polity
    ON setting_domains(campaign_id, polity_id);

-- Fallen-polity reaches for region painting (§7.2 fallen_polities[]):
-- the heartland hexes a polity held when it fell, plus its toponym root.
CREATE TABLE IF NOT EXISTS setting_fallen_polities (
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    polity_id TEXT NOT NULL,
    toponym_root TEXT NOT NULL DEFAULT '',
    hexes TEXT NOT NULL DEFAULT '[]',
    era_tick INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (campaign_id, polity_id)
);

-- Settlements-by-emergence (§7.2 settlements[]; market_class assigned by
-- Layer 6 reconciliation, name by Layer 5).
CREATE TABLE IF NOT EXISTS setting_settlements (
    id TEXT NOT NULL,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    hex_q INTEGER NOT NULL,
    hex_r INTEGER NOT NULL,
    polity_id TEXT NOT NULL DEFAULT '',
    urban_families INTEGER NOT NULL DEFAULT 0,
    emergence_tick INTEGER NOT NULL DEFAULT 0,
    is_capital INTEGER NOT NULL DEFAULT 0 CHECK(is_capital IN (0, 1)),
    market_class INTEGER NOT NULL DEFAULT 6 CHECK(market_class BETWEEN 1 AND 6),
    name TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (campaign_id, id)
);

-- Named non-political regions (gdd-region-painting.md §3.1). hexes is a JSON
-- [[q,r],...] membership list (ordered hex path for layer='road').
CREATE TABLE IF NOT EXISTS setting_regions (
    id TEXT NOT NULL,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    layer TEXT NOT NULL
        CHECK(layer IN ('continent', 'coastal_landform', 'terrain_cluster',
                        'hydronym', 'road', 'historical_cultural')),
    subtype TEXT NOT NULL DEFAULT '',
    scale TEXT NOT NULL DEFAULT 'campaign_24mi'
        CHECK(scale IN ('campaign_24mi', 'regional_6mi', 'local_15mi')),
    parent_id TEXT NOT NULL DEFAULT '',
    coarse_parent_region_id TEXT NOT NULL DEFAULT '',
    hexes TEXT NOT NULL DEFAULT '[]',
    overlaps TEXT NOT NULL DEFAULT '[]',
    name_primary TEXT NOT NULL DEFAULT '',
    name_culture_id TEXT NOT NULL DEFAULT '',
    name_origin TEXT NOT NULL DEFAULT ''
        CHECK(name_origin IN ('', 'descriptive', 'cultural', 'historical', 'hydronym_derived')),
    name_alternates TEXT NOT NULL DEFAULT '[]',
    significance REAL NOT NULL DEFAULT 0.0,
    source_event_id TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (campaign_id, id)
);

-- History event log (gdd-history-simulation.md §11.1; type enum verbatim).
CREATE TABLE IF NOT EXISTS setting_events (
    id TEXT NOT NULL,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    tick INTEGER NOT NULL,
    year_before_start INTEGER NOT NULL DEFAULT 0,
    type TEXT NOT NULL
        CHECK(type IN ('founding', 'expansion', 'war', 'conquest', 'vassalage',
                       'secession', 'pillage', 'schism', 'migration',
                       'collapse_rump', 'collapse_shatter', 'depopulation',
                       'golden_age', 'dynasty_change', 'alignment_drift',
                       'rebellion', 'rebellion_won', 'rebellion_concession',
                       'rebellion_crushed', 'rebellion_extinguished', 'razing',
                       'cultural_shift', 'protectorate')),
    polity_ids TEXT NOT NULL DEFAULT '[]',
    culture_ids TEXT NOT NULL DEFAULT '[]',
    hexes TEXT NOT NULL DEFAULT '[]',
    region_hint TEXT NOT NULL DEFAULT '',
    severity REAL NOT NULL DEFAULT 0.0,
    significance REAL NOT NULL DEFAULT 0.0,
    summary_key TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (campaign_id, id)
);

CREATE INDEX IF NOT EXISTS idx_setting_events_tick
    ON setting_events(campaign_id, tick);

-- Ruin/dungeon seeds with provenance (§7.2 ruin_seeds[];
-- gdd-setting-generation.md §9.3 — provenance-first).
CREATE TABLE IF NOT EXISTS setting_ruin_seeds (
    id TEXT NOT NULL,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    hex_q INTEGER NOT NULL,
    hex_r INTEGER NOT NULL,
    provenance_culture_id TEXT NOT NULL DEFAULT '',
    provenance_polity_id TEXT NOT NULL DEFAULT '',
    provenance_toponym TEXT NOT NULL DEFAULT '',
    era_tick INTEGER NOT NULL DEFAULT 0,
    event_type TEXT NOT NULL DEFAULT '',
    source_event_id TEXT NOT NULL DEFAULT '',
    size_hint TEXT NOT NULL DEFAULT 'lair'
        CHECK(size_hint IN ('lair', 'small', 'medium', 'large')),
    dungeon_type TEXT NOT NULL DEFAULT '',
    name TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (campaign_id, id)
);

-- Wilderness POI seeds (gdd-setting-generation.md §9.7; detail shape owned by
-- gdd-poi-generation.md — the type-specific mechanical skeleton and rumor
-- seeds are JSON so Stage 7 can fill them without schema churn).
CREATE TABLE IF NOT EXISTS setting_poi_seeds (
    id TEXT NOT NULL,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    hex_q INTEGER NOT NULL,
    hex_r INTEGER NOT NULL,
    poi_type TEXT NOT NULL DEFAULT '',
    context TEXT NOT NULL DEFAULT '{}',
    rumor_seeds TEXT NOT NULL DEFAULT '[]',
    name TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (campaign_id, id)
);

-- History-replay frames (§7.2 replay_frames[]; history-sim §15,
-- REPLAY_CADENCE = 4 ticks). Each *_by_hex is run-length encoded over the
-- canonical hex order (r ASC, then q ASC): runs of "value:count" joined by ';'
-- ('' value = none). owner_by_hex holds polity ownership; culture_by_hex the
-- dominant culture_id per hex; territory_by_hex the civ/borderlands/wilderness
-- class (migration 180) — so the replay animates political, culture AND
-- territory layers epoch by epoch, not just ownership. The palette is
-- per-campaign stable so a realm keeps its color across frames
-- (gdd-campaign-creation-ui.md §7).
CREATE TABLE IF NOT EXISTS setting_replay_frames (
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    tick INTEGER NOT NULL,
    owner_by_hex TEXT NOT NULL DEFAULT '',
    culture_by_hex TEXT NOT NULL DEFAULT '',
    territory_by_hex TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (campaign_id, tick)
);

-- seed_label (migration 180): a stable culture-seed identity per polity
-- ("Vallican_01") for the replay tooltip, so realms that never earn a proper
-- name still read as their seed culture rather than a bare pol id.
CREATE TABLE IF NOT EXISTS setting_replay_palette (
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    polity_id TEXT NOT NULL,
    color TEXT NOT NULL DEFAULT '',
    seed_label TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (campaign_id, polity_id)
);

-- StrategicDisposition strategic layer, one row per NPC ruler (migration 181;
-- gdd-ruler-ai.md §10, approved 2026-06-28; struct per gdd-npc-personality.md
-- §8.2). Derived — and regenerable — from characters.personality +
-- characters.alignment via StrategicDispositionBuilder. The 7 strategic-axis
-- ints snapshot the personality axes at build time; the 8 weights are the §8.3
-- derivation outputs (floats clamped 0-1). aggression_toward /
-- alliance_preference are serialized {realm_id: float} JSON dicts, '{}' when
-- realm relations are absent (gdd-ruler-ai.md §4.3 graceful degradation).
CREATE TABLE IF NOT EXISTS ruler_dispositions (
    character_id TEXT PRIMARY KEY REFERENCES characters(id),
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    motivation_primary TEXT NOT NULL DEFAULT '',
    motivation_secondary TEXT NOT NULL DEFAULT '',
    epistemic_curiosity INTEGER NOT NULL DEFAULT 5,
    societal_orthodoxy INTEGER NOT NULL DEFAULT 5,
    affective_compassion INTEGER NOT NULL DEFAULT 5,
    stress_reactivity INTEGER NOT NULL DEFAULT 5,
    self_interest INTEGER NOT NULL DEFAULT 5,
    in_group_loyalty INTEGER NOT NULL DEFAULT 5,
    mysticism INTEGER NOT NULL DEFAULT 5,
    research_weight REAL NOT NULL DEFAULT 0.0,
    religious_weight REAL NOT NULL DEFAULT 0.0,
    economic_weight REAL NOT NULL DEFAULT 0.0,
    military_weight REAL NOT NULL DEFAULT 0.0,
    expansion_weight REAL NOT NULL DEFAULT 0.0,
    fortification_weight REAL NOT NULL DEFAULT 0.0,
    diplomatic_weight REAL NOT NULL DEFAULT 0.0,
    oppression_weight REAL NOT NULL DEFAULT 0.0,
    crisis_response TEXT NOT NULL DEFAULT 'defensive'
        CHECK(crisis_response IN ('aggressive', 'defensive', 'diplomatic', 'cautious')),
    aggression_toward TEXT NOT NULL DEFAULT '{}',
    alliance_preference TEXT NOT NULL DEFAULT '{}',
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_ruler_dispositions_campaign
    ON ruler_dispositions(campaign_id);

-- Migration 182: ruler_ai_state — per-ruler planner runtime state, one row per
-- NPC ruler the Regional-LOD system has ever activated (gdd-ruler-ai.md §10,
-- approved by Jedidiah 2026-06-28). Persists what the Phase-3 in-memory LOD
-- cache could not: the ruler's current LOD tier (§8.1 'active'/'backdrop') for
-- save/load reconciliation, the §8.2 demotion grace stamp (demotion_pending_day
-- is the calendar day the ruler LEFT the play window's geometry; NULL when not
-- pending — the ruler stays active until ~1 month elapses or it re-enters),
-- the last strategic turn taken (day + top-scored action id, written by
-- RulerAI.process_campaign_month), and a small {cache_key: entry} JSON
-- narration cache so Seam-A retroactive narration is not regenerated for the
-- same (day, action) — gdd-ruler-ai.md §9.1. Derived runtime state: a
-- drop-and-rebuild loses only narration cache and grace stamps (the next
-- RulerLodManager.sync regenerates tiers), so it is non-destructive in practice.
CREATE TABLE IF NOT EXISTS ruler_ai_state (
    character_id TEXT PRIMARY KEY REFERENCES characters(id),
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    lod_tier TEXT NOT NULL DEFAULT 'backdrop'
        CHECK(lod_tier IN ('active', 'backdrop')),
    last_strategic_turn_day INTEGER NOT NULL DEFAULT 0,
    last_action_id TEXT NOT NULL DEFAULT '',
    demotion_pending_day INTEGER,
    narration_cache TEXT NOT NULL DEFAULT '{}',
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_ruler_ai_state_campaign
    ON ruler_ai_state(campaign_id);

-- ===========================================================================
-- Faction Framework FF-1 (migrations 188-189 / gdd-faction-framework.md §4)
-- Reference snapshot of the new §4 tables. The factions / faction_memberships
-- ALTER columns (§4.1, §4.4) appear inline in their table definitions above.
-- No new PoI column: §4.7 reuses the existing settlement_pois.owner_faction_id
-- and pois.faction_id as the "controlling faction" linkage.
-- ===========================================================================

CREATE TABLE IF NOT EXISTS faction_stances (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    faction_a_id TEXT NOT NULL REFERENCES factions(id),
    faction_b_id TEXT NOT NULL REFERENCES factions(id),
    public_stance TEXT NOT NULL DEFAULT 'neutral'
        CHECK(public_stance IN ('hostile', 'unfriendly', 'neutral', 'indifferent', 'friendly', 'allied')),
    true_stance TEXT
        CHECK(true_stance IS NULL OR true_stance IN ('hostile', 'unfriendly', 'neutral', 'indifferent', 'friendly', 'allied')),
    betrayal_condition TEXT,
    stance_reason TEXT NOT NULL DEFAULT '',
    grievance_score INTEGER NOT NULL DEFAULT 0,
    last_evaluated_day INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_faction_stances_pair
    ON faction_stances(faction_a_id, faction_b_id);
CREATE INDEX IF NOT EXISTS idx_faction_stances_campaign
    ON faction_stances(campaign_id);

CREATE TABLE IF NOT EXISTS treaties (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    kind TEXT NOT NULL
        CHECK(kind IN ('alliance', 'defensive_pact', 'non_aggression', 'protectorate', 'trade_pact')),
    realm_a_id TEXT NOT NULL REFERENCES realms(id),
    realm_b_id TEXT NOT NULL REFERENCES realms(id),
    terms TEXT NOT NULL DEFAULT '{}',
    signed_day INTEGER NOT NULL DEFAULT 0,
    duration_months INTEGER,
    status TEXT NOT NULL DEFAULT 'active'
        CHECK(status IN ('active', 'expired', 'renewed', 'broken', 'dissolved')),
    broken_by_realm_id TEXT REFERENCES realms(id),
    broken_day INTEGER,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_treaties_campaign
    ON treaties(campaign_id);
CREATE INDEX IF NOT EXISTS idx_treaties_pair
    ON treaties(realm_a_id, realm_b_id, status);

CREATE TABLE IF NOT EXISTS faction_events (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    day INTEGER NOT NULL DEFAULT 0,
    actor_faction_id TEXT NOT NULL REFERENCES factions(id),
    target_faction_id TEXT NOT NULL REFERENCES factions(id),
    kind TEXT NOT NULL,
    magnitude INTEGER NOT NULL DEFAULT 0,
    data TEXT NOT NULL DEFAULT '{}',
    expires_day INTEGER,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_faction_events_campaign
    ON faction_events(campaign_id);
CREATE INDEX IF NOT EXISTS idx_faction_events_pair
    ON faction_events(actor_faction_id, target_faction_id);

CREATE TABLE IF NOT EXISTS faction_plots (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    kind TEXT NOT NULL
        CHECK(kind IN ('rebellion', 'defection', 'betrayal', 'coup')),
    instigator_faction_id TEXT NOT NULL REFERENCES factions(id),
    target_faction_id TEXT REFERENCES factions(id),
    secrecy INTEGER NOT NULL DEFAULT 10,
    launch_condition TEXT NOT NULL DEFAULT '{}',
    status TEXT NOT NULL DEFAULT 'brewing'
        CHECK(status IN ('brewing', 'recruiting', 'ready', 'launched', 'exposed', 'abandoned', 'resolved')),
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_faction_plots_campaign
    ON faction_plots(campaign_id);

CREATE TABLE IF NOT EXISTS faction_plot_members (
    plot_id TEXT NOT NULL REFERENCES faction_plots(id),
    faction_id TEXT NOT NULL REFERENCES factions(id),
    commitment TEXT NOT NULL DEFAULT 'committed'
        CHECK(commitment IN ('committed', 'sympathetic', 'informant')),
    joined_day INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (plot_id, faction_id)
);

CREATE TABLE IF NOT EXISTS realm_petitions (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    petitioner_domain_id TEXT NOT NULL REFERENCES domains(id),
    liege_domain_id TEXT REFERENCES domains(id),
    kind TEXT NOT NULL
        CHECK(kind IN ('release', 'transfer', 'appeal')),
    status TEXT NOT NULL DEFAULT 'filed'
        CHECK(status IN ('filed', 'granted', 'refused', 'bought_off', 'escalated', 'withdrawn')),
    filed_day INTEGER NOT NULL DEFAULT 0,
    resolved_day INTEGER,
    terms TEXT NOT NULL DEFAULT '{}',
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_realm_petitions_campaign
    ON realm_petitions(campaign_id);

CREATE TABLE IF NOT EXISTS domain_tithe_shares (
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    domain_id TEXT NOT NULL REFERENCES domains(id),
    faction_id TEXT NOT NULL REFERENCES factions(id),
    share_pct INTEGER NOT NULL DEFAULT 0,
    set_day INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (domain_id, faction_id)
);
CREATE INDEX IF NOT EXISTS idx_domain_tithe_shares_campaign
    ON domain_tithe_shares(campaign_id);

-- ===========================================================================
-- Faction Framework FF-4: divided-loyalty conflicts (§8.4, migration 198).
-- A persisted party-loyalty conflict so a re-scan does not re-emit an already-
-- known conflict (dedup on the deterministic `signature`) and so resolution /
-- double-agent status has a home. Detected by DividedLoyaltyDetector; campaign-
-- scoped LEAF table (registered in CampaignRepository._SCOPE_DIRECT_CAMPAIGN).
-- ===========================================================================
CREATE TABLE IF NOT EXISTS party_loyalty_conflicts (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    cause TEXT NOT NULL
        CHECK(cause IN ('mutual_hostile_memberships', 'opposite_conflict_sides',
                        'obligation_targets_faction')),
    signature TEXT NOT NULL,
    member_a_id TEXT NOT NULL,
    member_b_id TEXT,
    faction_a_id TEXT NOT NULL,
    faction_b_id TEXT NOT NULL,
    conflict_ref TEXT,
    status TEXT NOT NULL DEFAULT 'detected'
        CHECK(status IN ('detected', 'surfaced', 'resolved', 'double_agent')),
    detected_day INTEGER NOT NULL DEFAULT 0,
    resolved_day INTEGER,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now')),
    UNIQUE(campaign_id, signature)
);
CREATE INDEX IF NOT EXISTS idx_party_loyalty_conflicts_campaign
    ON party_loyalty_conflicts(campaign_id);

-- ===========================================================================
-- Dialogue subsystem (Phase 1) — NPC memory data model (migration 191).
-- generation/gdd-npc-dialogue.md §8.1 / §15. Three campaign-scoped LEAF tables:
--   npc_relationships (Layer 1, mechanical spine), npc_memories (Layer 2,
--   episodic), npc_issues (Layer 3 / Track 2, landed now, consumed Phase 3).
-- Registered in CampaignRepository._SCOPE_DIRECT_CAMPAIGN's Dialogue block.
-- ===========================================================================

CREATE TABLE IF NOT EXISTS npc_relationships (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL,
    npc_id TEXT NOT NULL,
    party_id TEXT NOT NULL,
    attitude TEXT NOT NULL DEFAULT 'neutral'
        CHECK(attitude IN ('hostile','unfriendly','neutral','indifferent','friendly','fearful','cowed')),
    is_intimidated INTEGER NOT NULL DEFAULT 0,
    influence_attempt_count INTEGER NOT NULL DEFAULT 0,       -- Track 1 (tone) ladder counter only
    next_attempt_available_at INTEGER NOT NULL DEFAULT 0,     -- absolute rounds, tone-track
    favors_owed_to_party INTEGER NOT NULL DEFAULT 0,
    favors_owed_by_party INTEGER NOT NULL DEFAULT 0,
    first_met_day INTEGER,
    last_interaction_day INTEGER,
    role_tags TEXT NOT NULL DEFAULT '[]',      -- JSON: "employer","quest_giver","rival","victim"...
    UNIQUE(campaign_id, npc_id, party_id)
);

CREATE TABLE IF NOT EXISTS npc_memories (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL,
    npc_id TEXT NOT NULL,
    party_id TEXT,
    kind TEXT NOT NULL CHECK(kind IN
        ('conversation','event','promise','debt','grudge','gift','deception_by_npc','deception_suffered')),
    summary TEXT NOT NULL,
    facts TEXT NOT NULL DEFAULT '[]',
    attitude_after TEXT,
    importance INTEGER NOT NULL DEFAULT 1,      -- 1..5
    created_day INTEGER NOT NULL,
    last_recalled_day INTEGER,
    source_session_id TEXT
);
CREATE INDEX IF NOT EXISTS idx_npc_memories_recall
    ON npc_memories(campaign_id, npc_id, importance DESC, created_day DESC);

CREATE TABLE IF NOT EXISTS npc_issues (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL,
    npc_id TEXT NOT NULL,
    party_id TEXT NOT NULL,
    issue_key TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'open'
        CHECK(status IN ('open','granted','refused','withdrawn','expired')),
    last_result TEXT,
    attempt_count INTEGER NOT NULL DEFAULT 0,
    next_attempt_available_at INTEGER NOT NULL DEFAULT 0,
    terms TEXT NOT NULL DEFAULT '{}',
    offense_fired INTEGER NOT NULL DEFAULT 0,
    created_day INTEGER NOT NULL,
    resolved_day INTEGER,
    UNIQUE(campaign_id, npc_id, party_id, issue_key)
);

-- =============================================================================
-- Quest & Rumor system (Session Q-1) — migration 192
-- generation/gdd-quest-rumor-system.md §12. Seed layer (setting_quests,
-- setting_rumors) mirrors setting_poi_seeds' PRIMARY KEY (campaign_id, id)
-- convention. Runtime layer (quests, quest_rewards, domain_grants, rumors,
-- rumor_settlement_pool) uses CampaignRepository.generate_id() hex ids.
-- =============================================================================

CREATE TABLE IF NOT EXISTS setting_quests (
    id TEXT NOT NULL,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    questgiver_npc_id TEXT NOT NULL DEFAULT '',
    questgiver_faction_id TEXT REFERENCES factions(id),
    threat_type TEXT NOT NULL DEFAULT '' CHECK(threat_type IN (
        'monster_lair', 'dungeon', 'brigand', 'creature_bounty', 'recovery',
        'escort', 'delivery', 'domain_conquest', 'reconnaissance', 'faction_goal')),
    threat_source_id TEXT NOT NULL DEFAULT '',
    threat_hex TEXT NOT NULL DEFAULT '',
    completion_type TEXT NOT NULL DEFAULT '' CHECK(completion_type IN (
        'clear_dungeon', 'clear_lair', 'kill_target', 'retrieve_item',
        'escort_npc', 'deliver_item', 'hold_territory', 'scout_hex',
        'build_structure', 'faction_goal')),
    completion_target_id TEXT NOT NULL DEFAULT '',
    reward TEXT NOT NULL DEFAULT '{}',
    posting_type TEXT NOT NULL DEFAULT 'posted'
        CHECK(posting_type IN ('personal', 'posted', 'broadcast')),
    posting_range INTEGER NOT NULL DEFAULT 8,
    expires_day INTEGER,
    description_placeholder TEXT NOT NULL DEFAULT '',
    questgiver_dialogue_placeholder TEXT NOT NULL DEFAULT '',
    completion_dialogue_placeholder TEXT NOT NULL DEFAULT '',
    title_placeholder TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (campaign_id, id)
);

CREATE TABLE IF NOT EXISTS setting_rumors (
    id TEXT NOT NULL,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    source_type TEXT NOT NULL DEFAULT '' CHECK(source_type IN (
        'poi', 'dungeon', 'lair', 'political', 'settlement', 'npc',
        'quest', 'historical')),
    source_id TEXT NOT NULL DEFAULT '',
    source_quest_id TEXT REFERENCES setting_quests(id),
    content_hint TEXT NOT NULL DEFAULT '',
    accuracy TEXT NOT NULL DEFAULT 'true' CHECK(accuracy IN (
        'true', 'exaggerated', 'understated', 'misleading', 'false')),
    accuracy_detail TEXT NOT NULL DEFAULT '',
    knowledge_category TEXT NOT NULL DEFAULT 'local' CHECK(knowledge_category IN (
        'local', 'professional', 'political', 'criminal', 'religious',
        'military', 'dungeon', 'personal', 'historical')),
    origin_hex TEXT NOT NULL DEFAULT '',
    settlement_range INTEGER NOT NULL DEFAULT 5,
    min_npc_tier TEXT NOT NULL DEFAULT 'C' CHECK(min_npc_tier IN ('C', 'B', 'A')),
    freshness TEXT NOT NULL DEFAULT 'current' CHECK(freshness IN (
        'persistent', 'current', 'stale')),
    narrated_placeholder TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (campaign_id, id)
);

CREATE INDEX IF NOT EXISTS idx_setting_quests_campaign ON setting_quests(campaign_id);
CREATE INDEX IF NOT EXISTS idx_setting_rumors_campaign ON setting_rumors(campaign_id);
CREATE INDEX IF NOT EXISTS idx_setting_rumors_source_quest ON setting_rumors(source_quest_id);

CREATE TABLE IF NOT EXISTS quests (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    status TEXT NOT NULL DEFAULT 'available' CHECK(status IN (
        'available', 'accepted', 'completed', 'failed', 'expired', 'abandoned')),
    questgiver_id TEXT REFERENCES characters(id),
    questgiver_faction_id TEXT REFERENCES factions(id),
    questgiver_settlement_id TEXT REFERENCES settlement_entrances(id),
    questgiver_motivation TEXT NOT NULL DEFAULT '',
    threat_type TEXT NOT NULL DEFAULT '' CHECK(threat_type IN (
        'monster_lair', 'dungeon', 'brigand', 'creature_bounty', 'recovery',
        'escort', 'delivery', 'domain_conquest', 'reconnaissance', 'faction_goal')),
    threat_source_id TEXT NOT NULL DEFAULT '',
    threat_hex TEXT NOT NULL DEFAULT '',
    threat_description_hint TEXT NOT NULL DEFAULT '',
    completion_type TEXT NOT NULL DEFAULT '' CHECK(completion_type IN (
        'clear_dungeon', 'clear_lair', 'kill_target', 'retrieve_item',
        'escort_npc', 'deliver_item', 'hold_territory', 'scout_hex',
        'build_structure', 'faction_goal')),
    completion_target_id TEXT NOT NULL DEFAULT '',
    completion_verified_by TEXT NOT NULL DEFAULT 'automatic'
        CHECK(completion_verified_by IN ('questgiver_report', 'automatic', 'witness')),
    is_complete INTEGER NOT NULL DEFAULT 0 CHECK(is_complete IN (0, 1)),
    progress TEXT NOT NULL DEFAULT '{}',
    title TEXT NOT NULL DEFAULT '',
    description TEXT NOT NULL DEFAULT '',
    questgiver_dialogue TEXT NOT NULL DEFAULT '',
    completion_dialogue TEXT NOT NULL DEFAULT '',
    posting_type TEXT NOT NULL DEFAULT 'posted'
        CHECK(posting_type IN ('personal', 'posted', 'broadcast')),
    posting_range INTEGER NOT NULL DEFAULT 8,
    created_day INTEGER NOT NULL DEFAULT 0,
    expires_day INTEGER,
    accepted_day INTEGER,
    completed_day INTEGER,
    accepting_pc_id TEXT REFERENCES characters(id),
    reward_recipient_pc_id TEXT REFERENCES characters(id),
    faction_goal_id TEXT NOT NULL DEFAULT ''
);

CREATE INDEX IF NOT EXISTS idx_quests_campaign ON quests(campaign_id);
CREATE INDEX IF NOT EXISTS idx_quests_status ON quests(status);
CREATE INDEX IF NOT EXISTS idx_quests_questgiver_settlement ON quests(questgiver_settlement_id);
CREATE INDEX IF NOT EXISTS idx_quests_threat_hex ON quests(threat_hex);
CREATE INDEX IF NOT EXISTS idx_quests_threat_type ON quests(threat_type);
CREATE INDEX IF NOT EXISTS idx_quests_questgiver_faction ON quests(questgiver_faction_id);

CREATE TABLE IF NOT EXISTS quest_rewards (
    id TEXT PRIMARY KEY,
    quest_id TEXT NOT NULL REFERENCES quests(id),
    reward_type TEXT NOT NULL DEFAULT 'gold'
        CHECK(reward_type IN ('gold', 'item', 'domain', 'political', 'mixed')),
    gold_value INTEGER NOT NULL DEFAULT 0,
    item_id TEXT NOT NULL DEFAULT '',
    item_description TEXT NOT NULL DEFAULT '',
    domain_grant_id TEXT REFERENCES domain_grants(id),
    political_favor TEXT NOT NULL DEFAULT '',
    total_gp_value INTEGER NOT NULL DEFAULT 0,
    xp_eligible INTEGER NOT NULL DEFAULT 1 CHECK(xp_eligible IN (0, 1)),
    variance_applied REAL NOT NULL DEFAULT 0.0
);

CREATE INDEX IF NOT EXISTS idx_quest_rewards_quest ON quest_rewards(quest_id);

CREATE TABLE IF NOT EXISTS domain_grants (
    id TEXT PRIMARY KEY,
    quest_reward_id TEXT NOT NULL REFERENCES quest_rewards(id),
    hex_ids TEXT NOT NULL DEFAULT '[]',
    territory_class TEXT NOT NULL DEFAULT 'wilderness'
        CHECK(territory_class IN ('civilized', 'borderlands', 'wilderness')),
    estimated_families INTEGER NOT NULL DEFAULT 0,
    stronghold_present INTEGER NOT NULL DEFAULT 0 CHECK(stronghold_present IN (0, 1)),
    stronghold_value INTEGER NOT NULL DEFAULT 0,
    vassal_obligations TEXT NOT NULL DEFAULT '{}',
    title_granted TEXT NOT NULL DEFAULT '',
    single_owner_pc_id TEXT REFERENCES characters(id)
);

CREATE INDEX IF NOT EXISTS idx_domain_grants_quest_reward ON domain_grants(quest_reward_id);

CREATE TABLE IF NOT EXISTS rumors (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES campaigns(id),
    source_type TEXT NOT NULL DEFAULT '' CHECK(source_type IN (
        'poi', 'dungeon', 'lair', 'political', 'settlement', 'npc',
        'quest', 'historical')),
    source_id TEXT NOT NULL DEFAULT '',
    source_quest_id TEXT REFERENCES quests(id),
    content_hint TEXT NOT NULL DEFAULT '',
    narrated_text TEXT NOT NULL DEFAULT '',
    accuracy TEXT NOT NULL DEFAULT 'true' CHECK(accuracy IN (
        'true', 'exaggerated', 'understated', 'misleading', 'false')),
    accuracy_detail TEXT NOT NULL DEFAULT '',
    knowledge_category TEXT NOT NULL DEFAULT 'local' CHECK(knowledge_category IN (
        'local', 'professional', 'political', 'criminal', 'religious',
        'military', 'dungeon', 'personal', 'historical')),
    origin_hex TEXT NOT NULL DEFAULT '',
    settlement_range INTEGER NOT NULL DEFAULT 5,
    min_npc_tier TEXT NOT NULL DEFAULT 'C' CHECK(min_npc_tier IN ('C', 'B', 'A')),
    freshness TEXT NOT NULL DEFAULT 'current' CHECK(freshness IN (
        'persistent', 'current', 'stale')),
    known_to_party INTEGER NOT NULL DEFAULT 0 CHECK(known_to_party IN (0, 1)),
    verified INTEGER NOT NULL DEFAULT 0 CHECK(verified IN (0, 1)),
    first_heard_day INTEGER,
    created_day INTEGER NOT NULL DEFAULT 0,
    expires_day INTEGER
);

CREATE INDEX IF NOT EXISTS idx_rumors_campaign ON rumors(campaign_id);
CREATE INDEX IF NOT EXISTS idx_rumors_source_id ON rumors(source_id);
CREATE INDEX IF NOT EXISTS idx_rumors_origin_hex ON rumors(origin_hex);
CREATE INDEX IF NOT EXISTS idx_rumors_knowledge_category ON rumors(knowledge_category);
CREATE INDEX IF NOT EXISTS idx_rumors_freshness ON rumors(freshness);
CREATE INDEX IF NOT EXISTS idx_rumors_source_quest ON rumors(source_quest_id);

CREATE TABLE IF NOT EXISTS rumor_settlement_pool (
    rumor_id TEXT NOT NULL REFERENCES rumors(id),
    settlement_id TEXT NOT NULL REFERENCES settlement_entrances(id),
    PRIMARY KEY (rumor_id, settlement_id)
);

CREATE INDEX IF NOT EXISTS idx_rumor_settlement_pool_settlement ON rumor_settlement_pool(settlement_id);

-- ===========================================================================
-- Faction FF-3: realm diplomacy & rebellion (migration 193)
-- Doc-sync copies of the ALTER TABLE ADD COLUMN statements in
-- db/migrations/193_faction_ff3_realm_diplomacy.sql. schema.sql is a
-- documentation snapshot (the runtime DB is built from migrations only); these
-- ALTERs are appended here (not inlined into the FF-1 CREATE TABLE blocks) to
-- keep the parallel-track merge mechanical. See §5.3 / §5.7 of the GDD.
-- ===========================================================================
ALTER TABLE vassal_assignments ADD COLUMN compliance_behavior TEXT NOT NULL DEFAULT 'full_compliance'
    CHECK(compliance_behavior IN (
        'over_compliance', 'full_compliance', 'under_compliance',
        'resignation_seeking', 'rebellious'));
ALTER TABLE faction_plots ADD COLUMN ready_since_day INTEGER NOT NULL DEFAULT 0;

-- ===========================================================================
-- Vassal loyalty dice carryover (migration 194)
-- Doc-sync copy of db/migrations/194_vassal_loyalty_dice_carryover.sql. RAW
-- §2.2 Fanatic/Grudging carryover state on the liege<->vassal edge, mirroring
-- henchman_state.is_fanatic / is_grudging. See rules/acore_equipment.xml:806-808.
-- ===========================================================================
ALTER TABLE vassal_assignments ADD COLUMN loyalty_is_fanatic INTEGER NOT NULL DEFAULT 0
    CHECK(loyalty_is_fanatic IN (0, 1));
ALTER TABLE vassal_assignments ADD COLUMN loyalty_grudging_pending INTEGER NOT NULL DEFAULT 0
    CHECK(loyalty_grudging_pending IN (0, 1));

